const a=[{id:"common-risk-factors-in-the-returns-on-stocks-and-bonds",title:"Common risk factors in the returns on stocks and bonds",titleZh:"股票与债券收益中的共同风险因子",sourceTitle:"Common risk factors in the returns on stocks and bonds",authors:"Eugene F. Fama · Kenneth R. French",venue:"Journal of Financial Economics",year:"1993",kind:"paper",topic:"asset-pricing",data:"returns · fundamentals · portfolios",dataZh:"收益；基本面；组合构造",summary:{en:"Examines how market, size, value, term, and default factors relate to stock and bond returns.",zh:"研究市场、规模、价值、期限与违约等因素如何与股票及债券收益相关。"},related:{datasets:["cn-equity-daily","cn-pit-fundamentals"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/0304-405x(93)90023-5"}],readingNotes:[{title:{zh:"为什么把股票与债券放在一起？",en:"Why bring stocks and bonds together?"},body:{zh:"这篇论文问的不是哪只股票会涨，而是不同资产的收益能否由少数共同变化解释。作者把股票、政府债券和公司债券放进同一框架：如果市场相互联系，解释股票的变量与解释债券的变量可能有交集。",en:"The question is whether a small set of shared movements helps explain returns across assets, not which security will rise. Fama and French study stocks alongside government and corporate bonds, asking whether connected markets also share sources of return variation."}},{title:{zh:"债券因子是收益差，不是收益率差",en:"Bond factors are return differences, not yield spreads"},body:{zh:"论文的TERM用长期国债月收益减去上月末已知的一月期国库券利率；DEF用长期公司债组合收益减去长期国债收益。这两个定义都依赖持有期回报，不能直接用两条到期收益率相减替代。债券价格、期限与回报口径需要先核对。",en:"TERM subtracts the previously observed one-month bill rate from the monthly long-government-bond return. DEF subtracts the long-government-bond return from the long-corporate-bond portfolio return. These are holding-period return constructions, not interchangeable with differences between quoted yields. Price, tenor and return conventions matter."},reference:{url:"https://www.bauer.uh.edu/rsusmel/phd/Fama-French_JFE93.pdf",label:{zh:"原文第2.1.1节：债券市场因子",en:"Original §2.1.1: bond-market factors"}}},{title:{zh:"从公司特征到共同因子",en:"From characteristics to common factors"},body:{zh:"作者用月度时间序列回归，把资产超额收益与市场、规模、账面市值比，以及期限和违约相关的组合收益联系起来。公司规模是一个特征；对规模组合收益的敏感度是回归系数。阅读时应把两者分开。",en:"Time-series regressions relate monthly excess returns to the market, size, book-to-market, term and default-related portfolio returns. A firm's size is a characteristic; its loading on a size-related return series is a regression coefficient. Keeping those concepts separate is central to reading the paper."}},{title:{zh:"解释共同波动，不等于解释全部收益",en:"Two different tests of explanation"},body:{zh:"论文同时关注共同波动与平均收益：前者看因子能解释多少随时间的变化，后者看超额收益回归的截距是否仍明显偏离零。作者报告股票的三个因子与债券的两个因子具有解释力，但这不表示任何资产、任何时期都没有剩余差异。",en:"Shared variation and average returns are different tests. Loadings and fit describe co-movement; intercepts assess unexplained average excess returns. The authors report explanatory roles for three stock-market and two bond-market factors, without establishing universal coverage of every asset or period."}},{title:{zh:"分组断点来自哪个市场？",en:"Which market supplies the sorting breakpoints?"},body:{zh:"规模分组以纽约证交所股票的市值中位数为断点，再应用于包含Amex与Nasdaq的样本；账面市值比分组也采用纽约证交所的30%和70%断点。因此小股票组不等于全样本数量的一半，也不代表市值的一半。更换断点市场会改变组合，不能把同名排序当成完全相同的研究设计。",en:"The NYSE median capitalization splits size groups across the wider NYSE, Amex and Nasdaq sample; NYSE 30th and 70th percentiles also determine book-to-market groups. The small group is therefore neither half of all stocks nor half of aggregate capitalization. Changing the breakpoint universe changes the portfolios even when the sorting labels remain identical."},reference:{url:"https://www.bauer.uh.edu/rsusmel/phd/Fama-French_JFE93.pdf",label:{zh:"原文第2.1.2节：六个组合的分组断点",en:"Original §2.1.2: breakpoints for six portfolios"}}},{title:{zh:"带着什么问题继续读？",en:"A useful reading question"},body:{zh:"先读因子组合如何构造，再看回归截距，不要只看拟合优度。准备对应数据时，记录市场范围、无风险利率、财务信息可得日期和组合重建规则。1993年文中的五个跨资产因子，也不是后来加入盈利与投资的股票五因子模型。",en:"Read portfolio construction before interpreting intercepts or fit. For data preparation, record the market universe, risk-free benchmark, accounting availability and reconstitution rules. The five cross-asset factors here are not the later equity five-factor model that adds profitability and investment."}}],readerLimits:{zh:"历史美国样本中的解释力，不证明当前市场溢价或可交易收益；样本、交易成本和制度背景需要另行评估。",en:"Historical US explanatory power does not establish a current premium or executable return; sample construction, costs and institutions require separate assessment."}},{id:"returns-to-buying-winners-and-selling-losers-implications-for-stock-market-efficiency",title:"Returns to Buying Winners and Selling Losers: Implications for Stock Market Efficiency",titleZh:"买入赢家与卖出输家：市场效率研究",sourceTitle:"Returns to Buying Winners and Selling Losers: Implications for Stock Market Efficiency",authors:"NARASIMHAN JEGADEESH · SHERIDAN TITMAN",venue:"The Journal of Finance",year:"1993",kind:"paper",topic:"quant-methods",data:"daily prices · adjusted returns",dataZh:"日价格；复权收益；形成期与持有期",summary:{en:"Studies return persistence through portfolios formed from prior winners and losers.",zh:"通过历史赢家与输家组合，研究收益的延续性及其市场效率含义。"},related:{recipes:["pit-fundamentals-panel","adjusted-price-series"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/j.1540-6261.1993.tb04702.x"}]},{id:"continuous-auctions-and-insider-trading",title:"Continuous Auctions and Insider Trading",titleZh:"连续竞价与知情交易",sourceTitle:"Continuous Auctions and Insider Trading",authors:"Albert S. Kyle",venue:"Econometrica",year:"1985",kind:"paper",topic:"market-microstructure",data:"trades · quotes · volume",dataZh:"成交；报价；成交量",summary:{en:"Models how private information, order flow, and market-maker pricing interact in continuous auctions.",zh:"建模分析连续竞价中私人信息、订单流与做市定价之间的关系。"},related:{datasets:["cn-equity-minute"],features:["liquidity-measures"]},sources:[{label:"DOI",url:"https://doi.org/10.2307/1913210"}],readingNotes:[{title:{zh:"价格怎样逐步吸收私人信息？",en:"How does private information enter prices?"},body:{zh:"Kyle研究一个知情交易者不会一次性暴露全部信息的市场。价格如何在连续交易中逐渐反映信息，取决于知情者的交易选择，以及做市者从订单流中能推断出多少。",en:"Kyle studies a market in which an informed trader need not reveal information all at once. Price discovery depends on the trader's order choices and on what market makers can infer from the resulting order flow."}},{title:{zh:"每次拍卖先提交数量，再确定价格",en:"Quantities precede pricing in each auction"},body:{zh:"模型中知情者与噪声交易者先同时选择数量，做市者随后观察合并后的订单流并定价。做市者看不到两类交易的单独数量，知情者下单时也不知道当次噪声订单。把这些信息集合分清，才能理解噪声为何掩护私人信息，以及价格为何随订单流更新。",en:"The insider and noise traders choose quantities simultaneously; market makers then observe combined order flow and set a price. Makers cannot separate the two components, and the insider does not know the current noise order when choosing a quantity. These information sets explain both concealment and price updating."},reference:{url:"https://people.duke.edu/~qc2/BA532/1985%20EMA%20Kyle.pdf",label:{zh:"原文第1节：两步拍卖与信息集合",en:"Original §1: two-step auction and information sets"}}},{title:{zh:"三个角色构成一个机制",en:"Three roles, one mechanism"},body:{zh:"模型包含单一风险中性的知情者、随机噪声交易者和竞争性的风险中性做市者。噪声交易让知情交易混入普通订单，做市者则根据观察到的交易更新价格。缺少这些角色和假设，就不能把任何成交量变化都叫作模型中的信息交易。",en:"The model contains one risk-neutral insider, random noise traders and competitive risk-neutral market makers. Noise trading conceals informed orders, while market makers update prices from observed flow. These roles and assumptions are not interchangeable with generic changes in trading volume."}},{title:{zh:"均衡结果有条件",en:"Equilibrium results are conditional"},body:{zh:"出版方摘要描述了连续交易极限下的结果：市场深度在模型中保持不变，私人信息到交易结束时进入价格。这些是特定模型下推导的性质，不是对现实每一个交易日的描述。",en:"The publisher's abstract describes constant market depth and incorporation of private information by the end of trading in the continuous-trading limit. These are properties derived under the model, not descriptions of every real trading session."}},{title:{zh:"这里的深度不是盘口档位数量",en:"Model depth is not a count of order-book levels"},body:{zh:"做市者按其信息条件下的资产清算价值期望定价，订单流因此与价格变化联系起来。连续交易极限中的恒定深度是这一均衡的性质，不是承诺现实盘口总有同样厚度。编辑建议：实证代理应写清交易方向、价格变化和采样间隔，不能用总成交量直接替代模型订单流。",en:"Competitive makers price at expected liquidation value conditional on their information, linking flow to price changes. Constant depth in the continuous limit is an equilibrium property, not a claim that displayed books always have equal thickness. Editorial application: specify trade direction, price changes and sampling; aggregate volume is not the model's signed flow."},reference:{url:"https://people.duke.edu/~qc2/BA532/1985%20EMA%20Kyle.pdf",label:{zh:"原文第1节：竞争性定价与连续交易极限",en:"Original §1: competitive pricing and continuous limit"}}},{title:{zh:"从模型走到数据，还缺什么？",en:"What is missing when moving to data?"},body:{zh:"本站建议用它理解价格冲击与信息披露速度之间的联系，再单独核对实际数据能观察什么。分钟价格与总成交量并不直接提供交易方向、交易者身份或盘口深度；仅凭它们不能验证模型中的每一个机制。",en:"Use the model to organize questions about price impact and the speed of information revelation, then audit observability separately. Minute prices and aggregate volume do not directly reveal trade direction, trader identity or order-book depth, and cannot test every mechanism on their own."}}],readerLimits:{zh:"这是理论模型导读，不是内幕交易识别方法。单一知情者、风险中性等假设限制了向复杂现实市场的直接迁移。",en:"This is a guide to a theoretical model, not an insider-trading detector. Assumptions such as one informed trader and risk neutrality limit direct transfer to complex markets."}},{id:"optimal-execution-of-portfolio-transactions",title:"Optimal Execution of Portfolio Transactions",titleZh:"组合交易的最优执行",sourceTitle:"Optimal execution of portfolio transactions",authors:"Robert Almgren · Neil Chriss",venue:"The Journal of Risk",year:"2001",kind:"paper",topic:"market-microstructure",data:"intraday prices · volume · spread",dataZh:"日内价格；成交量；价差",summary:{en:"Frames execution as a balance between market impact, timing risk, and trading horizon.",zh:"从市场冲击、时间风险与交易周期之间的权衡来刻画执行问题。"},related:{datasets:["cn-equity-minute"],features:["liquidity-measures"]},sources:[{label:"DOI",url:"https://doi.org/10.21314/jor.2001.041"}]},{id:"price-momentum-and-trading-volume",title:"Price Momentum and Trading Volume",titleZh:"价格动量与交易量",sourceTitle:"Price Momentum and Trading Volume",authors:"Charles M.C. Lee · Bhaskaran Swaminathan",venue:"The Journal of Finance",year:"2000",kind:"paper",topic:"quant-methods",data:"returns · turnover · portfolios",dataZh:"收益；换手率；组合",summary:{en:"Examines how trading volume can help interpret the persistence and reversal of price momentum.",zh:"研究交易量如何帮助理解价格动量的延续与反转。"},related:{recipes:["pit-fundamentals-panel","adjusted-price-series"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/0022-1082.00280"}]},{id:"the-cross-section-of-expected-stock-returns",title:"The Cross-Section of Expected Stock Returns",titleZh:"预期股票收益的横截面",sourceTitle:"The Cross‐Section of Expected Stock Returns",authors:"EUGENE F. FAMA · KENNETH R. FRENCH",venue:"The Journal of Finance",year:"1992",kind:"paper",topic:"corporate-fundamentals",data:"prices · market cap · financials",dataZh:"价格；市值；财务报表",summary:{en:"Studies how firm size, book-to-market, leverage, and earnings-to-price relate to expected returns.",zh:"研究公司规模、账面市值比、杠杆及盈价比与预期收益的关系。"},related:{datasets:["cn-pit-fundamentals","cn-company-master"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/j.1540-6261.1992.tb04398.x"}],readingNotes:[{title:{zh:"比较公司，不是预测下一天",en:"Compare firms, not tomorrow"},body:{zh:"Fama与French研究公司之间平均收益的差异，比较市场贝塔、规模、账面市值比、杠杆和盈利价格比。横截面问题与预测某只股票下一天的价格不同，也不等于解释每一次日内波动。",en:"Fama and French compare average returns across firms using beta, size, book-to-market, leverage and earnings-price ratios. This cross-sectional question differs from forecasting tomorrow's price or explaining every intraday move."}},{title:{zh:"两个市值日期，各有用途",en:"Two capitalization dates serve different roles"},body:{zh:"样本取CRSP与COMPUSTAT交集中的非金融企业。作者用上一年12月市值计算账面市值比等比率，用本年6月市值衡量规模，再对应7月起的收益。财务年度、比率分母日期和分组日期因此不是同一个时间；混用它们就改变了比较对象。",en:"The sample intersects CRSP and COMPUSTAT for nonfinancial firms. Prior-December capitalization enters accounting ratios; June capitalization measures size before returns beginning in July. Fiscal year, ratio denominator date and sorting date therefore play distinct roles. Collapsing them into one date changes the comparison."},reference:{url:"https://www.ivey.uwo.ca/media/3775518/the_cross-section_of_expected_stock_returns.pdf",label:{zh:"原文第I.A节：样本与日期对齐",en:"Original §I.A: sample and date alignment"}}},{title:{zh:"把相互重叠的解释放在一起",en:"Test overlapping explanations"},body:{zh:"这些变量往往共享价格或公司规模信息。分别显著不意味着各自提供独立解释；作者把它们联合考察，并区分与规模相关及无关的贝塔变化。理解这种比较，比记住某一个系数更重要。",en:"Several variables share price or size information. Separate significance does not establish independent explanatory content. Joint tests and beta variation distinct from size help disentangle their roles."}},{title:{zh:"样本结论与经济解释分开",en:"Separate finding from mechanism"},body:{zh:"在1963—1990年的美国样本中，规模与账面市值比刻画了多项变量所关联的平均收益差异；市场贝塔的关系较弱。作者讨论风险与非理性定价两类解释，不能把统计关联直接定性为某一种机制。",en:"In the 1963–1990 US sample, size and book-to-market capture return differences associated with several variables, while beta's relation is weak. Risk and mispricing remain competing interpretations of those associations."}},{title:{zh:"组合贝塔不是当时的个股预测",en:"Portfolio betas are not contemporaneous forecasts"},body:{zh:"作者先按规模与预排序贝塔分组，再把组合的全样本后排序贝塔赋给组内股票，用于逐月横截面检验。这样做旨在提高测量精度，不是为每个历史时点生成可实时使用的输入。若改做时点一致分析，贝塔估计窗口也必须限制在当时已知的数据内。",en:"Stocks receive full-sample post-ranking betas from portfolios formed on size and pre-ranking beta. This improves measurement for monthly cross-sectional tests; it does not create real-time historical inputs. Editorial application: a point-in-time design must separately restrict beta estimation to observations already available at each date."},reference:{url:"https://www.ivey.uwo.ca/media/3775518/the_cross-section_of_expected_stock_returns.pdf",label:{zh:"原文第I.B.1节：贝塔估计与赋值",en:"Original §I.B.1: beta estimation and assignment"}}},{title:{zh:"与1993年论文对照阅读",en:"Read alongside the 1993 paper"},body:{zh:"这篇以公司特征和横截面为中心，1993年论文进一步研究因子组合收益的时间序列解释力。本站建议记录财务数据披露时点与市值日期，避免用后来修订的账面值去解释当时可得的信息。",en:"This paper centers on characteristics and cross-sections; the 1993 study examines factor-return time series. Preserve accounting availability and capitalization dates so later revisions do not silently enter historical information sets."}}],readerLimits:{zh:"历史关联既不识别唯一原因，也不保证其他市场或未来时期的表现；公司特征不等同于因子载荷。",en:"Historical associations neither identify one cause nor establish transfer to other markets or periods; characteristics are not factor loadings."}},{id:"china-s-stock-market-a-marriage-of-capitalism-and-state-control",title:"The Development of China's Stock Market and Stakes for the Global Economy",titleZh:"中国股票市场的发展及其全球经济意义",sourceTitle:"The Development of China's Stock Market and Stakes for the Global Economy",authors:"Jennifer N. Carpenter · Robert F. Whitelaw",venue:"Annual Review of Financial Economics",year:"2017",kind:"paper",topic:"a-share-market",data:"A-share prices · ownership · fundamentals",dataZh:"A股价格；所有权；基本面",summary:{en:"Reviews the ownership, institutional structure, and market development of China's stock market.",zh:"梳理中国股票市场的所有权、制度结构与市场发展特征。"},related:{datasets:["cn-equity-daily","cn-company-master","cn-market-reference"]},sources:[{label:"DOI",url:"https://doi.org/10.1146/annurev-financial-110716-032333"}],readingNotes:[{title:{zh:"先理解制度，再套用模型",en:"Institutions before imported models"},body:{zh:"Carpenter与Whitelaw解释为何研究中国股市不能只移植美国市场的常见假设。股票市场同时涉及国企改革、上市选择与资本配置，企业目标和投资者约束未必与已有模型一致。文章的价值是提出研究问题的背景，而不是给市场打一个效率总分。",en:"Carpenter and Whitelaw explain why familiar US-market assumptions may not transfer to China. SOE reform, listing selection and capital allocation interact with different objectives and constraints. The review frames research questions rather than assigning the market a single efficiency score."}},{title:{zh:"这是2017年的文献综述",en:"A review published in 2017"},body:{zh:"文章梳理公司金融与资产定价文献，并以当时的制度演进组织讨论，没有一个可以概括全文的统一回归样本。引言中的规模与制度描述对应其写作时期；阅读时应将其视为历史背景，不能把2017年的规则表述直接当成今天的规则。",en:"This review organizes corporate-finance and asset-pricing studies around institutional development; there is no single pooled regression sample for the article. Market sizes and rules in its introduction belong to its historical setting, not automatically to the present."},reference:{url:"https://pages.stern.nyu.edu/~jcarpen0/pdfs/Carpenter%20Whitelaw%202017%20ARFE%20-%20The%20Development%20of%20China's%20Stock%20Market%20and%20Stakes%20for%20the%20Global%20Economy.pdf",label:{zh:"原文摘要与第1节：综述范围",en:"Original abstract and §1: review scope"}}},{title:{zh:"公司侧：上市与所有权选择",en:"Corporate side: listing and ownership"},body:{zh:"第2节从部分私有化、IPO和上市选择展开。文章比较不同研究对产权变化与企业表现的发现，并提醒国企还可能承担就业、社会与战略目标。因此，上市公司不一定代表全部企业，单个利润指标也未必覆盖改革的全部目标。",en:"Section 2 examines partial privatization, IPOs and listing choice. It contrasts findings on ownership and performance and notes SOEs' employment, social and strategic roles. Listed firms need not represent all firms, and a single profitability measure need not capture every reform objective."},reference:{url:"https://pages.stern.nyu.edu/~jcarpen0/pdfs/Carpenter%20Whitelaw%202017%20ARFE%20-%20The%20Development%20of%20China's%20Stock%20Market%20and%20Stakes%20for%20the%20Global%20Economy.pdf",label:{zh:"原文第2节，尤其第2.1节",en:"Original §2, especially §2.1"}}},{title:{zh:"价格侧：分割与信息含量",en:"Pricing side: segmentation and information"},body:{zh:"引言归纳了A股与境外股份价差、公司特定信息进入价格，以及收益横截面等研究线索。价格差异可能同时涉及信息、可投资范围与市场分割，不能看到价差就认定存在可执行套利；价格波动大也不等于没有公司信息。",en:"The introduction maps work on A-share versus foreign-share premiums, firm-specific price information and the return cross-section. Information and investment constraints can coexist with segmentation. A price gap is not proof of executable arbitrage, and volatility alone is not proof of absent information."}},{title:{zh:"如何使用这篇综述",en:"How to use this review"},body:{zh:"建议先选一个问题，例如股权改革如何改变企业行为，再沿第2节追到被引用的原始研究。分别记录每篇的政策时期、处理对象、对照样本与结果变量。综述适合建立地图；若要引用具体效果大小或因果结论，仍需回到对应论文核对。",en:"Choose a question—such as how ownership reform changes firm behavior—then follow the review to original studies. Record policy periods, treated units, comparison groups and outcomes. A review supplies a map; effect sizes and causal claims still require checking the cited originals."}},{title:{zh:"数据准备从历史身份开始",en:"Start with historical identities"},body:{zh:"编辑建议：证券代码之外，还需保留上市板块、股份类别、所有权和资格规则的生效时间。用今天的公司主表回填过去，会抹去改革和样本选择。若研究涉及跨市场比较，还要明确币种、交易日历与可交易限制，不能仅按同名公司连接两列价格。",en:"Editorial application: preserve dated board membership, share class, ownership and eligibility alongside identifiers. Today's company master can erase historical selection and reform changes. Cross-market comparisons additionally need currency, calendars and trading constraints, not just matching company names."}}],readerLimits:{zh:"这是一张历史研究地图；当前制度、原始论文的识别假设和可获得数据需分别核对。",en:"This is a historical research map. Current institutions, original studies' identification assumptions and available data require separate checks."}},{id:"media-coverage-and-the-cross-section-of-stock-returns",title:"Media Coverage and the Cross-section of Stock Returns",titleZh:"媒体覆盖与股票收益横截面",sourceTitle:"Media Coverage and the Cross‐section of Stock Returns",authors:"LILY FANG · JOEL PERESS",venue:"The Journal of Finance",year:"2009",kind:"paper",topic:"alternative-data",data:"news coverage · returns · firm characteristics",dataZh:"新闻覆盖；收益；企业特征",summary:{en:"Examines how differences in media coverage relate to the cross-section of stock returns.",zh:"研究媒体覆盖差异如何与股票横截面收益表现相关。"},related:{datasets:["cn-news-flashes","cn-announcements"],recipes:["company-event-timeline"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/j.1540-6261.2009.01493.x"}]},{id:"csi-300-index-methodology",title:"CSI 300 Index Methodology",titleZh:"沪深300指数编制方法",sourceTitle:"CSI 300 Index Methodology",authors:"China Securities Index Company",venue:"Index methodology",year:"2023",kind:"industry-research",topic:"a-share-market",data:"constituents · free-float market cap · corporate actions",dataZh:"成分股；自由流通市值；公司行动",summary:{en:"Explains the index universe, selection, weighting, review, and adjustment methodology.",zh:"说明指数样本空间、选样、加权、定期审核与调整方法。"},related:{datasets:["cn-index-constituents"]},sourceNote:{en:"September 2023 PDF edition; a historical methodology version.",zh:"2023年9月PDF版本；属于历史方法论版本。"},sources:[{label:"CSI 300 Index Methodology (official PDF)",url:"https://oss-ch.csindex.com.cn/static/html/csindex/public/uploads/indices/detail/files/en/000300_Index_Methodology_en.pdf"}]},{id:"sse-statistical-yearbook",title:"SSE Statistical Yearbook",titleZh:"上海证券交易所统计年鉴（2025卷）",sourceTitle:"SSE Statistical Yearbook",authors:"Shanghai Stock Exchange",venue:"Market statistics",year:"2025",kind:"industry-research",topic:"a-share-market",data:"market statistics · listings · turnover · financing",dataZh:"市场统计；上市公司；成交；融资",summary:{en:"Provides a structured reference for market scale, listings, trading activity, and financing statistics.",zh:"提供市场规模、上市公司、交易活动与融资统计的结构化年度参考。"},related:{datasets:["cn-equity-daily","cn-company-master","cn-market-reference"]},sourceNote:{en:"2025 volume covers 2024 statistics; use the selected volume's definitions.",zh:"2025卷收录2024年统计；使用时以所选卷次的定义为准。"},sources:[{label:"SSE statistical yearbook archive",url:"https://www.sse.com.cn/aboutus/publication/yearly/"}]},{id:"findings-regarding-the-market-events-of-may-6-2010",title:"Findings Regarding the Market Events of May 6, 2010",titleZh:"2010年5月6日市场事件联合调查报告",sourceTitle:"Findings Regarding the Market Events of May 6, 2010",authors:"U.S. SEC · CFTC",venue:"Joint staff report",year:"2010",kind:"case",topic:"market-microstructure",data:"trades · quotes · order flow · futures",dataZh:"成交；报价；订单流；期货",summary:{en:"Reconstructs a market-structure event using synchronized order, trade, quote, and futures evidence.",zh:"使用同步的订单、成交、报价与期货证据重建一次市场结构事件。"},related:{datasets:["cn-equity-minute"],features:["liquidity-measures"]},sources:[{label:"SEC / CFTC joint report",url:"https://www.sec.gov/files/marketevents-report.pdf"}]},{id:"staff-report-on-equity-and-options-market-structure-conditions-in-early-2021",title:"Staff Report on Equity and Options Market Structure Conditions in Early 2021",titleZh:"2021年初股票与期权市场结构工作人员报告",sourceTitle:"Staff Report on Equity and Options Market Structure Conditions in Early 2021",authors:"U.S. Securities and Exchange Commission",venue:"Staff report",year:"2021",kind:"case",topic:"alternative-data",data:"prices · options · short interest · account activity",dataZh:"价格；期权；卖空余额；参与者活动",summary:{en:"Organizes market, options, short-interest, and participation evidence around a high-attention trading episode.",zh:"围绕一次高关注交易事件，整理市场、期权、卖空与参与者活动证据。"},related:{datasets:["cn-news-flashes","cn-announcements"],recipes:["company-event-timeline"]},sources:[{label:"SEC staff report",url:"https://www.sec.gov/about/reports-publications/staff-report-equity-options-market-structure-conditions-early-2021"}]},{id:"modeling-and-forecasting-realized-volatility",title:"Modeling and Forecasting Realized Volatility",titleZh:"已实现波动率的建模与预测",sourceTitle:"Modeling and Forecasting Realized Volatility",authors:"Torben G. Andersen · Tim Bollerslev · Francis X. Diebold · Paul Labys",venue:"Econometrica",year:"2003",kind:"paper",topic:"market-microstructure",data:"minute returns · sampling interval · session boundaries · missingness",dataZh:"分钟收益；采样间隔；交易时段；缺失观测",summary:{en:"Shows how high-frequency returns can be aggregated into realized-volatility measures for lower-frequency analysis.",zh:"说明如何将高频收益聚合为已实现波动率，用于更低频的分析。"},related:{datasets:["cn-equity-minute"],features:["realized-volatility"],recipes:["adjusted-price-series"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/1468-0262.00418"}],readingNotes:[{title:{zh:"从日内变化到每日波动",en:"From intraday movement to daily volatility"},body:{zh:"Andersen等人研究如何把日内信息用于日频及更低频的波动测量与预测。重点不是预测价格方向，而是把波动从潜在变量转为可以由高频收益近似测量的对象，再研究这个对象随时间如何变化。",en:"Andersen and coauthors use intraday information to measure and forecast daily and lower-frequency volatility. Their target is not price direction. They construct an observable proxy for variation from high-frequency returns, then model its dynamics."}},{title:{zh:"原始样本与时间切分",en:"Original observations and time split"},body:{zh:"原始材料是1986年12月至1999年6月Reuters屏幕上的马克/美元与日元/美元银行间买卖报价。它们是指示性报价，不是必然可成交的价格。作者剔除周末及部分低活跃假日后，保留3,045天，并将其分为2,449天估计期与596天样本外预测期。",en:"The raw material is indicative interbank DM/USD and JPY/USD bid/ask quotes on Reuters, December 1986–June 1999—not binding transaction prices. After weekend and selected holiday exclusions, 3,045 days remain: 2,449 for estimation and 596 for out-of-sample evaluation."},reference:{url:"https://users.ssc.wisc.edu/~behansen/718/Anderson2003.pdf",label:{zh:"原文第3.1节：报价、清理与样本切分",en:"Original §3.1: quotes, cleaning and sample split"}}},{title:{zh:"30分钟采样是取舍",en:"Thirty-minute sampling is a trade-off"},body:{zh:"作者从相邻报价插值得到等间隔价格，再计算30分钟对数收益；按日累加收益平方及交叉乘积，构造波动与协变动。选择30分钟，是为了平衡更密集采样的信息收益与微观结构噪声，并非证明这个间隔对所有市场最优。",en:"They interpolate prices from neighboring quotes, calculate half-hour log returns and aggregate squared returns and cross-products. Thirty-minute sampling balances information against microstructure contamination in this setting. It is not a universally optimal interval."},reference:{url:"https://users.ssc.wisc.edu/~behansen/718/Anderson2003.pdf",label:{zh:"原文第3.1–3.2节：收益与已实现波动构造",en:"Original §§3.1–3.2: returns and realized-volatility construction"}}},{title:{zh:"论文报告的发现",en:"What the paper reports"},body:{zh:"作者利用对数已实现波动的近似高斯分布与长记忆特征建立简单的多变量模型，并报告其波动预测通常优于比较模型。结合条件收益分布后，还检验密度与分位数预测。阅读时要分开点预测好坏和整个预测分布是否校准，不能用其中一个替代另一个。",en:"The authors exploit approximately Gaussian log realized volatility and long-memory dynamics in a simple multivariate model. They report generally strong volatility forecasts and assess return-density and quantile calibration. Point-forecast accuracy and distributional calibration are distinct evaluations."}},{title:{zh:"建议怎样读",en:"A useful reading order"},body:{zh:"先读第3节，明确每日样本究竟怎样生成；再回第2节理解二次变差与实际测量之间的关系；最后读第5–6节的模型与预测比较。尤其注意：已实现波动是事后测量，预测必须只使用预测时点之前的信息，二者不能混成同一个指标。",en:"Start with Section 3's construction, return to Section 2's quadratic-variation foundation, then read Sections 5–6 on modeling and forecast comparisons. Keep ex-post realized variation distinct from a forecast formed using information available beforehand."}},{title:{zh:"迁移到股票分钟线的缺口",en:"What changes with equity bars"},body:{zh:"编辑建议：股票有午间休市、集合竞价、停牌和隔夜区间，不能照搬全球外汇的24小时日界。分钟收盘价也不是原文的买卖报价中点。应先标明缺口与时间网格，单独处理隔夜变化，再讨论频率敏感性，不能将补零后的完整表格当作完整观测。",en:"Editorial application: equities introduce lunch breaks, auctions, suspensions and overnight intervals, unlike the global FX day. Minute closes are not quote midpoints. Mark gaps, define session boundaries and separate overnight movement before testing sampling sensitivity; zero-filled rows are not observations."}}],readerLimits:{zh:"历史外汇结果不能直接证明股票或加密市场的预测效果；缺失、报价口径与采样噪声都需要重新检查。",en:"Historical FX results do not establish forecasting performance for equities or crypto. Missingness, quote conventions and sampling noise require fresh checks."}},{id:"intraday-information-efficiency-on-the-chinese-equity-market",title:"Intraday Information Efficiency on the Chinese Equity Market",titleZh:"中国股票市场的日内信息效率",sourceTitle:"Intraday information efficiency on the Chinese equity market",authors:"Tao Chen · Jun Cai · Richard Y.K. Ho",venue:"China Economic Review",year:"2009",kind:"paper",topic:"a-share-market",data:"tick trades · quotes · bid-ask spread · volume",dataZh:"逐笔成交；报价；买卖价差；成交量",summary:{en:"Uses tick-by-tick Shanghai evidence to examine intraday spreads and price discovery across more and less liquid stocks.",zh:"使用上交所逐笔数据，研究不同流动性股票的日内价差与价格发现。"},related:{datasets:["cn-equity-minute"],features:["liquidity-measures"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/j.chieco.2009.03.007"}],readingNotes:[{title:{zh:"一天中的信息吸收是否相同？",en:"Does information arrive evenly?"},body:{zh:"Chen、Cai与Ho关注价格发现如何在交易日内变化。开盘、连续交易与收盘拥有不同的信息环境；把它们平均成一天，可能掩盖市场机制的重要差别。",en:"Chen, Cai and Ho examine how price discovery changes within a trading day. Opening, continuous trading and closing have different information environments that daily aggregation can hide."}},{title:{zh:"历史交易阶段是样本的一部分",en:"Historical session phases are part of the sample"},body:{zh:"原文市场结构段落区分早盘开盘集合竞价、上午连续交易、午间休市和下午交易。编辑建议：为2004—2005年样本保留当时的阶段标签，不把午休当作随机缺失，也不要直接套用今日制度。相同钟点在不同交易阶段，可能代表不同的信息环境。",en:"The market-structure passage separates the opening call auction, morning continuous trading, lunch closure and afternoon trading. Editorial application: retain historical phase labels for the 2004–2005 sample. Lunch is not a random gap, and present-day rules should not be assumed. Clock time alone does not identify the information environment."},reference:{url:"https://www.sciencedirect.com/science/article/abs/pii/S1043951X0900039X",label:{zh:"期刊页面章节预览：Market structure",en:"Journal section preview: Market structure"}}},{title:{zh:"研究依赖逐笔交易与报价",en:"Trades and quotes are distinct inputs"},body:{zh:"作者使用2004年6月至2005年5月上海证券交易所180只成分股的报价与成交资料，考察报价价差、有效价差及价格无偏性。只拥有五分钟行情或日收盘价，不能重建原研究的全部观测。",en:"The sample contains trades and quotes for 180 Shanghai stocks from June 2004 through May 2005. Quoted spreads, effective spreads and price unbiasedness require information that daily closes or five-minute bars cannot fully recover."}},{title:{zh:"读模式，也读适用条件",en:"Read patterns with their conditions"},body:{zh:"摘要报告价差在开盘较高、随后下降、收盘略有回升，并发现更高流动性股票的日内价格更接近所检验的有效与无偏特征。不同交易规模在不同时段的作用也不同，不能概括为“大单总是更有信息”。",en:"Reported spreads are high at the open, decline and rise slightly at the close. More liquid stocks appear more efficient under the tests. Trade-size roles vary by session; large trades are not uniformly more informative."}},{title:{zh:"先分清价差问题与无偏性问题",en:"Spreads and unbiasedness ask different questions"},body:{zh:"交易成本分析关心买卖价差，而无偏性回归考察日内价格与后续价格发现的关系。出版方预览说明后者使用收盘到收盘收益作为被解释对象。编辑建议：分别记录报价配对、收益基准和观测时点；价差较小不能单独证明价格已吸收全部信息。",en:"Trading-cost analysis concerns spreads, while unbiasedness regressions examine intraday prices relative to subsequent price discovery. The publisher preview identifies close-to-close returns as the dependent object. Editorial application: document quote matching, return benchmarks and observation times separately. A narrow spread alone does not establish complete information incorporation."},reference:{url:"https://www.sciencedirect.com/science/article/abs/pii/S1043951X0900039X",label:{zh:"期刊页面章节预览：Unbiasedness regressions",en:"Journal section preview: Unbiasedness regressions"}}},{title:{zh:"在不同尺度之间保持概念清楚",en:"Keep time scales distinct"},body:{zh:"长期盈利信息与日内价格发现相互关联，但度量和样本要求不同。本站建议保留交易所时钟、报价与成交类型、交易阶段和缺失记录，再决定能回答什么问题，不用数据频率高低替代质量判断。",en:"Long-horizon profit information and intraday discovery are related but require different measures. Preserve exchange clocks, quote/trade identity, session phase and gaps before deciding which question the data can answer."}}],readerLimits:{zh:"样本仅覆盖特定时期与成分股；市场制度已可能变化。导读不是当前日内效率诊断，低频行情也不是原样本替代品。",en:"The sample is period- and constituent-specific. This is not a current efficiency diagnosis, and low-frequency bars are not equivalent to its original observations."}},{id:"giving-content-to-investor-sentiment-the-role-of-media-in-the-stock-market",title:"Giving Content to Investor Sentiment: The Role of Media in the Stock Market",titleZh:"赋予投资者情绪以内容：媒体在股市中的作用",sourceTitle:"Giving Content to Investor Sentiment: The Role of Media in the Stock Market",authors:"PAUL C. TETLOCK",venue:"The Journal of Finance",year:"2007",kind:"paper",topic:"alternative-data",data:"news text · publisher time · entity mapping · returns · volume",dataZh:"新闻文本；发布时间；实体映射；收益；成交量",summary:{en:"Studies how the tone of financial media relates to market prices and trading volume.",zh:"研究财经媒体语气如何与市场价格和交易量相关。"},related:{datasets:["cn-news-flashes","cn-announcements"],recipes:["company-event-timeline"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/j.1540-6261.2007.01232.x"}],readingNotes:[{title:{zh:"媒体在反映市场，还是影响市场？",en:"Does media reflect or influence markets?"},body:{zh:"Tetlock研究财经媒体的语气与市场活动之间的关系。问题不只是坏消息是否伴随下跌，还包括市场下跌是否反过来影响报道，以及这种关系能否与基本面信息区分。",en:"Tetlock examines how financial-media tone relates to market activity. The question includes whether pessimism precedes price changes, whether declines affect subsequent reporting, and how these relations differ from information about fundamentals."}},{title:{zh:"词典类别不是互斥标签",en:"Dictionary categories are not exclusive labels"},body:{zh:"第II节说明General Inquirer词典类别既不互斥，也不覆盖所有词；一个词可能进入多个类别。作者还调整星期几对应的类别均值，避免专栏的规律性写作差异主导因子。编辑建议：保留词典版本、计数口径与日历处理，不把各类别计数直接加成独立词数。",en:"Section II states that General Inquirer categories overlap and do not cover every word. Category means are also centered by weekday to reduce systematic writing-pattern noise. Editorial application: preserve dictionary versions, counting conventions and calendar treatment; summing category counts does not yield a count of distinct classified words."},reference:{url:"https://www.columbia.edu/~pt2238/papers/Tetlock_Media_Sentiment_JF.pdf",label:{zh:"原文第II节：词语分类与星期效应",en:"Original §II: word categories and weekday effects"}}},{title:{zh:"把文字转成可观察的度量",en:"Turning text into a measure"},body:{zh:"作者使用《华尔街日报》一个日常市场专栏，将词语分类并通过主成分方法构建悲观程度指标，再用时间序列方法观察它与收益、成交量的联系。这个度量依赖具体语料和词典，不是语言本身天然给出的分数。",en:"The study classifies words from a daily Wall Street Journal market column, uses principal components to construct a pessimism measure, and examines its temporal relations with returns and volume. The measure depends on a particular corpus and dictionary, not a universal language score."}},{title:{zh:"双向关系与短期反应",en:"Feedback and short-run responses"},body:{zh:"论文报告较高悲观程度与随后价格下行压力及回归相关，极端语气与较高成交量相关，市场下跌也会带来更多悲观报道。因此，单向写成“新闻决定股价”会丢失论文的重要部分。",en:"The paper reports downward price pressure followed by reversion after pessimistic media content, higher volume with extreme tone, and greater pessimism following low returns. Reducing this to 'news determines prices' omits important feedback in the evidence."}},{title:{zh:"先确定载荷，再计算下一年的文本指标",en:"Estimate loadings before scoring the next year"},body:{zh:"作者用t−1年的文本估计主成分载荷，再用这些载荷计算t年的每日因子，避免把未来语料信息带入当期度量。这个因子从词语类别的共同变化中提取，不以股票收益作为拟合目标。若改用全样本一次性训练，就改变了原研究的信息边界。",en:"Loadings estimated from year t−1 score daily content in year t, keeping future corpus information out of contemporaneous measurement. The factor extracts variation among word categories rather than optimizing against stock returns. Training once on the complete historical corpus would change that information boundary."},reference:{url:"https://www.columbia.edu/~pt2238/papers/Tetlock_Media_Sentiment_JF.pdf",label:{zh:"原文第II节：逐年主成分估计",en:"Original §II: annual principal-component estimation"}}},{title:{zh:"从旧报纸走向新语料",en:"Moving to a different corpus"},body:{zh:"本站建议先固定媒体范围、版本与发布时间，再去除转载并检查实体识别。原样本是1984—1999年的美国报纸专栏；中文公告、社交媒体和大模型标签都需要自己的人工核对样本，不能直接继承这篇论文的测量有效性。",en:"Fix the publisher universe, text version and release timing before deduplicating and checking entity mapping. The sample is a US newspaper column from 1984–1999. Chinese filings, social media and model-generated labels need their own validation samples."}}],readerLimits:{zh:"时间序列预测关系不自动等于因果效应；语料选择、语言、词典与发布时间都会限制迁移。",en:"Predictive temporal relations do not automatically establish causation; corpus selection, language, dictionaries and release timing constrain transfer."}},{id:"trading-and-arbitrage-in-cryptocurrency-markets",title:"Trading and Arbitrage in Cryptocurrency Markets",titleZh:"加密货币市场的交易与套利",sourceTitle:"Trading and arbitrage in cryptocurrency markets",authors:"Igor Makarov · Antoinette Schoar",venue:"Journal of Financial Economics",year:"2020",kind:"paper",topic:"crypto-markets",data:"multi-exchange prices · signed volume · fiat markets · exchange identity",dataZh:"跨交易所价格；带方向成交量；法币市场；场所身份",summary:{en:"Documents persistent cross-exchange price deviations and connects them to market segmentation and arbitrage constraints.",zh:"记录持续的跨交易所价格偏离，并将其与市场分割和套利约束联系起来。"},related:{datasets:["crypto-binance-spot-5m"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/j.jfineco.2019.07.001"}],readingNotes:[{title:{zh:"同一种资产，为什么出现不同价格？",en:"Why can the same asset have different prices?"},body:{zh:"Makarov与Schoar把不同交易所的比特币价格放在一起，研究价格偏离为何反复出现、为何没有立即消失。重点是市场之间的连接与资金约束，而不是单个交易所的价格趋势。",en:"Makarov and Schoar compare bitcoin prices across exchanges to study recurring deviations and why they persist. The focus is connections between markets and constraints on capital, rather than a price trend within one venue."}},{title:{zh:"原始观测是带场所身份的成交",en:"The observations are venue-specific trades"},body:{zh:"接受稿第2节说明主要资料来自Kaiko，覆盖17家大型交易所，分析窗口为2017年1月1日至2018年2月28日。记录包含成交时间、价格、数量和买卖发起方向。它不是把几家网站的日收盘价拼在一起；场所、报价币和时钟对齐共同决定比较是否有意义。",en:"Section 2 of the accepted manuscript describes Kaiko trades from 17 large exchanges, focusing on January 1, 2017–February 28, 2018. Fields include timestamps, prices, amounts and initiation direction. This is not a panel of website daily closes: venue identity, quote currency and synchronized clocks jointly define a meaningful comparison."},reference:{url:"https://researchonline.lse.ac.uk/id/eprint/100409/1/Cryptocurrency_Markets_JFE_final_v4.pdf",label:{zh:"接受稿第2节：数据描述",en:"Accepted manuscript §2: data description"}}},{title:{zh:"跨场所比较需要统一什么？",en:"What must a venue comparison align?"},body:{zh:"研究使用多个国家、多个交易所的逐笔数据，比较境内与跨国价差，并区分共同和场所特有的带方向成交量变化。报价币种、时间同步与场所身份都是比较的前提，不能在聚合时消失。",en:"The analysis uses tick data across countries and exchanges, compares domestic with international deviations, and distinguishes common from venue-specific signed-volume components. Quote currencies, synchronized time and venue identity are prerequisites, not disposable metadata."}},{title:{zh:"价格偏离揭示市场分割",en:"Deviations reveal segmentation"},body:{zh:"作者报告跨国价格偏离通常比同国内更大，在比特币快速升值时期共同扩大，并讨论跨境资本流动约束的作用。这些证据说明看到价差并不等于资金能够无摩擦地跨场所移动。",en:"The paper reports larger deviations across countries than within them, common widening during rapid bitcoin appreciation, and a role for constraints on cross-border capital. Seeing a spread is not equivalent to being able to move capital frictionlessly between venues."}},{title:{zh:"完成一次交易，不等于资金可以循环",en:"One completed trade is not a repeatable capital cycle"},body:{zh:"作者用跨国交易说明，低价地区买入、高价地区卖出后，所得法币可能难以汇回最初地区，资金因而被困在交易的一端。这个机制把数字资产转移与法币回流分开。编辑建议：记录价差时也记录结算币种与转移限制，不把账面价格差当作可反复实现的收益。",en:"The authors distinguish moving crypto from repatriating fiat: after buying in a low-price region and selling in a high-price region, proceeds may be difficult to return to the starting market. Capital can become trapped. Editorial application: retain settlement currencies and transfer constraints rather than treating a quoted spread as repeatedly realizable profit."},reference:{url:"https://researchonline.lse.ac.uk/id/eprint/100409/1/Cryptocurrency_Markets_JFE_final_v4.pdf",label:{zh:"接受稿引言：法币回流与市场分割",en:"Accepted manuscript introduction: fiat repatriation and segmentation"}}},{title:{zh:"把价差记录成问题，而非收益承诺",en:"Treat a spread as a question"},body:{zh:"本站建议同时记录价格、手续费、兑换与转移约束、缺失区间和数据时钟，再决定观察到的偏离是什么。本站单一Binance场所的数据只能作为局部材料，不能替代论文的跨交易所样本，更不能证明套利可执行。",en:"Record prices alongside fees, conversion and transfer constraints, missing periods and data clocks before interpreting a deviation. A single Binance venue is only partial material: it cannot replace this cross-exchange sample or establish executable arbitrage."}}],readerLimits:{zh:"接受稿与期刊定稿可能存在差异。历史价差不代表当前机会；转账、资本流动、场所风险和可成交数量均需另行评估。",en:"The accepted manuscript may differ from the journal edition. Historical deviations are not current opportunities; transfers, capital restrictions, venue risk and executable size require separate assessment."}},{id:"why-defi-lending-evidence-from-aave-v2",title:"Why DeFi Lending? Evidence from Aave V2",titleZh:"为何使用DeFi借贷？来自Aave V2的证据",sourceTitle:"Why DeFi Lending? Evidence from Aave V2",authors:"Giulio Cornelli · Leonardo Gambacorta · Rodney Garratt · Alessio Reghezza",venue:"BIS Working Papers No 1183",year:"2024 · rev. 2025",kind:"industry-research",topic:"crypto-markets",data:"protocol transactions; collateral; lending rates; governance tokens",dataZh:"协议交易；抵押物；借贷利率；治理代币",summary:{en:"Examines motivations for DeFi lending and borrowing, framing leverage and funding conditions as market context rather than a standalone signal.",zh:"研究 DeFi 借贷动机，将杠杆与资金条件视为市场背景，而非独立信号。"},related:{datasets:["crypto-binance-derivatives"]},sources:[{label:"BIS Working Paper 1183",url:"https://www.bis.org/publications/working-paper-1183-why-defi-lending-evidence-aave-v2"}],readerLimits:{en:"The evidence concerns Aave V2 lending. Exchange perpetual funding rates and open interest describe different activity.",zh:"研究证据涉及Aave V2借贷；交易所永续资金费率与持仓量描述的是不同活动。"}},{id:"form-13f-official-filing-guidance-and-edgar-data-access",title:"Form 13F: Official Filing Guidance and EDGAR Data Access",titleZh:"Form 13F：官方申报指引与EDGAR数据访问",sourceTitle:"Form 13F: Official Filing Guidance and EDGAR Data Access",authors:"U.S. Securities and Exchange Commission",venue:"SEC primary sources",year:"living",kind:"primary-source",topic:"alternative-data",data:"institution universe · Form 13F filings · amendments · CIK · submission time",dataZh:"机构范围；13F文件；修订；CIK；提交时点",summary:{en:"Defines the filing context and public access path for institutional Form 13F holdings disclosures.",zh:"界定机构 Form 13F 持仓披露的申报背景与公开访问路径。"},related:{datasets:["us-notable-investor-13f"]},sources:[{label:"SEC Form 13F FAQ",url:"https://www.sec.gov/rules-regulations/staff-guidance/division-investment-management-frequently-asked-questions/frequently-asked-questions-about-form-13f"},{label:"SEC EDGAR data APIs",url:"https://www.sec.gov/search-filings/edgar-application-programming-interfaces"}],readerLimits:{en:"13F disclosures are quarterly, delayed, and subject to amendments and reporting-scope limits; they are not real-time portfolios.",zh:"13F按季度披露，存在时滞、修订和申报范围限制，不是实时持仓。"}},{id:"binance-usd-m-futures-market-data-funding-rate-and-open-interest",title:"Binance USDⓈ-M Futures Market Data: Funding Rate and Open Interest",titleZh:"Binance USDⓈ-M市场数据：资金费率与持仓量",sourceTitle:"Binance USDⓈ-M Futures Market Data: Funding Rate and Open Interest",authors:"Binance",venue:"Binance Developer Documentation",year:"living",kind:"primary-source",topic:"crypto-markets",data:"frozen symbol universe · funding rate history · open interest · request limits",dataZh:"固定标的范围；资金费率历史；持仓量；请求限制",summary:{en:"Documents public REST market-data endpoints that define funding-rate and open-interest request shapes for USDⓈ-M futures.",zh:"说明 USDⓈ-M 永续合约的公开 REST 市场数据端点，以及资金费率和持仓量的请求形态。"},related:{datasets:["crypto-binance-derivatives"]},sources:[{label:"Binance USDⓈ-M market-data reference",url:"https://developers.binance.com/en/docs/catalog/core-trading-derivatives-trading-usd-s-m-futures/api/rest-api/market-data"}],readerLimits:{en:"Funding rates, premium indices, and open interest are distinct measures with different units and observation times.",zh:"资金费率、溢价指数与持仓量是不同指标，单位与观测时点也不同。"}},{id:"a-comprehensive-look-at-the-empirical-performance-of-equity-premium-prediction",title:"A Comprehensive Look at The Empirical Performance of Equity Premium Prediction",titleZh:"股权溢价预测的实证表现评估",sourceTitle:"A Comprehensive Look at The Empirical Performance of Equity Premium Prediction",authors:"Ivo Welch · Amit Goyal",venue:"Review of Financial Studies",year:"2008",kind:"paper",topic:"research-methods",data:"historical predictors; release dates; returns; expanding windows",dataZh:"历史预测变量；发布日期；收益；扩展窗口",summary:{en:"Compares published predictors using a consistent out-of-sample evaluation framework.",zh:"用一致的样本外评估框架比较已发表的预测变量。"},related:{recipes:["pit-fundamentals-panel","adjusted-price-series"]},sources:[{label:"DOI",url:"https://doi.org/10.1093/rfs/hhm014"}]},{id:"portfolio-selection",title:"Portfolio Selection",titleZh:"投资组合选择",sourceTitle:"PORTFOLIO SELECTION*",authors:"Harry Markowitz",venue:"The Journal of Finance",year:"1952",kind:"paper",topic:"asset-pricing",data:"asset returns; covariance matrix; sampling window",dataZh:"资产收益；协方差矩阵；采样窗口",summary:{en:"Introduces the joint role of expected returns, variances, and covariances in portfolio analysis.",zh:"从预期收益、方差与协方差出发，理解组合分析为何需要联合分布。"},related:{datasets:["cn-equity-daily","cn-pit-fundamentals"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/j.1540-6261.1952.tb01525.x"}],readingNotes:[{title:{zh:"为什么单看收益不够",en:"Why expected return is not enough"},body:{zh:"Markowitz把选择过程分成形成未来判断与据此配置资产两步，本文研究后一步。若只追求最高预期收益，很难解释为何要分散持有；文章因此把预期收益与收益方差一起纳入选择。这里讨论的是给定判断后的取舍，不是如何预测股票。",en:"Markowitz separates forming beliefs from choosing a portfolio given those beliefs. The paper addresses the second task. Maximizing expected return alone cannot explain a preference for diversification, so variance enters alongside expected return. It is a framework for choices conditional on beliefs, not a stock-forecasting procedure."}},{title:{zh:"材料是模型，不是回测样本",en:"A model, not a backtest sample"},body:{zh:"输入是各证券的预期收益、方差和两两协方差，以及由投资者确定的权重。本文所展示的推导排除负权重，且权重之和为1。它没有给出某一市场或某段历史的优胜组合；历史收益只是后来估计这些输入的一种可能材料。",en:"Inputs are expected returns, variances, pairwise covariances and investor-chosen weights. The displayed analysis excludes negative weights and requires weights to sum to one. It does not report a winning historical portfolio. Using past returns to estimate its inputs is an additional empirical choice."},reference:{url:"https://www2.stat.duke.edu/courses/Fall07/sta103/markowitz.pdf",label:{zh:"原文：组合收益与方差定义",en:"Original: portfolio return and variance definitions"}}},{title:{zh:"关键一步：把共同变动算进去",en:"The key step: include co-movement"},body:{zh:"组合期望收益是个别期望收益的加权和；组合方差还包含证券之间的协方差。因此，给两只各自波动很大的证券配权，结果取决于它们是否一起涨跌。只比较单只证券的风险，或者只数持仓个数，都会漏掉组合层面的关系。",en:"Portfolio mean is a weighted sum of individual means; portfolio variance also includes cross-security covariance terms. Combining two volatile securities therefore depends on their co-movement. Ranking securities by stand-alone volatility, or counting holdings, misses this portfolio-level relationship."}},{title:{zh:"有效集合说明了什么",en:"What the efficient set tells us"},body:{zh:"文章用几何方式描述可达到的收益—方差组合。在预期收益相同或更高时方差最低，或者方差相同或更低时期望收益最高的组合，构成有效选择的边界。这不是唯一答案：投资者仍需在边界上选择自己愿意接受的风险与收益组合。",en:"The geometric argument describes attainable mean–variance combinations and their efficient boundary. Efficiency means that another feasible portfolio cannot improve the relevant mean–variance trade-off. It does not identify one universally best allocation: the investor must still choose a preferred point on that boundary."},reference:{url:"https://www2.stat.duke.edu/courses/Fall07/sta103/markowitz.pdf",label:{zh:"原文：有效集合与几何说明",en:"Original: efficient-set and geometric discussion"}}},{title:{zh:"阅读时先分清三个对象",en:"Keep three objects separate"},body:{zh:"建议依次区分个别证券的随机收益、事先固定的持仓权重，以及由两者组合得到的收益分布。读协方差式子时，检查非对角项如何改变结果；读有效边界时，再问哪些权重被允许。更换约束或预期判断，就已经在研究另一个可行集合。",en:"Track random security returns, fixed allocation weights and the resulting portfolio distribution separately. In the variance expression, inspect the off-diagonal terms; in the efficient-set argument, inspect the allowed weights. Different constraints or beliefs define a different feasible problem."}},{title:{zh:"把模型带入数据前",en:"Before bringing data to the model"},body:{zh:"编辑建议：先冻结收益定义、证券范围、观察窗口和缺失处理，再讨论估计。协方差矩阵所用的日期必须对齐，不能让不同证券在不同样本上悄悄计算。估计误差、交易成本与现实约束需另行处理；一条画出来的边界不能证明未来表现。",en:"Editorial application: freeze return definitions, the universe, observation windows and missingness rules before estimation. Align covariance inputs to a defensible common sample. Estimation error, trading costs and real constraints need separate treatment; a plotted frontier does not validate future performance."}}],readerLimits:{zh:"本文建立的是给定预期与协方差后的选择框架；样本估计、偏好和现实约束改变时，结果也会改变。",en:"This is a conditional choice framework. Estimated inputs, preferences and real-world constraints can change the result."}},{id:"capital-asset-prices-a-theory-of-market-equilibrium-under-conditions-of-risk",title:"Capital Asset Prices: A Theory of Market Equilibrium under Conditions of Risk",titleZh:"资本资产价格：风险条件下的市场均衡理论",sourceTitle:"CAPITAL ASSET PRICES: A THEORY OF MARKET EQUILIBRIUM UNDER CONDITIONS OF RISK*",authors:"William F. Sharpe",venue:"The Journal of Finance",year:"1964",kind:"paper",topic:"asset-pricing",data:"asset returns; market proxy; risk-free series",dataZh:"资产收益；市场代理；无风险序列",summary:{en:"Frames expected returns through systematic risk and an equilibrium market portfolio.",zh:"用系统性风险与市场组合界定预期收益的理论参照。"},related:{datasets:["cn-equity-daily","cn-pit-fundamentals"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/j.1540-6261.1964.tb02865.x"}],readingNotes:[{title:{zh:"从组合选择走向价格均衡",en:"From portfolio choice to equilibrium prices"},body:{zh:"Sharpe关心分散投资之后，哪种风险仍会进入资产价格。把单个资产看起来很波动，直接等同于它应获得更高收益，会忽略其与组合其他资产的共同变化。这也是理解理论为何从组合出发，而不是从单只股票排名出发的关键。",en:"Sharpe asks which risk remains priced after diversification. Standalone volatility misses an asset's interaction with the rest of a portfolio, motivating an equilibrium rather than a stock-ranking argument."},reference:{url:"https://cdn.uw.edu/wp-content/uploads/sites/103/2022/07/12172209/Sharpe-1964-Capital-Asset-Prices-seminal-article.pdf",label:{zh:"原文定位：1964年期刊版，第425–426页",en:"Source: 1964 journal article, pp. 425–426"}}},{title:{zh:"相关性改变组合机会",en:"Correlation changes portfolio opportunities"},body:{zh:"组合风险不仅取决于各项资产自身波动，也取决于它们如何一起变化。两个波动相近的资产，放入同一组合后的贡献可能不同。判断资产作用时需要整个协方差结构，不能只根据每只资产的单独风险大小进行排序。",en:"Portfolio opportunities depend on co-movement as well as individual volatility. Similar standalone risks can make different contributions to a combination; isolated risk rankings lose that distinction."},reference:{url:"https://cdn.uw.edu/wp-content/uploads/sites/103/2022/07/12172209/Sharpe-1964-Capital-Asset-Prices-seminal-article.pdf",label:{zh:"原文定位：1964年期刊版，第431–432页",en:"Source: 1964 journal article, pp. 431–432"}}},{title:{zh:"共同预期是一项强假设",en:"Shared expectations are a strong assumption"},body:{zh:"均衡推导假设投资者对预期收益、波动和相关性具有共同判断，并能按相同条件借贷。作者承认这些假设很强。现实中的观点分歧、融资成本和约束不因此消失；应用模型时，应把这些差异看作待检验的边界。",en:"Investors share forecasts and borrowing terms in the equilibrium construction. These restrictive assumptions do not erase real disagreements or financing constraints; application needs to confront those differences."},reference:{url:"https://cdn.uw.edu/wp-content/uploads/sites/103/2022/07/12172209/Sharpe-1964-Capital-Asset-Prices-seminal-article.pdf",label:{zh:"原文定位：1964年期刊版，第433–434页",en:"Source: 1964 journal article, pp. 433–434"}}},{title:{zh:"风险组合与风险承担程度分开",en:"Separate the risky combination from risk tolerance"},body:{zh:"在给定条件下，选择风险资产组合与决定借入或贷出多少资金可以分开考虑。共同组合不意味着所有投资者承担相同风险，其与无风险资产的配置仍会不同。若借贷条件改变，这种分离的适用性也要重新分析。",en:"Under the stated conditions, choosing the risky combination separates from borrowing or lending. Sharing that combination does not mean investors choose identical overall risk exposure."},reference:{url:"https://cdn.uw.edu/wp-content/uploads/sites/103/2022/07/12172209/Sharpe-1964-Capital-Asset-Prices-seminal-article.pdf",label:{zh:"原文定位：1964年期刊版，第433页",en:"Source: 1964 journal article, pp. 433"}}},{title:{zh:"系统风险与总风险不同",en:"Systematic exposure differs from total risk"},body:{zh:"论文将资产对有效组合收益变化的敏感度与不能通过加入该组合消除的风险联系起来。这种敏感度不是资产的全部波动，也不是相关系数本身。模型讨论预期收益与这种暴露的关系，不能直接把资本市场线用于每个未分散资产。",en:"Sensitivity to an efficient combination identifies systematic exposure, distinct from total volatility or correlation alone. The capital-market relation for efficient portfolios is not a standalone-volatility rule for every asset."},reference:{url:"https://cdn.uw.edu/wp-content/uploads/sites/103/2022/07/12172209/Sharpe-1964-Capital-Asset-Prices-seminal-article.pdf",label:{zh:"原文定位：1964年期刊版，第436, 439–440页",en:"Source: 1964 journal article, pp. 436, 439–440"}}},{title:{zh:"事前关系不等于事后每期兑现",en:"An expected relation is not a realized guarantee"},body:{zh:"理论中的预期收益与风险暴露属于事前判断，而实际样本回报会受意外变化影响。历史回归可以帮助提出检验问题，却不是理论自动兑现的证明。选择哪个市场代理以及用什么窗口估计，都需要另行说明，不能从模型名称直接得到答案。",en:"The relation concerns expectations, not guaranteed realized returns. Historical estimates need explicit market proxies and windows; a model's name cannot supply those empirical choices or validate their results."},reference:{url:"https://cdn.uw.edu/wp-content/uploads/sites/103/2022/07/12172209/Sharpe-1964-Capital-Asset-Prices-seminal-article.pdf",label:{zh:"原文定位：1964年期刊版，第439–440页",en:"Source: 1964 journal article, pp. 439–440"}}}],readerLimits:{zh:"这是带有共同预期、借贷条件等假设的均衡模型，不是历史拟合结果或收益预测保证。市场代理、估计窗口与实际融资约束仍需单独检验。",en:"This equilibrium model relies on shared expectations and borrowing assumptions. It is not empirical validation or a return guarantee; market proxies and actual financing constraints require separate scrutiny."}},{id:"the-valuation-of-risk-assets-and-the-selection-of-risky-investments-in-stock-portfolios-and-capital-budgets",title:"The Valuation of Risk Assets and the Selection of Risky Investments in Stock Portfolios and Capital Budgets",titleZh:"风险资产估值与风险投资选择",sourceTitle:"The Valuation of Risk Assets and the Selection of Risky Investments in Stock Portfolios and Capital Budgets",authors:"John Lintner",venue:"The Review of Economics and Statistics",year:"1965",kind:"paper",topic:"asset-pricing",data:"asset returns; market weights; risk-free rate",dataZh:"资产收益；市场权重；无风险利率",summary:{en:"Develops an equilibrium account of risk pricing and portfolio choice.",zh:"研究风险如何进入资产定价与组合选择的均衡框架。"},related:{datasets:["cn-equity-daily","cn-pit-fundamentals"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.2307/1924119"}]},{id:"an-intertemporal-capital-asset-pricing-model",title:"An Intertemporal Capital Asset Pricing Model",titleZh:"跨期资本资产定价模型",sourceTitle:"An Intertemporal Capital Asset Pricing Model",authors:"Robert C. Merton",venue:"Econometrica",year:"1973",kind:"paper",topic:"asset-pricing",data:"returns; state variables; investment horizon",dataZh:"收益；状态变量；投资期限",summary:{en:"Adds changing investment opportunities and hedging demands to asset-pricing analysis.",zh:"将投资机会变化与跨期对冲需求纳入资产定价分析。"},related:{datasets:["cn-equity-daily","cn-pit-fundamentals"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.2307/1913811"}]},{id:"the-arbitrage-theory-of-capital-asset-pricing",title:"The Arbitrage Theory of Capital Asset Pricing",titleZh:"资本资产定价的套利理论",sourceTitle:"The arbitrage theory of capital asset pricing",authors:"Stephen A Ross",venue:"Journal of Economic Theory",year:"1976",kind:"paper",topic:"asset-pricing",data:"return panel; factor exposures; residual covariance",dataZh:"收益面板；因子暴露；残差协方差",summary:{en:"Relates a factor structure in returns to restrictions implied by no-arbitrage.",zh:"考察收益因子结构与无套利条件对价格关系的约束。"},related:{datasets:["cn-equity-daily","cn-pit-fundamentals"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/0022-0531(76)90046-6"}]},{id:"risk-return-and-equilibrium-empirical-tests",title:"Risk, Return, and Equilibrium: Empirical Tests",titleZh:"风险、收益与均衡：实证检验",sourceTitle:"Risk, Return, and Equilibrium: Empirical Tests",authors:"Eugene F. Fama · James D. MacBeth",venue:"Journal of Political Economy",year:"1973",kind:"paper",topic:"asset-pricing",data:"security returns; portfolio formation dates; betas",dataZh:"证券收益；组合形成日期；贝塔估计",summary:{en:"Introduces cross-sectional testing of the relation between estimated risk and average returns.",zh:"展示如何在横截面上检验风险估计与平均收益之间的关系。"},related:{datasets:["cn-equity-daily","cn-pit-fundamentals"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.1086/260061"}]},{id:"the-equity-premium-a-puzzle",title:"The Equity Premium: A Puzzle",titleZh:"股权溢价之谜",sourceTitle:"The equity premium: A puzzle",authors:"Rajnish Mehra · Edward C. Prescott",venue:"Journal of Monetary Economics",year:"1985",kind:"paper",topic:"asset-pricing",data:"equity returns; consumption; safe-asset returns",dataZh:"股票收益；消费；安全资产收益",summary:{en:"Compares historical equity premia with a representative-agent consumption model.",zh:"将历史股权溢价与代表性投资者的消费模型进行比较。"},related:{datasets:["cn-equity-daily","cn-pit-fundamentals"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/0304-3932(85)90061-3"}]},{id:"asset-prices-in-an-exchange-economy",title:"Asset Prices in an Exchange Economy",titleZh:"交换经济中的资产价格",sourceTitle:"Asset Prices in an Exchange Economy",authors:"Robert E. Lucas",venue:"Econometrica",year:"1978",kind:"paper",topic:"asset-pricing",data:"consumption; dividends; state transitions",dataZh:"消费；股息；状态转移",summary:{en:"Builds a consumption-based equilibrium model linking payouts and asset prices.",zh:"构建以消费为基础的均衡模型，连接资产支付与价格。"},related:{datasets:["cn-equity-daily","cn-pit-fundamentals"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.2307/1913837"}]},{id:"habit-formation-a-resolution-of-the-equity-premium-puzzle",title:"Habit Formation: A Resolution of the Equity Premium Puzzle",titleZh:"习惯形成与股权溢价之谜",sourceTitle:"Habit Formation: A Resolution of the Equity Premium Puzzle",authors:"George M. Constantinides",venue:"Journal of Political Economy",year:"1990",kind:"paper",topic:"asset-pricing",data:"consumption history; equity returns; model parameters",dataZh:"消费历史；股票收益；模型参数",summary:{en:"Examines how consumption habits alter risk preferences in asset-pricing models.",zh:"研究消费习惯如何改变资产定价模型中的风险偏好。"},related:{datasets:["cn-equity-daily","cn-pit-fundamentals"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.1086/261693"}]},{id:"by-force-of-habit-a-consumption-based-explanation-of-aggregate-stock-market-behavior",title:"By Force of Habit: A Consumption-Based Explanation of Aggregate Stock Market Behavior",titleZh:"习惯的力量：股票市场行为的消费解释",sourceTitle:"By Force of Habit: A Consumption‐Based Explanation of Aggregate Stock Market Behavior",authors:"John Y. Campbell · John H. Cochrane",venue:"Journal of Political Economy",year:"1999",kind:"paper",topic:"asset-pricing",data:"consumption growth; market returns; valuation ratios",dataZh:"消费增长；市场收益；估值比率",summary:{en:"Uses habit dynamics to connect consumption risk with aggregate market fluctuations.",zh:"利用习惯动态连接消费风险与整体市场波动。"},related:{datasets:["cn-equity-daily","cn-pit-fundamentals"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.1086/250059"}]},{id:"risks-for-the-long-run-a-potential-resolution-of-asset-pricing-puzzles",title:"Risks for the Long Run: A Potential Resolution of Asset Pricing Puzzles",titleZh:"长期风险与资产定价难题",sourceTitle:"Risks for the Long Run: A Potential Resolution of Asset Pricing Puzzles",authors:"Ravi Bansal · Amir Yaron",venue:"The Journal of Finance",year:"2004",kind:"paper",topic:"asset-pricing",data:"consumption; dividends; volatility estimates",dataZh:"消费；股息；波动率估计",summary:{en:"Studies persistent consumption growth and uncertainty as ingredients in asset pricing.",zh:"研究持续性消费增长与不确定性在资产定价中的作用。"},related:{datasets:["cn-equity-daily","cn-pit-fundamentals"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/j.1540-6261.2004.00670.x"}]},{id:"a-five-factor-asset-pricing-model",title:"A Five-Factor Asset Pricing Model",titleZh:"五因子资产定价模型",sourceTitle:"A five-factor asset pricing model",authors:"Eugene F. Fama · Kenneth R. French",venue:"Journal of Financial Economics",year:"2015",kind:"paper",topic:"asset-pricing",data:"returns; book equity; operating profits; investment",dataZh:"收益；账面权益；营业利润；投资",summary:{en:"Extends size and value comparisons with profitability and investment characteristics.",zh:"在规模与价值之外加入盈利能力和投资特征进行比较。"},related:{datasets:["cn-equity-daily","cn-pit-fundamentals"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/j.jfineco.2014.10.010"}],readingNotes:[{title:{zh:"为什么再加入盈利与投资？",en:"Why add profitability and investment?"},body:{zh:"作者从估值关系出发，说明账面市值比之外，预期盈利与投资也可能关联平均收益。五因子模型因此加入盈利和投资组合收益。这个动机解释了变量为何值得研究，却不单独证明某一种风险或错误定价机制是所有结果的唯一原因。",en:"Valuation relations motivate looking beyond book-to-market to expected profitability and investment. The model adds portfolio returns associated with those dimensions. This rationale explains why the variables deserve attention without uniquely identifying a risk mechanism or mispricing explanation for every empirical result."},reference:{url:"https://tevgeniou.github.io/EquityRiskFactors/bibliography/FiveFactor.pdf",label:{zh:"原文定位：2015年期刊版，第1–3页",en:"Source: 2015 journal article, pp. 1–3"}}},{title:{zh:"因子是组合收益，不是公司评分",en:"Factors are portfolio returns, not firm scores"},body:{zh:"RMW比较盈利强与弱的分散组合收益，CMA比较投资保守与激进的组合收益，另有市场、规模和价值因子。公司盈利水平是排序特征，对RMW的回归载荷则是收益敏感度。两者有联系，但不能把会计比率直接当成因子收益或载荷。",en:"RMW contrasts diversified robust- and weak-profitability portfolios; CMA contrasts conservative and aggressive investment portfolios alongside market, size and value factors. A firm's profitability is a sorting characteristic, while its RMW loading measures return sensitivity. Neither the factor return nor its loading is simply an accounting ratio."},reference:{url:"https://tevgeniou.github.io/EquityRiskFactors/bibliography/FiveFactor.pdf",label:{zh:"原文定位：2015年期刊版，第3页",en:"Source: 2015 journal article, pp. 3"}}},{title:{zh:"这里的盈利分母是账面权益",en:"Operating profitability uses book equity"},body:{zh:"文中的经营盈利以收入减去销售成本、销售及管理费用和利息费用，再除以账面权益。它不同于毛利润除以总资产，也不同于销售利润率。比较另一篇论文或数据字段时，要逐项核对费用范围、分母与财政年度，不能只看“盈利能力”这个名称。",en:"Operating profitability subtracts cost of goods sold, selling and administrative expenses, and interest expense from revenue, then divides by book equity. It differs from gross profit over assets and from a sales margin. Comparing papers or fields requires the expense scope, denominator and fiscal year, not just a shared profitability label."},reference:{url:"https://tevgeniou.github.io/EquityRiskFactors/bibliography/FiveFactor.pdf",label:{zh:"原文定位：2015年期刊版，第3页",en:"Source: 2015 journal article, pp. 3"}}},{title:{zh:"投资增长与排序时点相互配合",en:"Investment growth needs dated accounting inputs"},body:{zh:"投资指标使用上一财政年度总资产的增量，除以前一年度总资产。组合每年六月末排序，采用此前财政年度会计资料与规定的市值时点。保留这些时点才能理解组合形成，不能把后来修订的财报当作历史排序日已经掌握的信息。",en:"Investment uses the prior fiscal year's increase in total assets divided by assets one year earlier. Portfolios are sorted at the end of June using preceding fiscal-year accounts and specified market-value dates. These conventions matter: a subsequently revised filing is not evidence of what was known on the historical sorting date."},reference:{url:"https://tevgeniou.github.io/EquityRiskFactors/bibliography/FiveFactor.pdf",label:{zh:"原文定位：2015年期刊版，第3页",en:"Source: 2015 journal article, pp. 3"}}},{title:{zh:"检验的对象是有意拉开差异的组合",en:"Test portfolios deliberately span characteristics"},body:{zh:"研究通过规模与账面市值比、盈利或投资的排序构造组合，观察模型能否解释平均收益差异。若因子完整捕捉预期收益，超额收益回归截距应为零。组合拟合好与这一截距条件不是同一回事，多维排序还可能带来稀疏或分散不足的问题。",en:"Size sorts combined with book-to-market, profitability or investment create test portfolios with different average returns. Complete capture of expected returns implies zero excess-return regression intercepts. Good fit is a different criterion, and multidimensional sorting can also create sparse or poorly diversified cells."},reference:{url:"https://tevgeniou.github.io/EquityRiskFactors/bibliography/FiveFactor.pdf",label:{zh:"原文定位：2015年期刊版，第3–4页",en:"Source: 2015 journal article, pp. 3–4"}}},{title:{zh:"冗余结论有样本边界",en:"Redundancy is a sample-dependent finding"},body:{zh:"论文的主要样本是1963年7月至2013年12月的美国股票。作者讨论加入新因子后的HML冗余，也指出低盈利且高投资的小股票带来的困难。理解这些结果要保留检验时期与组合选择，不能推导出价值永久失效或五因子普遍完备。",en:"The main US sample runs from July 1963 to December 2013. The paper discusses HML redundancy after adding the new factors and difficulties with small, weak-profitability, high-investment stocks. Neither finding establishes that value is permanently obsolete or that five factors universally complete an asset-pricing model."},reference:{url:"https://tevgeniou.github.io/EquityRiskFactors/bibliography/FiveFactor.pdf",label:{zh:"原文定位：2015年期刊版，第1–4页",en:"Source: 2015 journal article, pp. 1–4"}}}],readerLimits:{zh:"五因子解释力取决于样本与检验组合。某个样本中的价值因子冗余，不代表价值特征永久无用；模型也不是个股收益承诺。",en:"Explanatory power depends on the sample and test portfolios. Value-factor redundancy in one sample does not make value characteristics permanently irrelevant or turn the model into a return promise."}},{id:"dissecting-anomalies-with-a-five-factor-model",title:"Dissecting Anomalies with a Five-Factor Model",titleZh:"用五因子模型分析异象",sourceTitle:"Dissecting Anomalies with a Five-Factor Model",authors:"Eugene F. Fama · Kenneth R. French",venue:"Review of Financial Studies",year:"2016",kind:"paper",topic:"asset-pricing",data:"factor returns; characteristic portfolios; sample definitions",dataZh:"因子收益；特征组合；样本定义",summary:{en:"Examines which return patterns remain after controlling for five common factors.",zh:"考察控制五个共同因子后，哪些收益模式仍有待解释。"},related:{datasets:["cn-equity-daily","cn-pit-fundamentals"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.1093/rfs/hhv043"}]},{id:"digesting-anomalies-an-investment-approach",title:"Digesting Anomalies: An Investment Approach",titleZh:"从投资视角理解异象",sourceTitle:"Digesting Anomalies: An Investment Approach",authors:"Kewei Hou · Chen Xue · Lu Zhang",venue:"Review of Financial Studies",year:"2015",kind:"paper",topic:"asset-pricing",data:"firm investment; profitability; market equity; returns",dataZh:"企业投资；盈利能力；市值；收益",summary:{en:"Organizes return comparisons around investment and profitability in a production-based framework.",zh:"在生产侧框架中围绕投资与盈利能力组织收益比较。"},related:{datasets:["cn-equity-daily","cn-pit-fundamentals"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.1093/rfs/hhu068"}]},{id:"replicating-anomalies",title:"Replicating Anomalies",titleZh:"复现异象",sourceTitle:"Replicating Anomalies",authors:"Kewei Hou · Chen Xue · Lu Zhang",venue:"The Review of Financial Studies",year:"2020",kind:"paper",topic:"research-methods",data:"published signal definitions; security panel; delistings",dataZh:"已发表变量定义；证券面板；退市数据",summary:{en:"Shows why portfolio construction, microcap treatment, and significance thresholds matter in replication.",zh:"说明组合构造、微盘股处理与显著性门槛为何影响复现。"},related:{recipes:["pit-fundamentals-panel","adjusted-price-series"]},sources:[{label:"DOI",url:"https://doi.org/10.1093/rfs/hhy131"}],readingNotes:[{title:{zh:"同一个名称是否代表同一个实验？",en:"Does a name identify an experiment?"},body:{zh:"Hou、Xue与Zhang把大量已发表的异象放进统一复现框架。核心问题不只是是否再次得到显著结果，还包括变量定义、股票范围、分组方式与权重改变后，原有解释是否仍成立。",en:"Hou, Xue and Zhang bring reported anomalies into a common replication framework. The question includes variable definitions, universes, grouping and weighting, not merely whether significance reappears."}},{title:{zh:"统一样本，也统一信息时钟",en:"Harmonize samples and information clocks"},body:{zh:"2017年工作论文将CRSP月收益与COMPUSTAT财务资料连接。年度分组使用上一财年的资料；月度分组则区分已公告盈余与其他季度会计项目，后者采用四个月滞后。这个区分承认盈余新闻稿不一定同时披露资产负债表，不能把所有字段都视为同一天可得。",en:"The 2017 working paper joins CRSP monthly returns with COMPUSTAT accounts. Annual sorts use prior-fiscal-year data; monthly sorts distinguish announced earnings from other quarterly items, for which a four-month lag is imposed. Earnings releases need not contain balance sheets, so all accounting fields cannot share an assumed availability date."},reference:{url:"https://www.nber.org/system/files/working_papers/w23394/w23394.pdf",label:{zh:"2017年工作论文第3–3.1节：信息滞后",en:"2017 working paper §§3–3.1: information lags"}}},{title:{zh:"微型股为什么影响比较",en:"Why microcaps matter"},body:{zh:"作者通过纽约证券交易所断点和市值加权，降低微型股对比较的主导作用。等权与市值加权回答的对象不同，因此不能只比较结果名称，而不比较样本中哪些公司实际上贡献最大。",en:"NYSE breakpoints and value weighting reduce microcap influence. Equal- and value-weighted results describe different objects, so comparing labels without checking which firms dominate can mislead."}},{title:{zh:"显著性之外还有复现口径",en:"Replication is more than significance"},body:{zh:"论文报告许多结果在统一标准下减弱或不再显著，并讨论多重检验。不能由此推导所有异象都不存在；相反，需要说明什么定义、样本和统计标准产生了什么证据。工作论文与定稿的统计数量也不可混用。",en:"Many results weaken under harmonized standards, with multiple testing adding another hurdle. This does not prove every anomaly absent. Definitions, samples and inference standards must accompany findings; draft and final counts are not interchangeable."}},{title:{zh:"退市处理也属于复现合同",en:"Delisting treatment belongs in the replication contract"},body:{zh:"作者单独说明如何合并CRSP退市收益，以及缺失退市收益的处理。编辑建议：除记录断点和权重，还应列明退出样本的原因、退市回报来源与替代规则。只保留持续上市企业，或者把退市缺失值静默设为零，都会改变正在比较的实验。",en:"The authors document how CRSP delisting returns are combined with ordinary returns and how missing delisting observations are handled. Editorial application: record exit reasons, sources and substitution rules alongside breakpoints and weights. Keeping only surviving listings or silently replacing missing delisting returns with zero changes the experiment."},reference:{url:"https://www.nber.org/system/files/working_papers/w23394/w23394.pdf",label:{zh:"2017年工作论文第3.1节：退市收益处理",en:"2017 working paper §3.1: delisting-return treatment"}}},{title:{zh:"回到应计研究重新提问",en:"Return to accrual studies"},body:{zh:"读完Sloan和Dechow–Dichev后，可以用这篇重新检查财务变量怎样构建。本站建议保留原始字段、版本、筛选记录和每一步样本数量，把无法复现的环节当作明确缺口，而不是用相近指标补齐后继续沿用原结论。",en:"After Sloan and Dechow–Dichev, revisit accounting-variable construction. Keep raw fields, versions, exclusions and sample counts. A substituted proxy should be named as a change, not quietly presented as replication."}}],readerLimits:{zh:"导读依据2017年工作论文讨论复现原则；具体清单与检验以期刊定稿为准。未显著不等于证明效应为零。",en:"The guide uses the 2017 working paper for replication principles; consult the journal edition for its final inventory and tests. Insignificance is not proof of zero effect."}},{id:"and-the-cross-section-of-expected-returns",title:"… and the Cross-Section of Expected Returns",titleZh:"多重检验与预期收益横截面",sourceTitle:"… and the Cross-Section of Expected Returns",authors:"Campbell R. Harvey · Yan Liu · Heqing Zhu",venue:"Review of Financial Studies",year:"2016",kind:"paper",topic:"research-methods",data:"factor test inventory; test statistics; dependence",dataZh:"因子检验清单；检验统计量；依赖关系",summary:{en:"Examines the statistical burden created by testing many proposed return factors.",zh:"讨论大量候选收益因子检验带来的统计负担。"},related:{recipes:["pit-fundamentals-panel","adjusted-price-series"]},sources:[{label:"DOI",url:"https://doi.org/10.1093/rfs/hhv059"}]},{id:"the-other-side-of-value-the-gross-profitability-premium",title:"The Other Side of Value: The Gross Profitability Premium",titleZh:"价值的另一面：毛利能力溢价",sourceTitle:"The other side of value: The gross profitability premium",authors:"Robert Novy-Marx",venue:"Journal of Financial Economics",year:"2013",kind:"paper",topic:"corporate-fundamentals",data:"gross profits; total assets; book equity; returns",dataZh:"毛利；总资产；账面权益；收益",summary:{en:"Studies gross profitability alongside valuation when comparing firms.",zh:"在企业比较中将毛利能力与估值共同考察。"},related:{datasets:["cn-pit-fundamentals","cn-company-master"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/j.jfineco.2013.01.003"}],readingNotes:[{title:{zh:"毛利能力，不是通常所说的毛利率",en:"Gross profitability is not gross margin"},body:{zh:"Novy-Marx用毛利除以账面总资产来衡量毛利能力，其中毛利由收入减去销售成本得到。它不是毛利除以收入的毛利率，也不是净利润除以权益的ROE。分母从收入换成资产后，问题从每单位销售留下多少毛利，变成每单位资产支持多少毛利，经济含义随之改变。",en:"The measure divides gross profits, revenue less cost of goods sold, by book assets. It is not gross margin, which divides gross profits by sales, or ROE, which uses earnings and equity. Changing the denominator changes the question from profit per unit of sales to gross profits supported by the asset base."},reference:{url:"https://mysimon.rochester.edu/novy-marx/research/OSoV.pdf",label:{zh:"原文定位：2012年6月作者稿，第1、5–7页",en:"Source: June 2012 author draft, pp. 1, 5–7"}}},{title:{zh:"为什么不只看净利润？",en:"Why look above bottom-line earnings?"},body:{zh:"作者认为，广告、研发及组织能力建设等当期费用，可能压低净利润，却不一定表示经营生产力更弱。因此论文考察更靠近生产活动的毛利口径。这个解释不是说所有被扣除的费用都无关紧要，而是要求在比较盈利指标之前，先理解它们包含或排除了哪些经营投入。",en:"The author argues that current spending on advertising, R&D or organizational capability can depress earnings without implying weaker productivity. Gross profits offer a different view of operations. This does not make excluded expenses irrelevant; comparisons should identify which operating investments each profitability measure includes or leaves out."},reference:{url:"https://mysimon.rochester.edu/novy-marx/research/OSoV.pdf",label:{zh:"原文定位：2012年6月作者稿，第4–5页",en:"Source: June 2012 author draft, pp. 4–5"}}},{title:{zh:"财务年份不等于可用日期",en:"Fiscal year is not availability time"},body:{zh:"作者稿把某财政年度的会计数据从下一日历年6月底开始用于研究，资产定价检验覆盖1963年7月至2010年12月，并排除金融企业。这个时滞是原样本设计，不证明别的市场在同一天已经全部披露。迁移时仍要核对真实公告日期、修订版本与行业定义，不能把报告期末直接当成可用日期。",en:"The draft uses a fiscal year's accounting data from the end of June in the next calendar year; tests span July 1963–December 2010 and exclude financial firms. That lag is a sample convention, not proof of publication elsewhere. Transfer requires actual publication dates, filing versions and industry definitions rather than period-end availability."},reference:{url:"https://mysimon.rochester.edu/novy-marx/research/OSoV.pdf",label:{zh:"原文定位：2012年6月作者稿，第6页",en:"Source: June 2012 author draft, pp. 6"}}},{title:{zh:"与估值一起比较，而非单独排序",en:"Compare profitability alongside valuation"},body:{zh:"横截面回归同时考虑账面市值比、规模与过去收益，再比较毛利／资产、净利润／权益和自由现金流／权益。作者还检查行业调整后的口径。这样的问题是毛利能力是否带来额外信息，而不是只展示高毛利组合的表现；控制变量、分母与样本需要一并阅读。",en:"Cross-sectional regressions control for book-to-market, size and past returns while comparing gross profits/assets with earnings/equity and free cash flow/equity. Industry-adjusted versions are also examined. The question is incremental information, not merely the performance of a high-profitability portfolio; controls, denominators and the sample matter together."},reference:{url:"https://mysimon.rochester.edu/novy-marx/research/OSoV.pdf",label:{zh:"原文定位：2012年6月作者稿，第6–7页",en:"Source: June 2012 author draft, pp. 6–7"}}},{title:{zh:"先分清统计结果与经营解释",en:"Separate the result from its interpretation"},body:{zh:"在作者稿所报告的比较中，毛利能力保留了较强的横截面解释信息，加入其他盈利指标后也不完全消失。这是一组设定与历史样本下的结果，不是毛利率、资产周转率或所有“质量”指标都等价的证明。论文还分别讨论毛利率和资产周转，说明相似名称不能替代变量定义。",en:"In the draft's reported comparisons, gross profitability retains substantial cross-sectional information alongside other earnings measures. This is conditional historical evidence, not proof that gross margin, asset turnover or every quality metric is interchangeable. The paper examines those components separately, reinforcing the importance of exact variable definitions."},reference:{url:"https://mysimon.rochester.edu/novy-marx/research/OSoV.pdf",label:{zh:"原文定位：2012年6月作者稿，第7页",en:"Source: June 2012 author draft, pp. 7"}}},{title:{zh:"建立可解释的财务输入表",en:"Build an interpretable accounting input table"},body:{zh:"准备对应研究时，可以分别保存收入、销售成本、毛利、总资产、财政期间与披露版本，再记录缩放和行业处理。毛利缺失不能自动用净利润替代；不同会计准则的成本归类也需核对。保留这些差异，才能判断结果来自企业经营特征，还是来自数据口径与样本选择。",en:"Retain revenue, cost of goods sold, gross profits, assets, fiscal periods and filing versions separately, alongside scaling and industry treatment. Missing gross profits must not silently become net income. Cost classifications can differ across accounting regimes; preserving them helps distinguish economic variation from input and sample choices."},reference:{url:"https://mysimon.rochester.edu/novy-marx/research/OSoV.pdf",label:{zh:"原文定位：2012年6月作者稿，第5–7页",en:"Source: June 2012 author draft, pp. 5–7"}}}],readerLimits:{zh:"导读采用2012年6月作者稿，保留2013年期刊题录；具体最终设定请核对期刊原文。指标是毛利／资产而非毛利率，不是统一的质量评分，也不保证当前或A股市场的收益。",en:"This guide uses the June 2012 author draft while retaining the 2013 journal citation; consult the final article for definitive specifications. Gross profits/assets is not gross margin or a universal quality score, and does not guarantee current or A-share returns."}},{id:"value-and-momentum-everywhere",title:"Value and Momentum Everywhere",titleZh:"跨资产的价值与动量",sourceTitle:"Value and Momentum Everywhere",authors:"CLIFFORD S. ASNESS · TOBIAS J. MOSKOWITZ · LASSE HEJE PEDERSEN",venue:"The Journal of Finance",year:"2013",kind:"paper",topic:"asset-pricing",data:"multi-asset prices; value measures; currencies",dataZh:"多资产价格；价值指标；币种",summary:{en:"Compares value and momentum definitions across markets and asset classes.",zh:"比较不同市场与资产类别中的价值和动量定义。"},related:{datasets:["cn-equity-daily","cn-pit-fundamentals"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/jofi.12021"}]},{id:"time-series-momentum",title:"Time Series Momentum",titleZh:"时间序列动量",sourceTitle:"Time series momentum",authors:"Tobias J. Moskowitz · Yao Hua Ooi · Lasse Heje Pedersen",venue:"Journal of Financial Economics",year:"2012",kind:"paper",topic:"quant-methods",data:"futures returns; contract rolls; volatility; collateral",dataZh:"期货收益；换月；波动率；保证金现金",summary:{en:"Examines an asset's own past returns across futures markets.",zh:"以期货市场为样本，研究资产自身历史收益的统计关系。"},related:{recipes:["pit-fundamentals-panel","adjusted-price-series"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/j.jfineco.2011.11.003"}]},{id:"betting-against-beta",title:"Betting Against Beta",titleZh:"贝塔约束与低风险资产研究",sourceTitle:"Betting against beta",authors:"Andrea Frazzini · Lasse Heje Pedersen",venue:"Journal of Financial Economics",year:"2014",kind:"paper",topic:"asset-pricing",data:"asset betas; financing rates; leverage constraints",dataZh:"资产贝塔；融资利率；杠杆约束",summary:{en:"Studies leverage constraints and the pricing of assets with different market betas.",zh:"研究杠杆约束与不同市场贝塔资产的定价关系。"},related:{datasets:["cn-equity-daily","cn-pit-fundamentals"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/j.jfineco.2013.10.005"}]},{id:"idiosyncratic-risk-and-the-cross-section-of-expected-stock-returns",title:"Idiosyncratic Risk and the Cross-Section of Expected Stock Returns",titleZh:"特质风险与预期股票收益横截面",sourceTitle:"Idiosyncratic risk and the cross-section of expected stock returns",authors:"Fangjian Fu",venue:"Journal of Financial Economics",year:"2009",kind:"paper",topic:"asset-pricing",data:"daily returns; factor model; volatility estimates",dataZh:"日收益；因子模型；波动率估计",summary:{en:"Separates systematic volatility exposures from firm-specific return variation.",zh:"区分系统性波动暴露与企业特有的收益变化。"},related:{datasets:["cn-equity-daily","cn-pit-fundamentals"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/j.jfineco.2008.02.003"}]},{id:"expected-stock-returns-and-volatility",title:"Expected Stock Returns and Volatility",titleZh:"预期股票收益与波动率",sourceTitle:"Expected stock returns and volatility",authors:"Kenneth R. French · G.William Schwert · Robert F. Stambaugh",venue:"Journal of Financial Economics",year:"1987",kind:"paper",topic:"asset-pricing",data:"market returns; realized volatility; risk-free rates",dataZh:"市场收益；已实现波动率；无风险利率",summary:{en:"Investigates the relationship between market volatility and expected stock returns.",zh:"考察市场波动率与预期股票收益的关系。"},related:{datasets:["cn-equity-daily","cn-pit-fundamentals"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/0304-405x(87)90026-2"}]},{id:"the-cross-section-of-volatility-and-expected-returns",title:"The Cross-Section of Volatility and Expected Returns",titleZh:"波动率与预期收益的横截面",sourceTitle:"The Cross‐Section of Volatility and Expected Returns",authors:"ANDREW ANG · ROBERT J. HODRICK · YUHANG XING · XIAOYAN ZHANG",venue:"The Journal of Finance",year:"2006",kind:"paper",topic:"asset-pricing",data:"equity returns; volatility innovations; factor exposures",dataZh:"股票收益；波动创新；因子暴露",summary:{en:"Examines how sensitivities to aggregate volatility relate to cross-sectional returns.",zh:"考察总体波动敏感度与横截面收益之间的关系。"},related:{datasets:["cn-equity-daily","cn-pit-fundamentals"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/j.1540-6261.2006.00836.x"}]},{id:"tests-of-asset-pricing-with-time-varying-expected-risk-premiums-and-market-betas",title:"Tests of Asset Pricing with Time-Varying Expected Risk Premiums and Market Betas",titleZh:"时变风险溢价与市场贝塔下的资产定价检验",sourceTitle:"Tests of Asset Pricing with Time‐Varying Expected Risk Premiums and Market Betas",authors:"WAYNE E. FERSON · SHMUEL KANDEL · ROBERT F. STAMBAUGH",venue:"The Journal of Finance",year:"1987",kind:"paper",topic:"asset-pricing",data:"returns; yield spreads; lagged conditioning variables",dataZh:"收益；收益率利差；滞后条件变量",summary:{en:"Uses changing business conditions to study time-varying expected returns.",zh:"利用经济环境变化研究时变预期收益。"},related:{datasets:["cn-equity-daily","cn-pit-fundamentals"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/j.1540-6261.1987.tb02564.x"}]},{id:"the-dividend-price-ratio-and-expectations-of-future-dividends-and-discount-factors",title:"The Dividend-Price Ratio and Expectations of Future Dividends and Discount Factors",titleZh:"股息价格比、未来股息与贴现因子",sourceTitle:"The Dividend-Price Ratio and Expectations of Future Dividends and Discount Factors",authors:"John Y. Campbell · Robert J. Shiller",venue:"Review of Financial Studies",year:"1988",kind:"paper",topic:"asset-pricing",data:"prices; dividends; log returns; long time series",dataZh:"价格；股息；对数收益；长期序列",summary:{en:"Decomposes valuation ratios into expectations about dividends and discounting.",zh:"将估值比率分解为股息与贴现因素的预期。"},related:{datasets:["cn-equity-daily","cn-pit-fundamentals"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.1093/rfs/1.3.195"}]},{id:"do-stock-prices-move-too-much-to-be-justified-by-subsequent-changes-in-dividends",title:"Do Stock Prices Move Too Much to be Justified by Subsequent Changes in Dividends?",titleZh:"股价波动能否由后续股息变化解释？",sourceTitle:"Do Stock Prices Move Too Much to be Justified by Subsequent Changes in Dividends?",authors:"Robert J. Shiller",venue:"The American Economic Review",year:"1981",kind:"paper",topic:"asset-pricing",data:"long-run prices; dividends; discount-rate assumptions",dataZh:"长期价格；股息；贴现率假设",summary:{en:"Compares stock-price variability with a discounted-dividend benchmark.",zh:"将股价变化与贴现股息基准进行比较。"},related:{datasets:["cn-equity-daily","cn-pit-fundamentals"],recipes:["pit-fundamentals-panel"]},sources:[{label:"The American Economic Review",url:"https://www.aeaweb.org/aer/top20/71.3.421-436.pdf"}]},{id:"stock-prices-earnings-and-expected-dividends",title:"Stock Prices, Earnings, and Expected Dividends",titleZh:"股价、盈利与预期股息",sourceTitle:"Stock Prices, Earnings, and Expected Dividends",authors:"JOHN Y. CAMPBELL · ROBERT J. SHILLER",venue:"The Journal of Finance",year:"1988",kind:"paper",topic:"asset-pricing",data:"earnings; dividends; price indices; inflation",dataZh:"盈利；股息；价格指数；通胀",summary:{en:"Relates price and earnings histories to expectations of future dividend flows.",zh:"利用价格与盈利历史分析未来股息的预期。"},related:{datasets:["cn-equity-daily","cn-pit-fundamentals"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/j.1540-6261.1988.tb04598.x"}]},{id:"on-the-estimation-of-beta-pricing-models",title:"On the Estimation of Beta-Pricing Models",titleZh:"贝塔定价模型的估计",sourceTitle:"On the Estimation of Beta-Pricing Models",authors:"Jay Shanken",venue:"Review of Financial Studies",year:"1992",kind:"paper",topic:"asset-pricing",data:"returns; estimated betas; sampling errors",dataZh:"收益；估计贝塔；采样误差",summary:{en:"Examines inference when risk exposures used in pricing tests are themselves estimated.",zh:"研究定价检验中的风险暴露本身需要估计时的统计推断。"},related:{datasets:["cn-equity-daily","cn-pit-fundamentals"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.1093/rfs/5.1.1"}]},{id:"presidential-address-discount-rates",title:"Presidential Address: Discount Rates",titleZh:"贴现率研究综述",sourceTitle:"Presidential Address: Discount Rates",authors:"JOHN H. COCHRANE",venue:"The Journal of Finance",year:"2011",kind:"paper",topic:"asset-pricing",data:"valuation ratios; returns; macro state variables",dataZh:"估值比率；收益；宏观状态变量",summary:{en:"Surveys variation in discount rates and its implications for interpreting asset prices.",zh:"综述贴现率变化及其对资产价格解释的影响。"},related:{datasets:["cn-equity-daily","cn-pit-fundamentals"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/j.1540-6261.2011.01671.x"}]},{id:"size-and-value-in-china",title:"Size and Value in China",titleZh:"中国市场的规模与价值",sourceTitle:"Size and value in China",authors:"Jianan Liu · Robert F. Stambaugh · Yu Yuan",venue:"Journal of Financial Economics",year:"2019",kind:"paper",topic:"a-share-market",data:"A-share returns; market equity; earnings; listing histories",dataZh:"A股收益；市值；盈利；上市历史",summary:{en:"Adapts size and value comparisons to Chinese market institutions and shell-value effects.",zh:"结合中国市场制度及壳价值问题，讨论规模和价值比较。"},related:{datasets:["cn-equity-daily","cn-company-master","cn-market-reference"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/j.jfineco.2019.03.008"}]},{id:"bid-ask-and-transaction-prices-in-a-specialist-market-with-heterogeneously-informed-traders",title:"Bid, Ask and Transaction Prices in a Specialist Market with Heterogeneously Informed Traders",titleZh:"异质信息交易者下的买价、卖价与成交价",sourceTitle:"Bid, ask and transaction prices in a specialist market with heterogeneously informed traders",authors:"Lawrence R. Glosten · Paul R. Milgrom",venue:"Journal of Financial Economics",year:"1985",kind:"paper",topic:"market-microstructure",data:"bid and ask quotes; transaction prices; trade direction",dataZh:"买卖报价；成交价格；交易方向",summary:{en:"Models how information asymmetry can generate a bid-ask spread.",zh:"解释信息不对称如何形成买卖价差。"},related:{datasets:["cn-equity-minute"],features:["liquidity-measures"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/0304-405x(85)90044-3"}]},{id:"a-simple-implicit-measure-of-the-effective-bid-ask-spread-in-an-efficient-market",title:"A Simple Implicit Measure of the Effective Bid-Ask Spread in an Efficient Market",titleZh:"有效买卖价差的简便隐含度量",sourceTitle:"A Simple Implicit Measure of the Effective Bid-Ask Spread in an Efficient Market",authors:"Richard Roll",venue:"The Journal of Finance",year:"1984",kind:"paper",topic:"market-microstructure",data:"transaction prices; price-change covariance; trading intervals",dataZh:"成交价格；价格变化协方差；交易间隔",summary:{en:"Derives a spread measure from the serial covariance of price changes.",zh:"利用价格变化的序列协方差推导价差度量。"},related:{datasets:["cn-equity-minute"],features:["liquidity-measures"]},sources:[{label:"DOI",url:"https://doi.org/10.2307/2327617"}],readingNotes:[{title:{zh:"成交价会在买卖报价之间跳动",en:"Bid–ask bounce can create serial dependence"},body:{zh:"即使有效价格没有可预测变化，成交也可能交替发生在买价和卖价附近，造成相邻价格变化的负相关结构。Roll利用这个交易摩擦留下的统计痕迹估计价差。它不是把所有短期反转都认定为可获利的价格错误。",en:"Even without predictable movements in efficient value, transactions can alternate near bid and ask prices, leaving negative serial dependence in price changes. Roll uses this statistical footprint of trading friction to infer a spread. The argument does not classify every short-run reversal as a profitable pricing error."},reference:{url:"https://www.bauer.uh.edu/rsusmel/phd/roll1984.pdf",label:{zh:"原文定位：1984年期刊版，第1128–1129页",en:"Source: 1984 journal article, pp. 1128–1129"}}},{title:{zh:"公式使用协方差，不是相关系数",en:"Covariance is not correlation"},body:{zh:"在论文假设下，有效价差等于相邻价格变化协方差取负号后的平方根，再乘以二。这里是协方差而非相关系数：后者已经除去尺度，不能直接代入得到价格单位的价差。计算前应明确变化量、滞后方向和配对观察值。",en:"Under the model, the spread is twice the square root of minus the covariance between adjacent price changes. This is covariance, not correlation: a scale-free correlation cannot be inserted to obtain a spread in price units. Specify the changes, lag direction and paired observations before calculation."},reference:{url:"https://www.bauer.uh.edu/rsusmel/phd/roll1984.pdf",label:{zh:"原文定位：1984年期刊版，第1129页",en:"Source: 1984 journal article, pp. 1129"}}},{title:{zh:"价格变化与收益变化有不同单位",en:"Price changes and returns have different units"},body:{zh:"用价格差计算时，估计结果具有价格单位；使用收益的近似形式时，结果更接近比例口径。跨币种、复权方案或股票价格水平比较前，需要说明输入与缩放。隐含有效价差也不同于屏幕上的报价差，更不包含全部手续费与市场冲击。",en:"Using price differences produces a spread in price units; a return-based approximation instead has a proportional interpretation. Comparisons across currencies, adjustment schemes or price levels need explicit inputs and scaling. An inferred effective spread also differs from a displayed quoted spread and does not include every fee or market-impact cost."},reference:{url:"https://www.bauer.uh.edu/rsusmel/phd/roll1984.pdf",label:{zh:"原文定位：1984年期刊版，第1129–1131页",en:"Source: 1984 journal article, pp. 1129–1131"}}},{title:{zh:"无法估计也是有信息的结果",en:"An unavailable estimate is a diagnostic"},body:{zh:"这个平方根表达式在样本协方差为负时给出正的价差。协方差为正时，实数范围内无法按原式得到价差，可能涉及样本噪声或假设不适用。此时应报告无法估计及其原因；擅自取绝对值或填零会改变方法，不应仍称为未经修改的原始估计。",en:"The square-root expression gives a positive spread for negative sample covariance. A positive covariance does not yield a real-valued spread under that expression and can reflect sampling noise or unsuitable assumptions. Report the estimation failure; silently taking an absolute value or filling zero changes the method rather than preserving the original estimator."},reference:{url:"https://www.bauer.uh.edu/rsusmel/phd/roll1984.pdf",label:{zh:"原文定位：1984年期刊版，第1128–1130页",en:"Source: 1984 journal article, pp. 1128–1130"}}},{title:{zh:"换一个频率，结果为何会变？",en:"Sampling frequency tests the assumptions"},body:{zh:"论文比较日频和周频估计，发现明显差异，而理论中的简化假设并不预期这种差异。作者讨论了价格有效性与非平稳等解释。频率敏感性因此值得作为诊断保留，不能任意挑选数值较低的窗口来声称某只股票交易成本更小。",en:"Daily and weekly estimates differ materially in the paper, despite the simplified theory's sampling-interval implication. The author discusses efficiency and nonstationarity as possible explanations. Retain frequency sensitivity as a diagnostic instead of choosing whichever window produces the lowest number and declaring a stock cheaper to trade."},reference:{url:"https://www.bauer.uh.edu/rsusmel/phd/roll1984.pdf",label:{zh:"原文定位：1984年期刊版，第1134–1135页",en:"Source: 1984 journal article, pp. 1134–1135"}}},{title:{zh:"先保留序列，再解释估计",en:"Preserve the sequence behind the estimate"},body:{zh:"准备数据时应核对成交价定义、复权、交易时段和缺失观察，并明确相邻记录是否真的是相邻交易或相邻时间窗。补零、跨停牌拼接或混合不同频率，都可能改变协方差。保留这些处理记录，才有条件区分交易摩擦与数据加工带来的反转。",en:"For new data, check transaction-price definitions, adjustments, sessions and missing observations. State whether adjacent records represent adjacent trades or time windows. Zero filling, joining across suspensions and mixing frequencies can alter covariance; documented treatment helps distinguish trading friction from reversals introduced during data preparation."},reference:{url:"https://www.bauer.uh.edu/rsusmel/phd/roll1984.pdf",label:{zh:"原文定位：1984年期刊版，第1128–1131, 1134–1135页",en:"Source: 1984 journal article, pp. 1128–1131, 1134–1135"}}}],readerLimits:{zh:"Roll指标依赖有效价格与交易过程假设，是隐含价差估计，不是完整执行成本。样本协方差、采样频率和价格单位会改变可解释性，不能把公式失效静默改写成零成本。",en:"The Roll measure depends on assumptions about efficient prices and trading. It estimates an implicit spread, not total execution costs; sample covariance, frequency and price units constrain interpretation, and an invalid calculation is not evidence of zero cost."}},{id:"measuring-the-information-content-of-stock-trades",title:"Measuring the Information Content of Stock Trades",titleZh:"衡量股票交易的信息含量",sourceTitle:"Measuring the Information Content of Stock Trades",authors:"JOEL HASBROUCK",venue:"The Journal of Finance",year:"1991",kind:"paper",topic:"market-microstructure",data:"signed trades; quotes; timestamps; lag structure",dataZh:"带方向成交；报价；时间戳；滞后结构",summary:{en:"Uses a dynamic system of trades and prices to study information in order flow.",zh:"用交易与价格的动态系统研究订单流的信息含量。"},related:{datasets:["cn-equity-minute"],features:["liquidity-measures"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/j.1540-6261.1991.tb03749.x"}],readingNotes:[{title:{zh:"信息含量关注持久影响",en:"Information content concerns the persistent response"},body:{zh:"Hasbrouck研究交易之后报价的长期调整，而不是只看成交后的即时价格跳动。短期反应可能包含库存管理和交易摩擦；持久部分更接近论文想识别的信息作用。把两者区分开，才能理解为什么一次成交价变化并不等于信息被完整揭示。",en:"Hasbrouck studies the eventual quote adjustment following a trade rather than only its immediate price movement. Short-run responses can include inventory management and trading frictions. Separating these from the persistent component explains why a single transaction-price change does not measure the complete revelation of information."},reference:{url:"https://www.acsu.buffalo.edu/~keechung/MGF743/Readings/K2.pdf",label:{zh:"原文定位：1991年期刊版，第179–181页",en:"Source: 1991 journal article, pp. 179–181"}}},{title:{zh:"关键是未被预期的交易部分",en:"Focus on the unexpected component of trading"},body:{zh:"交易本身可能延续此前的成交与报价信息。论文关注在给定过去信息后仍无法预期的交易创新，并分析它随后引起的报价响应。直接把全部买入成交量与价格变化相连，会混合可预测订单流和新增信息，回答的已不是同一个问题。",en:"Trades can be predictable from earlier trades and quote changes. The paper focuses on the trading innovation left after conditioning on past information and traces the subsequent quote response. Relating all buyer-initiated volume directly to price changes mixes predictable order flow with new information and answers a different question."},reference:{url:"https://www.acsu.buffalo.edu/~keechung/MGF743/Readings/K2.pdf",label:{zh:"原文定位：1991年期刊版，第180–183页",en:"Source: 1991 journal article, pp. 180–183"}}},{title:{zh:"滞后关系组成一个动态系统",en:"Lags form a dynamic system"},body:{zh:"向量自回归把交易与报价修订放进同一滞后系统，允许信息在多个事件后逐步体现。由此得到的长期响应依赖变量选择、滞后长度和交易过程假设。它不是把一条回归的当期系数简单命名为永久冲击，模型设定也需要随结果保留。",en:"A vector autoregression places trades and quote revisions in a joint lagged system, allowing adjustment over several events. Its long-run response depends on variables, lag structure and assumptions about trading. It is not merely a contemporaneous regression coefficient renamed as permanent impact; the specification must accompany the result."},reference:{url:"https://www.acsu.buffalo.edu/~keechung/MGF743/Readings/K2.pdf",label:{zh:"原文定位：1991年期刊版，第181–183页",en:"Source: 1991 journal article, pp. 181–183"}}},{title:{zh:"报价中点与成交价各有角色",en:"Quotes and transaction prices play different roles"},body:{zh:"论文以报价中点描述价格修订，并给成交赋予买方或卖方发起的方向。中点处的成交方向可能无法明确识别。只保存成交价和成交量会失去当时报价背景；方向判定规则也应单独记录，不能把推断方向当成交易所直接提供的事实。",en:"Quote midpoints describe price revisions, while trades receive buyer- or seller-initiated signs. Trades at the midpoint can be indeterminate. Keeping only transaction prices and volume loses the quote context; retain the signing rule separately rather than treating an inferred direction as an exchange-observed fact."},reference:{url:"https://www.acsu.buffalo.edu/~keechung/MGF743/Readings/K2.pdf",label:{zh:"原文定位：1991年期刊版，第181–182, 191–192页",en:"Source: 1991 journal article, pp. 181–182, 191–192"}}},{title:{zh:"事件时间不等于钟表时间",en:"Transaction time is not clock time"},body:{zh:"样本使用1989年第一季度的交易和报价记录，并按规模组选取公司。模型的事件索引会在交易或报价出现时推进；报价与成交还经过时间匹配处理。因此一个滞后不是固定的一分钟，不能用规则时间柱机械替代原研究的事件序列。",en:"The sample uses first-quarter 1989 trades and quotes from companies selected across size groups. The transaction time index advances with trade or quote events, with additional quote–trade timing alignment. A lag is therefore not a fixed minute; regular time bars cannot mechanically substitute for the original event sequence."},reference:{url:"https://www.acsu.buffalo.edu/~keechung/MGF743/Readings/K2.pdf",label:{zh:"原文定位：1991年期刊版，第190–192页",en:"Source: 1991 journal article, pp. 190–192"}}},{title:{zh:"持久响应不自动证明私人信息",en:"Persistence alone does not prove private information"},body:{zh:"公开新闻、报价调整方式和交易摩擦都可能影响所估计的响应。论文讨论的识别依赖其结构和信息假设；数据匹配误差也可能改变交易与报价的先后关系。评价结果时需要同时阅读模型限制和清洗方法，而不是把每次持久变动归因于知情交易者。",en:"Public news, quote adjustment and trading frictions can influence the estimated response. Identification depends on the model's structural and information assumptions, while matching errors can alter the order of trades and quotes. Read these limits alongside preprocessing rather than assigning every persistent movement to an informed trader."},reference:{url:"https://www.acsu.buffalo.edu/~keechung/MGF743/Readings/K2.pdf",label:{zh:"原文定位：1991年期刊版，第180–183, 191–192页",en:"Source: 1991 journal article, pp. 180–183, 191–192"}}}],readerLimits:{zh:"交易的信息含量依赖报价、成交方向、事件排序与模型设定。历史样本中的长期报价响应不能直接解释为每笔交易的私人信息，更不能只靠分钟行情复现。",en:"Information content depends on quotes, trade signs, event ordering and model specification. A persistent quote response in this historical design does not identify private information in every trade, and minute bars alone cannot reproduce it."}},{id:"one-security-many-markets-determining-the-contributions-to-price-discovery",title:"One Security, Many Markets: Determining the Contributions to Price Discovery",titleZh:"一种证券、多个市场：价格发现贡献",sourceTitle:"One Security, Many Markets: Determining the Contributions to Price Discovery",authors:"JOEL HASBROUCK",venue:"The Journal of Finance",year:"1995",kind:"paper",topic:"market-microstructure",data:"synchronized venue quotes; common securities; timestamps",dataZh:"同步场所报价；相同证券；时间戳",summary:{en:"Measures contributions to a common price from trading in multiple venues.",zh:"衡量多个交易场所对共同价格形成的贡献。"},related:{datasets:["cn-equity-minute"],features:["liquidity-measures"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/j.1540-6261.1995.tb04054.x"}]},{id:"illiquidity-and-stock-returns-cross-section-and-time-series-effects",title:"Illiquidity and Stock Returns: Cross-Section and Time-Series Effects",titleZh:"非流动性与股票收益",sourceTitle:"Illiquidity and stock returns: cross-section and time-series effects",authors:"Yakov Amihud",venue:"Journal of Financial Markets",year:"2002",kind:"paper",topic:"market-microstructure",data:"daily returns; trading value; security histories",dataZh:"日收益；成交金额；证券历史",summary:{en:"Uses return-to-volume measures to examine liquidity across securities and time.",zh:"使用收益与成交金额的比值比较证券间和时间上的流动性。"},related:{datasets:["cn-equity-minute"],features:["liquidity-measures"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/s1386-4181(01)00024-6"}],readingNotes:[{title:{zh:"流动性为什么需要代理量？",en:"Why use a liquidity proxy?"},body:{zh:"Amihud关注流动性与股票收益之间的关系，但日频历史数据通常没有完整报价和订单流。论文因此构造容易从日收益与成交金额得到的粗略代理量。它牺牲了微观结构细节，换取较长的历史覆盖；这不是把成交金额本身当作流动性，也不是直接测量买卖价差。",en:"Amihud studies the relation between liquidity and stock returns when long histories of quotes and order flow are unavailable. A coarse proxy built from daily returns and traded value trades microstructure detail for historical coverage. It is neither trading value by itself nor a directly observed bid–ask spread."},reference:{url:"https://www.cis.upenn.edu/~mkearns/finread/amihud.pdf",label:{zh:"原文定位：2002年期刊版，第31–34页",en:"Source: 2002 journal article, pp. 31–34"}}},{title:{zh:"先算每日比值，再取平均",en:"Average the daily ratios"},body:{zh:"ILLIQ先用每日收益的绝对值除以当日成交金额，再在观察期内对这些比值取平均。分母是金额，不是股数；“每日比值的平均”也不同于把全年绝对收益之和除以全年成交金额之和。单位、日频边界与有效观测天数都应随结果保留，否则不同序列的数值无法直接比较。",en:"ILLIQ is the mean of daily ratios: absolute return divided by that day's dollar trading volume. The denominator is traded value, not shares. This differs from dividing summed absolute returns by summed volume. Retain currency, return units, daily boundaries and the number of valid observations when comparing series."},reference:{url:"https://www.cis.upenn.edu/~mkearns/finread/amihud.pdf",label:{zh:"原文定位：2002年期刊版，第34页",en:"Source: 2002 journal article, pp. 34"}}},{title:{zh:"样本规则也是方法的一部分",en:"The sample is part of the method"},body:{zh:"横截面检验限制在纽约证券交易所股票，并使用上一年的特征解释之后的月收益。样本要求上一年有超过200天的收益及成交量数据、年末仍挂牌且价格高于5美元，还需要市值资料并剔除ILLIQ两端各1%的极端值。这些是原研究的历史设定，不是所有市场都应沿用的清洗规则。",en:"The cross-sectional tests use NYSE stocks and prior-year characteristics for subsequent monthly returns. Admission requires more than 200 prior-year return/volume observations, year-end listing, a price above $5 and capitalization data; the outer 1% tails of ILLIQ are excluded. These historical design choices are not universal cleaning defaults."},reference:{url:"https://www.cis.upenn.edu/~mkearns/finread/amihud.pdf",label:{zh:"原文定位：2002年期刊版，第36–37页",en:"Source: 2002 journal article, pp. 36–37"}}},{title:{zh:"不要把原始指标与回归变量混用",en:"Raw and normalized measures differ"},body:{zh:"论文不仅计算单只股票的ILLIQ，也计算年度市场平均值，再用个股指标除以该平均值形成均值调整后的变量。展示时还使用数值缩放。因此，看到名为“Amihud非流动性”的字段时，要先问它是原始日比值、期间平均、缩放值还是市场标准化值，不能只按名称连接数据。",en:"The paper also averages stock-level ILLIQ across the yearly sample and divides individual measures by that market average. Numerical scaling is used in presentation. A field called Amihud illiquidity could therefore contain daily ratios, period means, scaled values or market-normalized values; the name alone does not establish comparability."},reference:{url:"https://www.cis.upenn.edu/~mkearns/finread/amihud.pdf",label:{zh:"原文定位：2002年期刊版，第36–37页",en:"Source: 2002 journal article, pp. 36–37"}}},{title:{zh:"预期补偿与当期冲击并不矛盾",en:"Expected compensation and contemporaneous shocks"},body:{zh:"论文区分预期非流动性与未预期的当期变化：前者与预期超额收益正相关，后者与当期股票收益负相关。这分别对应持有不易交易资产的补偿，以及流动性意外恶化时的价格调整。阅读中应保留变量的时间位置，不能把历史上的正向关系简化为“流动性变差就会涨”。",en:"The opening argument separates expected illiquidity, positively related to expected excess returns, from unexpected contemporaneous illiquidity, negatively related to current returns. Compensation for holding less liquid assets and repricing after a liquidity shock address different time positions. Neither implies that worsening liquidity must produce a price rise."},reference:{url:"https://www.cis.upenn.edu/~mkearns/finread/amihud.pdf",label:{zh:"原文定位：2002年期刊版，第31–32页",en:"Source: 2002 journal article, pp. 31–32"}}},{title:{zh:"把口径检查放在计算之前",en:"Check conventions before calculation"},body:{zh:"用于新数据时，应先核对收益定义、币种、成交金额单位和市场日历。零成交金额使比值无定义，缺失也不能当作零流动性；应单独标记并披露处理规则。保留退市证券与样本剔除原因，再比较不同市场。上述准备原则帮助说明输入边界，并不等于已经复现论文的回归。",en:"For a new dataset, verify return definitions, currency, traded-value units and sessions first. A zero denominator prevents calculation; missing observations are not zero illiquidity. Mark these cases explicitly, retain delisted securities and record exclusions. These preparation principles clarify inputs without claiming to reproduce the paper's regressions."},reference:{url:"https://www.cis.upenn.edu/~mkearns/finread/amihud.pdf",label:{zh:"原文定位：2002年期刊版，第34–37页",en:"Source: 2002 journal article, pp. 34–37"}}}],readerLimits:{zh:"日收益／成交金额只是粗略代理量，不能替代报价、订单方向或实际执行成本。历史纽约证券交易所样本的关系不保证跨市场成立；这里没有复现回归或检验当前收益。",en:"Daily return-to-value ratios are coarse proxies, not quotes, signed order flow or execution costs. Historical NYSE relationships need not transfer across markets; no regression replication or current-return test is claimed here."}},{id:"asset-pricing-and-the-bid-ask-spread",title:"Asset Pricing and the Bid-Ask Spread",titleZh:"资产定价与买卖价差",sourceTitle:"Asset pricing and the bid-ask spread",authors:"Yakov Amihud · Haim Mendelson",venue:"Journal of Financial Economics",year:"1986",kind:"paper",topic:"market-microstructure",data:"quoted spreads; returns; holding-period assumptions",dataZh:"报价价差；收益；持有期假设",summary:{en:"Connects transaction costs and expected holding periods to asset pricing.",zh:"将交易成本与预期持有期联系到资产定价。"},related:{datasets:["cn-equity-minute"],features:["liquidity-measures"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/0304-405x(86)90065-6"}]},{id:"liquidity-risk-and-expected-stock-returns",title:"Liquidity Risk and Expected Stock Returns",titleZh:"流动性风险与预期股票收益",sourceTitle:"Liquidity Risk and Expected Stock Returns",authors:"Ľuboš Pástor · Robert F. Stambaugh",venue:"Journal of Political Economy",year:"2003",kind:"paper",topic:"market-microstructure",data:"daily prices; volumes; aggregate liquidity innovations",dataZh:"日价格；成交量；总体流动性创新",summary:{en:"Distinguishes marketwide liquidity shocks from an individual stock's liquidity level.",zh:"区分全市场流动性冲击与单只股票的流动性水平。"},related:{datasets:["cn-equity-minute"],features:["liquidity-measures"]},sources:[{label:"DOI",url:"https://doi.org/10.1086/374184"}]},{id:"trading-volume-and-serial-correlation-in-stock-returns",title:"Trading Volume and Serial Correlation in Stock Returns",titleZh:"成交量与股票收益的序列相关",sourceTitle:"Trading Volume and Serial Correlation in Stock Returns",authors:"J. Y. Campbell · S. J. Grossman · J. Wang",venue:"The Quarterly Journal of Economics",year:"1993",kind:"paper",topic:"market-microstructure",data:"daily returns; turnover; lagged volumes",dataZh:"日收益；换手率；滞后成交量",summary:{en:"Studies how trading volume helps interpret serial dependence in returns.",zh:"考察成交量如何帮助解释收益的序列相关。"},related:{datasets:["cn-equity-minute"],features:["liquidity-measures"]},sources:[{label:"DOI",url:"https://doi.org/10.2307/2118454"}]},{id:"limit-order-book-as-a-market-for-liquidity",title:"Limit Order Book as a Market for Liquidity",titleZh:"限价订单簿作为流动性市场",sourceTitle:"Limit Order Book as a Market for Liquidity",authors:"Thierry Foucault · Ohad Kadan · Eugene Kandel",venue:"Review of Financial Studies",year:"2005",kind:"paper",topic:"market-microstructure",data:"order submissions; cancellations; queue positions",dataZh:"订单提交；撤单；队列位置",summary:{en:"Models the choices of liquidity demanders and suppliers in a limit-order market.",zh:"建模分析限价订单市场中的流动性需求和供给决策。"},related:{datasets:["cn-equity-minute"],features:["liquidity-measures"]},sources:[{label:"DOI",url:"https://doi.org/10.1093/rfs/hhi029"}]},{id:"the-price-impact-of-order-book-events",title:"The Price Impact of Order Book Events",titleZh:"订单簿事件的价格冲击",sourceTitle:"The Price Impact of Order Book Events",authors:"R. Cont · A. Kukanov · S. Stoikov",venue:"Journal of Financial Econometrics",year:"2014",kind:"paper",topic:"market-microstructure",data:"order-book updates; trades; depth; event timestamps",dataZh:"订单簿更新；成交；深度；事件时间戳",summary:{en:"Relates short-horizon price changes to imbalance in order-book events.",zh:"将短期价格变化与订单簿事件的不平衡联系起来。"},related:{datasets:["cn-equity-minute"],features:["liquidity-measures"]},sources:[{label:"DOI",url:"https://doi.org/10.1093/jjfinec/nbt003"}],readingNotes:[{title:{zh:"订单簿事件不只是成交",en:"Order book events extend beyond trades"},body:{zh:"论文从最优买卖报价及其挂单数量出发，把市价成交、限价单新增和撤单共同纳入供需变化。成交量只记录已经撮合的部分，无法描述尚未成交的流动性变化。因此只有价格柱和成交量时，不能直接声称重建了论文的订单流不平衡。",en:"The paper starts from best bid and ask prices and displayed sizes, combining market trades, limit-order additions and cancellations. Traded volume records only matched activity, not all changes in available liquidity. Price bars and volume alone therefore cannot establish that the paper's order flow imbalance has been reconstructed."},reference:{url:"https://arxiv.org/pdf/1011.6402v3",label:{zh:"原文定位：2011年3月作者稿v3，第1–4页",en:"Source: March 2011 author draft v3, pp. 1–4"}}},{title:{zh:"OFI是按事件累计的净变化",en:"OFI aggregates signed event contributions"},body:{zh:"订单流不平衡按最优报价及队列变化，为每个事件赋予带方向的贡献，再在时间窗内累计。买方队列增加与卖方队列增加的方向不同，最优价格改变时也要按定义处理。它不是简单用买入成交量减去卖出成交量，更不是整本订单簿的静态买卖数量差。",en:"Order flow imbalance aggregates signed contributions from changes in best prices and queues over an interval. Added bid and ask size contribute in opposite directions, and best-price changes need their own treatment. OFI is neither simply buyer volume minus seller volume nor a static difference across the entire order book."},reference:{url:"https://arxiv.org/pdf/1011.6402v3",label:{zh:"原文定位：2011年3月作者稿v3，第4–5页",en:"Source: March 2011 author draft v3, pp. 4–5"}}},{title:{zh:"相同不平衡在不同深度下含义不同",en:"Depth changes the response to imbalance"},body:{zh:"作者把时间窗内以最小价格变动单位计量的中点变化，与同窗OFI联系起来，并讨论斜率随市场深度下降而增大的关系。价格单位、挂单数量单位和深度定义必须同时明确；这个简化关系并不保证任意市场、任意规模的订单都有相同线性影响。",en:"The model relates midpoint changes measured in ticks to OFI over the same interval and links a larger slope to lower market depth. Price units, size units and the depth definition must travel together. This simplified relation does not guarantee linear impact for every order size or market."},reference:{url:"https://arxiv.org/pdf/1011.6402v3",label:{zh:"原文定位：2011年3月作者稿v3，第5–8页",en:"Source: March 2011 author draft v3, pp. 5–8"}}},{title:{zh:"时间窗是研究设定的一部分",en:"The observation window is part of the design"},body:{zh:"作者稿使用2010年4月随机选取的50只标普500股票，基准观察网格为10秒，并在半小时区间估计关系。论文还考察其他时间尺度。更换股票范围、市场时段或聚合窗口会改变样本与参数，不能把原文的短窗结论直接移到日频数据。",en:"The draft studies 50 randomly selected S&P 500 stocks in April 2010, using a ten-second baseline grid and estimating relations within half-hour periods. Other timescales are also examined. Changing the universe, session or aggregation window changes the sample and parameters; short-window findings cannot simply be transferred to daily data."},reference:{url:"https://arxiv.org/pdf/1011.6402v3",label:{zh:"原文定位：2011年3月作者稿v3，第8–11页",en:"Source: March 2011 author draft v3, pp. 8–11"}}},{title:{zh:"同期解释不是下一刻的预测",en:"Contemporaneous fit is not a forecast"},body:{zh:"核心比较使用同一窗口里的价格变化和订单流不平衡，是同期解释关系，而不是提前知道下一窗口的价格。部分事件还同时改变最优报价，存在机械联系需要检查。若研究预测能力，必须另设信息截止点与未来目标，不能把同期拟合优度当成预测成绩。",en:"The core comparison is contemporaneous: price changes and OFI come from the same interval, not a forecast of the next interval. Some events also change best prices, requiring checks for mechanical association. Predictive evaluation needs a separate information cutoff and future target rather than reusing contemporaneous fit as a forecasting score."},reference:{url:"https://arxiv.org/pdf/1011.6402v3",label:{zh:"原文定位：2011年3月作者稿v3，第8–11页",en:"Source: March 2011 author draft v3, pp. 8–11"}}},{title:{zh:"保留报价事件与清洗依据",en:"Retain event records and filtering choices"},body:{zh:"附录说明了报价、成交记录的筛选、交易时段和最优报价整理。准备新数据时，应保留事件时间、买卖价格与数量、记录类型和过滤原因，并核对是否具备合并最优报价所需信息。只有这些边界清楚，才能判断指标缺口来自市场行为还是数据覆盖。",en:"The appendix describes quote and trade filtering, sessions and construction of best quotes. For new data, retain event times, bid and ask prices and sizes, record types and exclusion reasons, checking whether consolidated best-quote information is available. These boundaries distinguish economic variation from gaps in data coverage."},reference:{url:"https://arxiv.org/pdf/1011.6402v3",label:{zh:"原文定位：2011年3月作者稿v3，第4, 26页",en:"Source: March 2011 author draft v3, pp. 4, 26"}}}],readerLimits:{zh:"导读采用2011年作者稿v3，题录保留2014年期刊版。最优报价处的同期关系不是未来价格预测，也不代表完整订单簿或真实执行成本；分钟成交量不足以替代所需输入。",en:"This guide uses the 2011 author draft v3 while retaining the 2014 journal citation. Best-quote contemporaneous relationships are not forecasts, a complete order book or execution costs; minute-level traded volume cannot replace the required inputs."}},{id:"hawkes-processes-in-finance",title:"Hawkes Processes in Finance",titleZh:"金融中的霍克斯过程",sourceTitle:"Hawkes Processes in Finance",authors:"Emmanuel Bacry · Iacopo Mastromatteo · Jean-François Muzy",venue:"Market Microstructure and Liquidity",year:"2015",kind:"paper",topic:"market-microstructure",data:"event timestamps; event types; intensity estimates",dataZh:"事件时间戳；事件类型；强度估计",summary:{en:"Surveys self-exciting point processes for modeling clustered financial events.",zh:"综述用于建模金融事件聚集现象的自激点过程。"},related:{datasets:["cn-equity-minute"],features:["liquidity-measures"]},sources:[{label:"DOI",url:"https://doi.org/10.1142/s2382626615500057"}]},{id:"the-long-memory-of-the-efficient-market",title:"The Long Memory of the Efficient Market",titleZh:"有效市场的长记忆",sourceTitle:"The Long Memory of the Efficient Market",authors:"Fabrizio Lillo · J. Doyne Farmer",venue:"Studies in Nonlinear Dynamics & Econometrics",year:"2004",kind:"paper",topic:"market-microstructure",data:"signed order flow; transaction prices; long samples",dataZh:"带方向订单流；成交价格；长期样本",summary:{en:"Studies persistent order-flow patterns and their relationship to price efficiency.",zh:"研究持续的订单流模式及其与价格效率的关系。"},related:{datasets:["cn-equity-minute"],features:["liquidity-measures"]},sources:[{label:"DOI",url:"https://doi.org/10.2202/1558-3708.1226"}]},{id:"an-analysis-of-changes-in-specialist-inventories-and-quotations",title:"An Analysis of Changes in Specialist Inventories and Quotations",titleZh:"专家交易商库存与报价变化分析",sourceTitle:"An Analysis of Changes in Specialist Inventories and Quotations",authors:"ANANTH MADHAVAN · SEYMOUR SMIDT",venue:"The Journal of Finance",year:"1993",kind:"paper",topic:"market-microstructure",data:"dealer quotes; trades; inventory proxies; timestamps",dataZh:"交易商报价；成交；库存代理；时间戳",summary:{en:"Decomposes price formation into information and inventory-related components.",zh:"将价格形成分解为信息与库存相关成分。"},related:{datasets:["cn-equity-minute"],features:["liquidity-measures"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/j.1540-6261.1993.tb05122.x"}]},{id:"why-do-security-prices-change-a-transaction-level-analysis-of-nyse-stocks",title:"Why Do Security Prices Change? A Transaction-Level Analysis of NYSE Stocks",titleZh:"证券价格为何变化？逐笔交易分析",sourceTitle:"Why Do Security Prices Change? A Transaction-Level Analysis of NYSE Stocks",authors:"Ananth Madhavan · Matthew Richardson · Mark Roomans",venue:"Review of Financial Studies",year:"1997",kind:"paper",topic:"market-microstructure",data:"trade signs; transaction prices; quotes; intraday periods",dataZh:"交易方向；成交价格；报价；日内时段",summary:{en:"Examines information and trading frictions using transaction-level price dynamics.",zh:"借助逐笔价格动态研究信息与交易摩擦。"},related:{datasets:["cn-equity-minute"],features:["liquidity-measures"]},sources:[{label:"DOI",url:"https://doi.org/10.1093/rfs/10.4.1035"}]},{id:"high-frequency-trading-and-price-discovery",title:"High-Frequency Trading and Price Discovery",titleZh:"高频交易与价格发现",sourceTitle:"High-Frequency Trading and Price Discovery",authors:"Jonathan Brogaard · Terrence Hendershott · Ryan Riordan",venue:"Review of Financial Studies",year:"2014",kind:"paper",topic:"market-microstructure",data:"participant-classified trades; quotes; market timestamps",dataZh:"按参与者分类成交；报价；市场时间戳",summary:{en:"Studies the role of identified high-frequency traders in price formation.",zh:"研究可识别高频交易者在价格形成中的作用。"},related:{datasets:["cn-equity-minute"],features:["liquidity-measures"]},sources:[{label:"DOI",url:"https://doi.org/10.1093/rfs/hhu032"}]},{id:"does-algorithmic-trading-improve-liquidity",title:"Does Algorithmic Trading Improve Liquidity?",titleZh:"算法交易是否改善流动性？",sourceTitle:"Does Algorithmic Trading Improve Liquidity?",authors:"TERRENCE HENDERSHOTT · CHARLES M. JONES · ALBERT J. MENKVELD",venue:"The Journal of Finance",year:"2011",kind:"paper",topic:"market-microstructure",data:"message traffic; quotes; trades; infrastructure event dates",dataZh:"报文流量；报价；成交；基础设施事件日期",summary:{en:"Uses changes in market infrastructure to study algorithmic activity and liquidity.",zh:"利用市场基础设施变化研究算法交易活动与流动性。"},related:{datasets:["cn-equity-minute"],features:["liquidity-measures"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/j.1540-6261.2010.01624.x"}]},{id:"the-high-frequency-trading-arms-race-frequent-batch-auctions-as-a-market-design-response",title:"The High-Frequency Trading Arms Race: Frequent Batch Auctions as a Market Design Response",titleZh:"高频交易竞赛与频繁批量竞价",sourceTitle:"The High-Frequency Trading Arms Race: Frequent Batch Auctions as a Market Design Response *",authors:"Eric Budish · Peter Cramton · John Shim",venue:"The Quarterly Journal of Economics",year:"2015",kind:"paper",topic:"market-microstructure",data:"high-resolution quotes; cross-market synchronization; latency",dataZh:"高精度报价；跨市场同步；延迟",summary:{en:"Examines continuous-time market design and the incentives for speed competition.",zh:"研究连续时间市场设计如何形成速度竞争的激励。"},related:{datasets:["cn-equity-minute"],features:["liquidity-measures"]},sources:[{label:"DOI",url:"https://doi.org/10.1093/qje/qjv027"}]},{id:"the-flash-crash-high-frequency-trading-in-an-electronic-market",title:"The Flash Crash: High-Frequency Trading in an Electronic Market",titleZh:"闪电崩盘：电子市场中的高频交易",sourceTitle:"The Flash Crash: High‐Frequency Trading in an Electronic Market",authors:"ANDREI KIRILENKO · ALBERT S. KYLE · MEHRDAD SAMADI · TUGKAN TUZUN",venue:"The Journal of Finance",year:"2017",kind:"paper",topic:"market-microstructure",data:"audit-trail trades; participant IDs; futures positions",dataZh:"审计级成交；参与者标识；期货持仓",summary:{en:"Analyzes participant-level trading around the May 2010 market disruption.",zh:"分析2010年5月市场异常前后的参与者级交易。"},related:{datasets:["cn-equity-minute"],features:["liquidity-measures"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/jofi.12498"}]},{id:"high-frequency-trading-and-the-new-market-makers",title:"High Frequency Trading and the New Market Makers",titleZh:"高频交易与新型做市商",sourceTitle:"High frequency trading and the new market makers",authors:"Albert J. Menkveld",venue:"Journal of Financial Markets",year:"2013",kind:"paper",topic:"market-microstructure",data:"identified dealer trades; venue quotes; inventory",dataZh:"可识别交易商成交；场所报价；库存",summary:{en:"Studies a large high-frequency market maker operating across venues.",zh:"研究跨交易场所活动的大型高频做市商。"},related:{datasets:["cn-equity-minute"],features:["liquidity-measures"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/j.finmar.2013.06.006"}]},{id:"market-microstructure-a-survey",title:"Market Microstructure: A Survey",titleZh:"市场微观结构综述",sourceTitle:"Market microstructure: A survey",authors:"Ananth Madhavan",venue:"Journal of Financial Markets",year:"2000",kind:"paper",topic:"market-microstructure",data:"trade and quote data; trading rules; market design",dataZh:"成交与报价数据；交易规则；市场设计",summary:{en:"Organizes theories and evidence on how trading mechanisms affect observed prices.",zh:"梳理交易机制如何影响观测价格的理论与证据。"},related:{datasets:["cn-equity-minute"],features:["liquidity-measures"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/s1386-4181(00)00007-0"}]},{id:"commonality-in-liquidity",title:"Commonality in Liquidity",titleZh:"流动性的共同变化",sourceTitle:"Commonality in liquidity",authors:"Tarun Chordia · Richard Roll · Avanidhar Subrahmanyam",venue:"Journal of Financial Economics",year:"2000",kind:"paper",topic:"market-microstructure",data:"quoted spreads; depth; volume; market aggregates",dataZh:"报价价差；深度；成交量；市场汇总",summary:{en:"Studies whether liquidity measures co-move across individual securities.",zh:"考察不同证券的流动性度量是否共同变化。"},related:{datasets:["cn-equity-minute"],features:["liquidity-measures"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/s0304-405x(99)00057-4"}]},{id:"market-liquidity-and-trading-activity",title:"Market Liquidity and Trading Activity",titleZh:"市场流动性与交易活动",sourceTitle:"Market Liquidity and Trading Activity",authors:"Tarun Chordia · Richard Roll · Avanidhar Subrahmanyam",venue:"The Journal of Finance",year:"2001",kind:"paper",topic:"market-microstructure",data:"market spreads; depth; turnover; calendar variables",dataZh:"市场价差；深度；换手率；日历变量",summary:{en:"Examines marketwide liquidity alongside trading activity and economic conditions.",zh:"结合交易活动和经济条件分析市场总体流动性。"},related:{datasets:["cn-equity-minute"],features:["liquidity-measures"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/0022-1082.00335"}]},{id:"order-imbalance-and-individual-stock-returns-theory-and-evidence",title:"Order Imbalance and Individual Stock Returns: Theory and Evidence",titleZh:"订单不平衡与个股收益",sourceTitle:"Order imbalance and individual stock returns: Theory and evidence",authors:"Tarun Chordia · Avanidhar Subrahmanyam",venue:"Journal of Financial Economics",year:"2004",kind:"paper",topic:"market-microstructure",data:"buyer/seller initiated trades; quotes; daily aggregation",dataZh:"买卖发起成交；报价；日频汇总",summary:{en:"Relates order imbalance to short-horizon price changes and reversals.",zh:"将订单不平衡与短期价格变化及反转联系起来。"},related:{datasets:["cn-equity-minute"],features:["liquidity-measures"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/s0304-405x(03)00175-2"}]},{id:"a-new-estimate-of-transaction-costs",title:"A New Estimate of Transaction Costs",titleZh:"交易成本的新估计方法",sourceTitle:"A New Estimate of Transaction Costs",authors:"David A. Lesmond · Joseph P. Ogden · Charles A. Trzcinka",venue:"Review of Financial Studies",year:"1999",kind:"paper",topic:"market-microstructure",data:"daily returns; market returns; nontrading indicators",dataZh:"日收益；市场收益；无交易标识",summary:{en:"Infers trading costs from the occurrence of zero returns under a threshold model.",zh:"在阈值模型下从零收益的出现频率推断交易成本。"},related:{datasets:["cn-equity-minute"],features:["liquidity-measures"]},sources:[{label:"DOI",url:"https://doi.org/10.1093/rfs/12.5.1113"}]},{id:"a-simple-way-to-estimate-bid-ask-spreads-from-daily-high-and-low-prices",title:"A Simple Way to Estimate Bid-Ask Spreads from Daily High and Low Prices",titleZh:"利用日高低价估计买卖价差",sourceTitle:"A Simple Way to Estimate Bid‐Ask Spreads from Daily High and Low Prices",authors:"SHANE A. CORWIN · PAUL SCHULTZ",venue:"The Journal of Finance",year:"2012",kind:"paper",topic:"market-microstructure",data:"daily high/low prices; overnight adjustments; trading days",dataZh:"日最高最低价；隔夜调整；交易日",summary:{en:"Develops a high-low price estimator and distinguishes volatility from spread components.",zh:"利用最高最低价构造估计量，并区分波动与价差成分。"},related:{datasets:["cn-equity-minute"],features:["liquidity-measures"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/j.1540-6261.2012.01729.x"}],readingNotes:[{title:{zh:"只有日行情，还能研究价差吗？",en:"What can daily prices reveal?"},body:{zh:"Corwin与Schultz研究在缺少逐笔报价时，能否用每日最高价与最低价估计买卖价差。这是用容易取得的数据构造代理量，而不是从日行情恢复真实订单簿。",en:"Corwin and Schultz ask whether daily highs and lows can estimate spreads when detailed quotes are unavailable. The aim is a low-frequency proxy, not reconstruction of an order book."}},{title:{zh:"实际输入不止最高与最低价",en:"Practical inputs extend beyond highs and lows"},body:{zh:"作者示例程序要求证券身份、日期、月份及拆股调整后的最高、最低和收盘价，成交量可用于识别无交易日。程序先处理无效区间，再调整隔夜收益，最后计算价差。因此，把未经检查的日高低价直接代入一个公式，并不等于使用了完整方法。",en:"The authors' sample program requires security identity, date, month and split-adjusted high, low and closing prices; volume can identify nontrading days. Invalid ranges and overnight returns are handled before estimation. Feeding unchecked daily extremes into a formula therefore does not reproduce the documented procedure."},reference:{url:"https://sites.nd.edu/scorwin/files/2019/08/Sample-SAS-Program-Description.pdf",label:{zh:"作者程序说明：输入与步骤1–2",en:"Author program description: inputs and steps 1–2"}}},{title:{zh:"价格区间包含两种变化",en:"A range mixes two components"},body:{zh:"作者的思路是：最高与最低成交价之间的差异，既包含价格波动，也包含买卖价差。两种成分随观测区间扩展的方式不同，因而可以结合一天与两天的高低价比进行识别。",en:"High-low ranges combine price variation and spread effects. Their different behavior as the observation interval expands motivates combining one-day and two-day high-low ratios."}},{title:{zh:"估计价差与观测价差不同",en:"Estimated is not observed"},body:{zh:"论文比较低频价差估计与高频有效价差，作者配套材料还区分逐月横截面和逐股时间序列的比较。两类比较回答的问题不同；即使总体误差较小，单日、单股的估计仍不等于可成交成本，数量、冲击和费用也需另行考虑。",en:"The paper compares low-frequency estimates with high-frequency effective spreads. Its companion material separates monthly cross-sectional and stock-level time-series comparisons. Those answer different questions: aggregate accuracy does not make a daily estimate executable, and size, impact and fees remain separate."}},{title:{zh:"零值可能来自规则，而非无成本交易",en:"A zero can reflect a rule, not costless trading"},body:{zh:"配套程序把负的日价差估计设为零，并要求一个月至少有12个观测；附录还说明了部分缺失高低价的替代处理。编辑建议：保留原始值与每次调整标记，区分缺失、替代和截断后的零。这个专用估计规则不能推广成所有行情缺口的自动填补规则。",en:"The companion program floors negative daily estimates at zero and requires at least 12 observations per month; the appendix also describes replacement of some missing extremes. Editorial application: retain raw values and adjustment flags. Missing, substituted and floored-zero values differ, and this estimator-specific convention is not a general gap-filling rule."},reference:{url:"https://sites.nd.edu/scorwin/files/2019/11/Internet-Appendix_FINAL.pdf",label:{zh:"作者附录表IA.I说明与程序步骤3–4",en:"Author appendix Table IA.I notes; program steps 3–4"}}},{title:{zh:"与波动率论文一起读",en:"Read with volatility measurement"},body:{zh:"已实现波动率研究讨论高频收益如何聚合；这里则尝试从低频区间分离波动与价差。准备数据时先核对高低价口径、交易时段和停牌情况；具体计算还需结合原文公式、适用条件与异常处理。",en:"Realized volatility aggregates high-frequency returns; this paper separates components of low-frequency ranges. Check price conventions, sessions and suspensions. Consult the full specification and exception handling before implementing the estimator."}}],readerLimits:{zh:"高低价法是依赖清洗约定的价差代理。本导读结合作者配套说明，不复现主文推导；它不能替代真实报价、订单簿或成交成本。",en:"The proxy depends on cleaning conventions. This guide uses the authors' companion instructions, not a replication of the derivation; it does not replace quotes, an order book or execution costs."}},{id:"autoregressive-conditional-heteroscedasticity-with-estimates-of-the-variance-of-united-kingdom-inflation",title:"Autoregressive Conditional Heteroscedasticity with Estimates of the Variance of United Kingdom Inflation",titleZh:"自回归条件异方差模型",sourceTitle:"Autoregressive Conditional Heteroscedasticity with Estimates of the Variance of United Kingdom Inflation",authors:"Robert F. Engle",venue:"Econometrica",year:"1982",kind:"paper",topic:"research-methods",data:"time series; residuals; lagged squared innovations",dataZh:"时间序列；残差；滞后平方创新",summary:{en:"Introduces conditional variance modeling for time series with changing uncertainty.",zh:"为不确定性随时间变化的序列引入条件方差模型。"},related:{recipes:["pit-fundamentals-panel","adjusted-price-series"]},sources:[{label:"DOI",url:"https://doi.org/10.2307/1912773"}]},{id:"generalized-autoregressive-conditional-heteroskedasticity",title:"Generalized Autoregressive Conditional Heteroskedasticity",titleZh:"广义自回归条件异方差模型",sourceTitle:"Generalized autoregressive conditional heteroskedasticity",authors:"Tim Bollerslev",venue:"Journal of Econometrics",year:"1986",kind:"paper",topic:"research-methods",data:"returns; model residuals; lag specification",dataZh:"收益；模型残差；滞后设定",summary:{en:"Extends conditional variance dynamics with lagged variances and shocks.",zh:"以滞后方差与冲击扩展条件方差动态。"},related:{recipes:["pit-fundamentals-panel","adjusted-price-series"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/0304-4076(86)90063-1"}]},{id:"a-heteroskedasticity-consistent-covariance-matrix-estimator-and-a-direct-test-for-heteroskedasticity",title:"A Heteroskedasticity-Consistent Covariance Matrix Estimator and a Direct Test for Heteroskedasticity",titleZh:"异方差稳健协方差估计与检验",sourceTitle:"A Heteroskedasticity-Consistent Covariance Matrix Estimator and a Direct Test for Heteroskedasticity",authors:"Halbert White",venue:"Econometrica",year:"1980",kind:"paper",topic:"research-methods",data:"regression design; residuals; sample size",dataZh:"回归设计；残差；样本量",summary:{en:"Explains robust covariance estimation when regression errors have unequal variances.",zh:"说明回归误差方差不同时如何进行稳健协方差估计。"},related:{recipes:["pit-fundamentals-panel","adjusted-price-series"]},sources:[{label:"DOI",url:"https://doi.org/10.2307/1912934"}]},{id:"a-simple-positive-semi-definite-heteroskedasticity-and-autocorrelation-consistent-covariance-matrix",title:"A Simple, Positive Semi-Definite, Heteroskedasticity and Autocorrelation Consistent Covariance Matrix",titleZh:"异方差与自相关稳健协方差矩阵",sourceTitle:"A Simple, Positive Semi-Definite, Heteroskedasticity and Autocorrelation Consistent Covariance Matrix",authors:"Whitney K. Newey · Kenneth D. West",venue:"Econometrica",year:"1987",kind:"paper",topic:"research-methods",data:"ordered observations; regression residuals; bandwidth",dataZh:"有序观测；回归残差；带宽",summary:{en:"Provides covariance estimation for dependent and heteroskedastic observations.",zh:"为存在依赖性与异方差的观测提供协方差估计。"},related:{recipes:["pit-fundamentals-panel","adjusted-price-series"]},sources:[{label:"DOI",url:"https://doi.org/10.2307/1913610"}],readingNotes:[{title:{zh:"首先问估计结果有多不确定",en:"Start with uncertainty around estimates"},body:{zh:"论文讨论矩条件估计中的渐近协方差：参数估计不仅需要一个数值，还需要描述其不确定性，才能构造置信区间或检验。矩条件本身要求相应期望为零。如果这一识别前提错误，改用稳健协方差并不会自动使估计拥有正确的经济含义。",en:"The paper studies asymptotic covariance in moment-based estimation. A parameter estimate needs an uncertainty measure for confidence intervals and tests. The underlying moments must have zero expectation; changing the covariance estimator cannot automatically repair an invalid identifying condition."},reference:{url:"https://www.nber.org/system/files/working_papers/t0055/t0055.pdf",label:{zh:"原文定位：1986年2月修订工作论文，第1页",en:"Source: February 1986 revised working paper, pp. 1"}}},{title:{zh:"序列相关使不同时间共同影响方差",en:"Dependence links observations across time"},body:{zh:"长期协方差不仅包含同一期矩向量的波动，还包含不同滞后之间的协方差。忽略这些项会遗漏时间依赖结构；异方差又意味着波动规模并不固定。这里处理的是用于推断的协方差对象，不能把它误读成预测未来价格波动的直接模型。",en:"Long-run covariance includes both contemporaneous variation in the moment vector and lagged covariances. Omitting lag terms discards temporal dependence, while heteroskedasticity allows changing variation. This is a covariance object for inference, not by itself a model that forecasts future price volatility."},reference:{url:"https://www.nber.org/system/files/working_papers/t0055/t0055.pdf",label:{zh:"原文定位：1986年2月修订工作论文，第1–2页",en:"Source: February 1986 revised working paper, pp. 1–2"}}},{title:{zh:"直接截断求和可能产生负方差问题",en:"Unweighted truncation can misbehave"},body:{zh:"一种直观做法是把有限个滞后的样本协方差直接相加，但所得矩阵在有限样本中未必半正定。这样可能出现负的估计方差或难以解释的检验统计量。作者要解决的不只是能否算出结果，还包括协方差估计是否具有必要的数学性质。",en:"Simply summing sample covariances over finitely many lags need not produce a positive semidefinite matrix in a finite sample. Negative estimated variances or problematic test statistics may follow. The construction therefore addresses a mathematical property of covariance estimation, not just computational convenience."},reference:{url:"https://www.nber.org/system/files/working_papers/t0055/t0055.pdf",label:{zh:"原文定位：1986年2月修订工作论文，第2–3页",en:"Source: February 1986 revised working paper, pp. 2–3"}}},{title:{zh:"离得更远的滞后获得更小权重",en:"More distant lags receive smaller weights"},body:{zh:"论文使用随滞后递减的权重：若截断参数为m，第j阶的权重是1−j/(m+1)，并把滞后协方差与其转置一起加入。同一期项另行保留。实现时需要同时核对索引、转置与权重，不能只保留“使用若干滞后”这个笼统描述。",en:"With truncation parameter m, lag j receives weight 1−j/(m+1); its covariance and transpose enter together alongside the contemporaneous term. Implementation requires consistent lag indexing, transposes and weights, not merely an instruction to include a few lagged observations."},reference:{url:"https://www.nber.org/system/files/working_papers/t0055/t0055.pdf",label:{zh:"原文定位：1986年2月修订工作论文，第3–4页",en:"Source: February 1986 revised working paper, pp. 3–4"}}},{title:{zh:"半正定不等于一定能求逆",en:"Positive semidefinite does not mean invertible"},body:{zh:"该加权构造保证的半正定性质允许零特征值，并不等于矩阵必然严格正定或可逆。存在冗余矩条件、秩不足或数值问题时，后续计算仍需检查。不要把这项性质理解为每个检验都一定有效，或任何样本下都能直接完成矩阵求逆。",en:"The positive semidefinite property permits zero eigenvalues and does not guarantee invertibility. Redundant moments, rank deficiency or numerical problems still need scrutiny. This property is not a promise that every test is valid or that matrix inversion succeeds for every sample."},reference:{url:"https://www.nber.org/system/files/working_papers/t0055/t0055.pdf",label:{zh:"原文定位：1986年2月修订工作论文，第3–4页",en:"Source: February 1986 revised working paper, pp. 3–4"}}},{title:{zh:"滞后设置和样本仍影响推断",en:"Lag choices and sample size still matter"},body:{zh:"一致性是随样本增长、在相应假设下成立的结论，不能直接等同于短样本的准确置信区间。截断参数决定保留多少依赖信息，也会影响估计噪声。阅读经验研究时，应记录滞后规则与样本频率，而不是只看到“Newey–West”名称就停止核对。",en:"Consistency is an asymptotic statement under assumptions, not a guarantee of accurate confidence intervals in short samples. Truncation governs retained dependence information and estimation noise. An empirical study should state its lag rule and observation frequency rather than relying on the Newey–West label alone."},reference:{url:"https://www.nber.org/system/files/working_papers/t0055/t0055.pdf",label:{zh:"原文定位：1986年2月修订工作论文，第1–4页",en:"Source: February 1986 revised working paper, pp. 1–4"}}}],readerLimits:{zh:"导读依据1986年修订工作论文，题录保留1987年期刊版。稳健协方差依赖矩条件与渐近假设，不能修复内生性，也不保证小样本推断准确。",en:"This guide uses the revised 1986 working paper and retains the 1987 journal citation. Robust covariance relies on moment conditions and asymptotic assumptions; it does not repair endogeneity or guarantee accurate small-sample inference."}},{id:"estimating-standard-errors-in-finance-panel-data-sets-comparing-approaches",title:"Estimating Standard Errors in Finance Panel Data Sets: Comparing Approaches",titleZh:"金融面板数据标准误的比较",sourceTitle:"Estimating Standard Errors in Finance Panel Data Sets: Comparing Approaches",authors:"Mitchell A. Petersen",venue:"Review of Financial Studies",year:"2009",kind:"paper",topic:"research-methods",data:"firm-time panel; cluster identifiers; regression residuals",dataZh:"企业时间面板；聚类标识；回归残差",summary:{en:"Compares standard-error methods under firm and time dependence.",zh:"比较企业维度和时间维度依赖下的标准误方法。"},related:{recipes:["pit-fundamentals-panel","adjusted-price-series"]},sources:[{label:"DOI",url:"https://doi.org/10.1093/rfs/hhn053"}],readingNotes:[{title:{zh:"更多行不一定是更多独立信息",en:"Rows are not independent evidence"},body:{zh:"Petersen研究公司金融与资产定价中常见的面板数据：同一家公司跨年度的残差可能相关，同一年不同公司的残差也可能相关。忽略这些联系，会让不确定性的估计失真。",en:"Petersen studies panels where residuals may correlate within firms over time or across firms in a year. Ignoring these links can distort uncertainty, even with many rows."}},{title:{zh:"分别构造公司效应与时间效应",en:"Separate firm effects from time effects"},body:{zh:"工作论文先模拟同一公司跨期相关，再模拟同一时期跨公司相关，随后把两者组合。Fama–MacBeth与按公司聚类针对的依赖结构不同，因此不能因为两者都常见就互换。比较结果之前，先指出你的数据可能在哪个方向共享误差。",en:"The working paper first simulates within-firm dependence, then within-period dependence across firms, before combining them. Fama–MacBeth and firm-clustered inference address different dependence patterns; their popularity does not make them interchangeable. Identify which observations may share errors before comparing reported significance."},reference:{url:"https://www.nber.org/system/files/working_papers/w11280/w11280.pdf",label:{zh:"2006年工作论文引言：第II–IV节的比较设计",en:"2006 working-paper introduction: design of Sections II–IV"}}},{title:{zh:"先描述依赖，再选择标准误",en:"Describe dependence first"},body:{zh:"论文比较文献中常见的处理方法，并解释它们何时一致、何时不同。本站建议先写清观测单位、公司与时间维度、可能共同的冲击，再选择方法，不按哪一种给出的显著性更高来挑选。",en:"The paper compares common approaches and explains when they agree or diverge. Define the observation unit, firm/time dimensions and common shocks before choosing a method, not after comparing significance."}},{title:{zh:"控制平均差异不等于处理全部相关",en:"Mean controls and dependence differ"},body:{zh:"把公司或年度差异放入模型，与正确估计剩余误差的相关结构，是两个相关但不同的任务。固定效应不能被当作自动解决一切标准误问题的标签；具体设定仍要回到原文与数据结构。",en:"Controlling average firm or year differences is distinct from estimating remaining residual dependence. Fixed effects are not a label that automatically resolves every standard-error problem; specifications must match the data structure."}},{title:{zh:"标准误修正不能修复解释变量内生性",en:"An uncertainty correction does not fix endogeneity"},body:{zh:"第II.A节为说明标准误问题，明确假设模型设定正确，解释变量与误差独立。这使讨论聚焦于相关误差带来的不确定性。编辑建议：将这一前提单列；即使聚类方式合适，遗漏变量、反向因果或错误时间对齐仍可能影响系数，不能被一个“稳健”标签消除。",en:"Section II.A assumes a correctly specified model with regressors independent of errors to isolate the uncertainty problem. Editorial application: state that premise separately. Appropriate clustering does not remove coefficient problems arising from omitted variables, reverse causality or incorrect timing; the word 'robust' is not a general identification guarantee."},reference:{url:"https://www.nber.org/system/files/working_papers/w11280/w11280.pdf",label:{zh:"2006年工作论文第II.A节：模型前提",en:"2006 working paper §II.A: model assumptions"}}},{title:{zh:"把阅读路线落到数据组织",en:"Make the panel structure explicit"},body:{zh:"从事件研究继续到这篇，重点转向多个公司与多个时点的共同变化。本站建议保存稳定实体ID、期间、版本和分组键，检查重复观测；若基础表就把修订当成独立样本，后续统计修正不能恢复正确的信息集合。",en:"Following event studies, focus on common variation across firms and dates. Keep stable IDs, periods, versions and grouping keys; audit duplicates. Statistical corrections cannot repair amendments mistakenly counted as independent observations."}}],readerLimits:{zh:"补充细节来自2006年工作论文，正式发表身份保留。依赖方向、分组数量与模型设定决定适用方法，没有一种标准误对所有数据都正确。",en:"Additional detail comes from the 2006 working paper, separately from its final publication identity. Dependence direction, cluster counts and specification matter; no standard-error method is universally correct."}},{id:"robust-inference-with-multiway-clustering",title:"Robust Inference With Multiway Clustering",titleZh:"多维聚类下的稳健推断",sourceTitle:"Robust Inference With Multiway Clustering",authors:"A. Colin Cameron · Jonah B. Gelbach · Douglas L. Miller",venue:"Journal of Business & Economic Statistics",year:"2011",kind:"paper",topic:"research-methods",data:"panel observations; multiple cluster IDs; design matrix",dataZh:"面板观测；多个聚类标识；设计矩阵",summary:{en:"Develops inference with dependence along more than one clustering dimension.",zh:"研究多个聚类维度存在依赖时的统计推断。"},related:{recipes:["pit-fundamentals-panel","adjusted-price-series"]},sources:[{label:"DOI",url:"https://doi.org/10.1198/jbes.2010.07136"}]},{id:"event-studies-in-economics-and-finance",title:"Event Studies in Economics and Finance",titleZh:"经济与金融中的事件研究",sourceTitle:"Event Studies in Economics and Finance",authors:"A. Craig MacKinlay",venue:"Journal of Economic Literature",year:"1997",kind:"paper",topic:"research-methods",data:"event dates; returns; estimation and event windows",dataZh:"事件日期；收益；估计窗口与事件窗口",summary:{en:"Sets out event-window construction, expected-return benchmarks, and testing issues.",zh:"梳理事件窗口、预期收益基准和检验问题。"},related:{recipes:["pit-fundamentals-panel","adjusted-price-series"]},sources:[{label:"Journal of Economic Literature",url:"https://www.jstor.org/stable/2729691"}],readingNotes:[{title:{zh:"怎样区分事件与市场本身？",en:"Separating an event from the market"},body:{zh:"MacKinlay介绍事件研究如何利用事件附近的证券价格考察经济影响。关键不是只看涨跌，而是先构造“没有这个事件时”的正常收益基准，再观察实际收益与基准的差异。",en:"MacKinlay reviews how security prices around an event can help study economic effects. The key is not the price move alone: define a normal-return benchmark without conditioning on the event, then compare actual performance with that benchmark."}},{title:{zh:"先定义意外消息，而不是先按涨跌分组",en:"Define the news surprise before grouping by returns"},body:{zh:"原文用季度盈余公告举例，研究对象是1989—1993年道指30家公司的公告，并依据实际盈余与预期的差异区分消息。编辑建议：事件分类要来自事先定义的信息，不能看到股价上涨后再把公告标为好消息，否则分类本身已包含了要解释的结果。",en:"The illustrative study concerns quarterly earnings announcements for 30 Dow firms in 1989–1993, classifying news by actual earnings relative to expectations. Editorial application: define event categories from a prespecified information measure, not the observed price response. Labeling rising-price events as good news embeds the outcome in the classification."},reference:{url:"https://storage.courtlistener.com/recap/gov.uscourts.txsd.1759270/gov.uscourts.txsd.1759270.250.1.pdf",label:{zh:"原文第3节：盈余公告示例",en:"Original §3: earnings-announcement example"}}},{title:{zh:"事件窗口与估计窗口分开",en:"Separate event and estimation windows"},body:{zh:"先定义事件和样本筛选条件，再确定事件窗口；正常收益模型通常用事件发生前、且不与事件窗口重叠的资料估计。盘后公告的影响可能进入次日，预先泄露或预期也可能体现在事件前，窗口选择因此属于研究设计的一部分。",en:"Define the event and sample selection before choosing its window. Normal-return models are commonly estimated on earlier, non-overlapping observations. After-hours announcements may affect the next session, while anticipation may appear earlier. Window selection is part of the design."}},{title:{zh:"异常收益只是分析的起点",en:"Abnormal returns are a starting point"},body:{zh:"计算异常收益后，还需要决定如何跨时间、跨公司汇总，以及如何进行统计推断。作者提醒样本偏差和少数观测的影响。某一天偏离市场，并不能单独证明事件造成了该变化。",en:"After computing abnormal returns, researchers must decide how to aggregate across time and firms and how to conduct inference. The review highlights selection bias and influential observations. A one-day departure from market performance alone does not prove causation."}},{title:{zh:"经济模型也需要统计假设",en:"Economic models still require statistical assumptions"},body:{zh:"第4节把正常收益模型区分为统计型与经济型：前者主要依赖收益过程假设，后者加入经济行为限制，但实际使用仍需要统计设定。选择更复杂的模型不是自动获得更强识别；应说明基准、估计期和残差性质为何适合这一类事件。",en:"Section 4 distinguishes statistical normal-return models from models imposing economic restrictions. Economic models still need statistical assumptions in practice. Complexity is not automatic identification strength: explain why the benchmark, estimation window and residual assumptions are appropriate for the event class being studied."},reference:{url:"https://storage.courtlistener.com/recap/gov.uscourts.txsd.1759270/gov.uscourts.txsd.1759270.250.1.pdf",label:{zh:"原文第4节：正常收益模型",en:"Original §4: models of normal performance"}}},{title:{zh:"从事件时间线开始准备",en:"Begin with an event timeline"},body:{zh:"本站建议先完成带时区的发布时间、首次可见时间、修订关系和交易日映射，再考虑收益计算。没有这些时点，精细的统计检验也无法修复错位的样本。教程中的时间线示例只完成这一步，不自动输出事件研究结论。",en:"Prepare timezone-aware release times, first-seen times, revisions and session mapping before computing returns. Statistical sophistication cannot repair a misaligned sample. The accompanying timeline tutorial completes this preparation step without producing an event-study conclusion."}}],readerLimits:{zh:"并发事件、样本选择和跨公司相关性会影响解释与推断。事件窗口中的相关性不自动构成因果识别。",en:"Confounding events, selection and cross-firm dependence affect interpretation and inference. Correlation within an event window is not automatic causal identification."}},{id:"using-daily-stock-returns-the-case-of-event-studies",title:"Using Daily Stock Returns: The Case of Event Studies",titleZh:"用日股票收益开展事件研究",sourceTitle:"Using daily stock returns",authors:"Stephen J. Brown · Jerold B. Warner",venue:"Journal of Financial Economics",year:"1985",kind:"paper",topic:"research-methods",data:"daily returns; event assignments; benchmark returns",dataZh:"日收益；事件分配；基准收益",summary:{en:"Evaluates event-study methods using daily return observations.",zh:"利用日收益观测评估事件研究方法。"},related:{recipes:["pit-fundamentals-panel","adjusted-price-series"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/0304-405x(85)90042-x"}],readingNotes:[{title:{zh:"检验方法会不会自己制造事件",en:"Can the test manufacture an event?"},body:{zh:"Brown与Warner研究日收益的厚尾、非同步交易与方差变化，是否会破坏事件研究中的统计检验。问题是方法在没有异常表现时会不会误报，以及存在给定异常表现时能不能发现，而不是证明某一类公司公告必然影响价格。",en:"Brown and Warner ask how daily-return properties affect event-study tests. They examine false rejection when abnormal performance is absent and detection when a known effect is introduced. They do not establish the impact of one particular announcement category."}},{title:{zh:"真实收益配上虚构事件日",en:"Actual returns, artificial event dates"},body:{zh:"作者从CRSP随机有放回抽取证券与事件日期，构造250组、每组50只证券，日期范围为1962年7月至1979年12月。收益来自历史市场，但事件是随机指定的。因此这是一项方法模拟，不能把样本理解成250次真实公告。",en:"The experiment constructs 250 samples of 50 securities, drawing securities and event dates with replacement from CRSP, July 1962–December 1979. Returns are historical, but events are assigned randomly. These are methodological simulations, not 250 observed announcement episodes."},reference:{url:"https://bandi.feb.uns.ac.id/wp-content/uploads/2010/03/brown-warner-1985-1.pdf",label:{zh:"原文第3.1节：实验样本",en:"Original §3.1: experimental samples"}}},{title:{zh:"先估计正常表现，再看事件窗口",en:"Estimate normal performance first"},body:{zh:"每只证券最多使用事件前244日至后5日的250个日收益；前239日为估计期，最后11日为事件期。作者比较均值调整、市场调整和OLS市场模型。不同基准给出不同的异常收益定义，估计窗口与事件窗口不能互相污染。",en:"Up to 250 returns span days −244 through +5: 239 estimation days and an 11-day event period. Mean-adjusted, market-adjusted and OLS market-model measures are compared. Each benchmark defines abnormal performance differently, and estimation and event windows must remain separate."},reference:{url:"https://bandi.feb.uns.ac.id/wp-content/uploads/2010/03/brown-warner-1985-1.pdf",label:{zh:"原文第3.1–3.2节：窗口与超额收益",en:"Original §§3.1–3.2: windows and excess returns"}}},{title:{zh:"误报率和检验能力是两件事",en:"Size and power are different"},body:{zh:"没有人为加入异常收益时，观察拒绝原假设的频率；随后向事件日收益加入已知幅度，观察方法能否检出。前者考察误报，后者考察检验能力。仅展示一次显著结果，既不能证明方法校准，也不能说明未显著时确实没有经济效应。",en:"With no added abnormal return, rejection frequency measures test size. Adding a known event-day effect probes power. One significant result establishes neither calibration nor the ability to detect plausible effects; an insignificant result is not automatically evidence of no economic effect."}},{title:{zh:"结果不是忽略相关性的通行证",en:"The findings are not a dependence waiver"},body:{zh:"论文报告标准日频方法在不少模拟情形下表现良好，同时指出超额收益自相关和事件引起的方差变化有时值得调整。某些设定中更复杂的相关性处理未必更有检验力，但不能据此忽略真实样本中的集中事件、共同冲击或重叠窗口。",en:"Standard daily procedures perform well in many simulations, while serial dependence and event-induced variance changes sometimes warrant adjustment. More elaborate dependence correction need not always improve power, but that is not permission to ignore clustered events, common shocks or overlapping windows."}},{title:{zh:"从事件定义开始落地",en:"Begin with an event definition"},body:{zh:"编辑建议：先确定事件身份、可得时间与交易日映射，再定义估计窗口、基准和样本单位。对集中发生的事件单独检查依赖结构，并保留未对齐记录。本板块的事件时间线教程只完成这些准备，不替代异常收益估计或因果识别。",en:"Editorial application: define event identity, availability and session mapping before choosing windows, benchmarks and sampling units. Inspect dependence for clustered events and retain unresolved records. The event-timeline tutorial handles preparation only, not abnormal-return estimation or causal identification."}}],readerLimits:{zh:"随机事件模拟的良好表现不自动适用于集中公告、选择性事件或另一市场的交易制度。",en:"Performance under random-event simulation does not automatically transfer to clustered announcements, selected events or another market's trading institutions."}},{id:"the-adjustment-of-stock-prices-to-new-information",title:"The Adjustment of Stock Prices to New Information",titleZh:"股价对新信息的调整",sourceTitle:"The Adjustment of Stock Prices to New Information",authors:"Eugene F. Fama · Lawrence Fisher · Michael C. Jensen · Richard Roll",venue:"International Economic Review",year:"1969",kind:"paper",topic:"research-methods",data:"split announcements; returns; dividends; market index",dataZh:"拆分公告；收益；股息；市场指数",summary:{en:"Studies price behavior around stock splits to illustrate event-time analysis.",zh:"围绕股票拆分研究价格行为，展示事件时间分析。"},related:{recipes:["pit-fundamentals-panel","adjusted-price-series"]},sources:[{label:"DOI",url:"https://doi.org/10.2307/2525569"}]},{id:"a-reality-check-for-data-snooping",title:"A Reality Check for Data Snooping",titleZh:"数据窥探的现实检验",sourceTitle:"A Reality Check for Data Snooping",authors:"Halbert White",venue:"Econometrica",year:"2000",kind:"paper",topic:"research-methods",data:"candidate-model losses; time series; resampling blocks",dataZh:"候选模型损失；时间序列；重采样区块",summary:{en:"Accounts for choosing a model after evaluating many alternatives on the same data.",zh:"处理在同一数据上比较大量方案后再选择模型的问题。"},related:{recipes:["pit-fundamentals-panel","adjusted-price-series"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/1468-0262.00152"}]},{id:"a-test-for-superior-predictive-ability",title:"A Test for Superior Predictive Ability",titleZh:"预测能力比较的统计检验",sourceTitle:"A Test for Superior Predictive Ability",authors:"Peter Reinhard Hansen",venue:"Journal of Business & Economic Statistics",year:"2005",kind:"paper",topic:"research-methods",data:"forecast errors; benchmark losses; bootstrap settings",dataZh:"预测误差；基准损失；自助法设定",summary:{en:"Compares many forecasting procedures while accounting for data snooping.",zh:"在考虑数据窥探的前提下比较多种预测程序。"},related:{recipes:["pit-fundamentals-panel","adjusted-price-series"]},sources:[{label:"DOI",url:"https://doi.org/10.1198/073500105000000063"}]},{id:"comparing-predictive-accuracy",title:"Comparing Predictive Accuracy",titleZh:"比较预测准确性",sourceTitle:"Comparing Predictive Accuracy",authors:"Francis X. Diebold · Roberto S. Mariano",venue:"Journal of Business & Economic Statistics",year:"1995",kind:"paper",topic:"research-methods",data:"paired forecasts; realized values; loss differential",dataZh:"配对预测；真实值；损失差",summary:{en:"Tests differences in forecast losses while allowing serial dependence.",zh:"允许序列依赖并检验预测损失差异。"},related:{recipes:["pit-fundamentals-panel","adjusted-price-series"]},sources:[{label:"DOI",url:"https://doi.org/10.1080/07350015.1995.10524599"}]},{id:"the-probability-of-backtest-overfitting",title:"The Probability of Backtest Overfitting",titleZh:"回测过拟合概率",sourceTitle:"The probability of backtest overfitting",authors:"David Bailey · Jonathan Borwein · Marcos López de Prado · Qiji Jim Zhu",venue:"The Journal of Computational Finance",year:"2016",kind:"paper",topic:"research-methods",data:"configuration results; train/test splits; selection rules",dataZh:"配置结果；训练测试分割；选择规则",summary:{en:"Examines selection bias when many configurations are evaluated on finite samples.",zh:"研究在有限样本上评估大量配置时的选择偏差。"},related:{recipes:["pit-fundamentals-panel","adjusted-price-series"]},sources:[{label:"DOI",url:"https://doi.org/10.21314/jcf.2016.322"}]},{id:"the-deflated-sharpe-ratio-correcting-for-selection-bias-backtest-overfitting-and-non-normality",title:"The Deflated Sharpe Ratio: Correcting for Selection Bias, Backtest Overfitting, and Non-Normality",titleZh:"修正夏普比率中的选择偏差与非正态性",sourceTitle:`The Deflated Sharpe Ratio:
                    Correcting for Selection Bias, Backtest
                    Overfitting, and Non-Normality`,authors:"David H. Bailey · Marcos López de Prado",venue:"The Journal of Portfolio Management",year:"2014",kind:"paper",topic:"research-methods",data:"return distribution; trial count; sample length",dataZh:"收益分布；试验次数；样本长度",summary:{en:"Explains how multiple trials and return distribution shape affect a performance statistic.",zh:"说明多次试验和收益分布形态如何影响绩效统计量。"},related:{recipes:["pit-fundamentals-panel","adjusted-price-series"]},sources:[{label:"DOI",url:"https://doi.org/10.3905/jpm.2014.40.5.094"}]},{id:"false-discoveries-in-mutual-fund-performance-measuring-luck-in-estimated-alphas",title:"False Discoveries in Mutual Fund Performance: Measuring Luck in Estimated Alphas",titleZh:"基金绩效中的错误发现",sourceTitle:"False Discoveries in Mutual Fund Performance: Measuring Luck in Estimated Alphas",authors:"LAURENT BARRAS · OLIVIER SCAILLET · RUSS WERMERS",venue:"The Journal of Finance",year:"2010",kind:"paper",topic:"research-methods",data:"fund returns; factor returns; test statistics; dead funds",dataZh:"基金收益；因子收益；检验统计量；退出基金",summary:{en:"Uses false-discovery methods to distinguish estimation noise in a large fund sample.",zh:"利用错误发现方法识别大规模基金样本中的估计噪声。"},related:{recipes:["pit-fundamentals-panel","adjusted-price-series"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/j.1540-6261.2009.01527.x"}]},{id:"controlling-the-false-discovery-rate-a-practical-and-powerful-approach-to-multiple-testing",title:"Controlling the False Discovery Rate: A Practical and Powerful Approach to Multiple Testing",titleZh:"控制错误发现率的多重检验方法",sourceTitle:"Controlling the False Discovery Rate: A Practical and Powerful Approach to Multiple Testing",authors:"Yoav Benjamini · Yosef Hochberg",venue:"Journal of the Royal Statistical Society Series B: Statistical Methodology",year:"1995",kind:"paper",topic:"research-methods",data:"hypothesis inventory; p-values; dependence assumptions",dataZh:"假设清单；p值；依赖假设",summary:{en:"Introduces a procedure for controlling false discoveries across simultaneous tests.",zh:"介绍在同时进行多项检验时控制错误发现的方法。"},related:{recipes:["pit-fundamentals-panel","adjusted-price-series"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/j.2517-6161.1995.tb02031.x"}]},{id:"bootstrap-methods-another-look-at-the-jackknife",title:"Bootstrap Methods: Another Look at the Jackknife",titleZh:"自助法与刀切法",sourceTitle:"Bootstrap Methods: Another Look at the Jackknife",authors:"B. Efron",venue:"The Annals of Statistics",year:"1979",kind:"paper",topic:"research-methods",data:"observations; estimator; resampling design",dataZh:"观测；估计量；重采样设计",summary:{en:"Introduces resampling as a way to approximate estimator uncertainty.",zh:"通过重采样近似估计量的不确定性。"},related:{recipes:["pit-fundamentals-panel","adjusted-price-series"]},sources:[{label:"DOI",url:"https://doi.org/10.1214/aos/1176344552"}],readingNotes:[{title:{zh:"重采样要估计的是统计量的分布",en:"The target is a statistic's sampling distribution"},body:{zh:"Efron提出的问题是：只观察到一个样本，如何近似某个统计量在重复抽样下的分布？研究对象可以是偏差、方差或更一般的统计量，而不只是样本均值。先明确要估计什么分布，才能判断重采样结果是否回答了原本的问题。",en:"Efron asks how one observed sample can approximate a statistic's distribution under repeated sampling. The target may concern bias, variance or a more general quantity rather than only a sample mean. Defining that target first determines whether a resampling result answers the intended question."},reference:{url:"https://sites.stat.washington.edu/courses/stat527/s13/readings/ann_stat1979.pdf",label:{zh:"原文定位：1979年期刊版，第1–2页",en:"Source: 1979 journal article, pp. 1–2"}}},{title:{zh:"用经验分布近似未知分布",en:"Replace the unknown distribution with an empirical one"},body:{zh:"基本构造把每个已观察值赋予1/n的概率质量，形成经验分布，再把未知总体分布替换为它。这是从样本出发的近似，并没有创造新的总体信息。原样本若遗漏某类对象，重复抽取现有观测也不会自动恢复那些没有出现的对象。",en:"The basic construction assigns probability mass 1/n to each observed value and substitutes that empirical distribution for the unknown population. This is an approximation based on available data, not new population information. Resampling cannot automatically restore groups absent from the original observations."},reference:{url:"https://sites.stat.washington.edu/courses/stat527/s13/readings/ann_stat1979.pdf",label:{zh:"原文定位：1979年期刊版，第3页",en:"Source: 1979 journal article, pp. 3"}}},{title:{zh:"有放回抽取与打乱顺序不同",en:"Sampling with replacement is not permutation"},body:{zh:"每次从经验分布中有放回抽取n个观测，因此某些原始值可能重复出现，另一些则不出现。它不是简单打乱原样本的顺序。置换检验与这种自助法具有不同随机机制，不能因为都生成很多样本，就把它们的假设与解释混为一谈。",en:"Each bootstrap sample draws n observations with replacement, so some original values repeat and others are absent. This is not merely a permutation of the data. Permutation tests and this bootstrap construction use different random mechanisms, even though both can generate many simulated samples."},reference:{url:"https://sites.stat.washington.edu/courses/stat527/s13/readings/ann_stat1979.pdf",label:{zh:"原文定位：1979年期刊版，第3页",en:"Source: 1979 journal article, pp. 3"}}},{title:{zh:"每次重新计算同一个目标",en:"Recompute a consistently defined target"},body:{zh:"在每个重采样数据上重新计算目标统计量，同时使用经验分布对应的参照量，便形成自助分布。目标如何中心化或标准化会影响近似表现。只汇总重采样后的原始数据分布，而没有重新计算所关心的估计量，通常不是同一个任务。",en:"The target is recalculated on each resample using the corresponding empirical-distribution reference, producing a bootstrap distribution. Centering and scaling can affect approximation quality. Summarizing the resampled raw observations without recomputing the estimator of interest generally answers a different question."},reference:{url:"https://sites.stat.washington.edu/courses/stat527/s13/readings/ann_stat1979.pdf",label:{zh:"原文定位：1979年期刊版，第2–3页",en:"Source: 1979 journal article, pp. 2–3"}}},{title:{zh:"刀切法是相关方法，不是同一个过程",en:"The jackknife is related but not identical"},body:{zh:"普通刀切法通过逐个删去观测重新估计，自助法则从经验分布有放回抽样。论文用线性近似理解二者的联系，并以样本中位数等例子说明适用表现可能不同。不能据此宣称任何统计量都能可靠地刀切，或自助法对所有问题都优于其他方法。",en:"The ordinary jackknife recomputes estimates after leaving out individual observations, whereas the bootstrap resamples with replacement. The paper relates them through linear approximation and discusses differing behavior for statistics such as the median. Neither connection establishes universal reliability or superiority for every statistic."},reference:{url:"https://sites.stat.washington.edu/courses/stat527/s13/readings/ann_stat1979.pdf",label:{zh:"原文定位：1979年期刊版，第1–3页",en:"Source: 1979 journal article, pp. 1–3"}}},{title:{zh:"抽样单位决定保留什么依赖",en:"The sampling unit determines retained dependence"},body:{zh:"原始单样本说明从同一未知分布抽取观测。若把有时间相关的日收益或同一公司多期资料当作独立行抽取，就改变了原有依赖。应用到金融面板前，需要另行说明适合该结构的抽样单位与方法；重复次数更多并不能代替这个设计判断。",en:"The introductory one-sample construction draws observations from one unknown distribution. Treating dependent daily returns or repeated firm records as independent rows changes their dependence. Financial panels need a separately justified sampling unit and method; increasing repetitions cannot substitute for that design decision."},reference:{url:"https://sites.stat.washington.edu/courses/stat527/s13/readings/ann_stat1979.pdf",label:{zh:"原文定位：1979年期刊版，第2–3页",en:"Source: 1979 journal article, pp. 2–3"}}}],readerLimits:{zh:"这里介绍原始单样本构造，不是对所有数据结构的自助法保证。有放回抽样不能自动保留时间、公司或群组依赖；增加重复次数也不会修复样本偏差。",en:"This guide describes the original one-sample construction, not universal bootstrap validity. Sampling with replacement does not automatically preserve time, firm or cluster dependence; more repetitions do not repair sample bias."}},{id:"the-stationary-bootstrap",title:"The Stationary Bootstrap",titleZh:"平稳自助法",sourceTitle:"The Stationary Bootstrap",authors:"Dimitris N. Politis · Joseph P. Romano",venue:"Journal of the American Statistical Association",year:"1994",kind:"paper",topic:"research-methods",data:"ordered series; block-length choice; stationarity checks",dataZh:"有序序列；区块长度；平稳性检查",summary:{en:"Resamples dependent time series using random-length blocks.",zh:"利用随机长度区块重采样有依赖的时间序列。"},related:{recipes:["pit-fundamentals-panel","adjusted-price-series"]},sources:[{label:"DOI",url:"https://doi.org/10.1080/01621459.1994.10476870"}]},{id:"an-introduction-to-the-bootstrap",title:"An Introduction to the Bootstrap",titleZh:"自助法导论",sourceTitle:"An Introduction to the Bootstrap",authors:"Bradley Efron · R.J. Tibshirani",venue:"Chapman and Hall/CRC",year:"1994",kind:"book",topic:"research-methods",data:"sample observations; estimator definitions; resampling seed",dataZh:"样本观测；估计量定义；重采样种子",summary:{en:"Provides a general reference for resampling estimates, intervals, and model uncertainty.",zh:"系统介绍重采样估计、区间和模型不确定性。"},related:{recipes:["pit-fundamentals-panel","adjusted-price-series"]},sources:[{label:"DOI",url:"https://doi.org/10.1201/9780429246593"}]},{id:"regression-shrinkage-and-selection-via-the-lasso",title:"Regression Shrinkage and Selection via the Lasso",titleZh:"Lasso回归收缩与变量选择",sourceTitle:"Regression Shrinkage and Selection Via the Lasso",authors:"Robert Tibshirani",venue:"Journal of the Royal Statistical Society Series B: Statistical Methodology",year:"1996",kind:"paper",topic:"research-methods",data:"predictor matrix; response; temporal validation splits",dataZh:"预测变量矩阵；响应；时间验证分割",summary:{en:"Studies coefficient shrinkage and variable selection through an absolute-value penalty.",zh:"利用绝对值惩罚研究系数收缩与变量选择。"},related:{recipes:["pit-fundamentals-panel","adjusted-price-series"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/j.2517-6161.1996.tb02080.x"}],readingNotes:[{title:{zh:"在偏差、方差与简洁性之间取舍",en:"Trade bias against variance and complexity"},body:{zh:"普通最小二乘可能具有较大估计方差，完整模型也可能难以解释。Lasso通过收缩系数并让部分系数为零，在预测与简洁性之间寻求取舍。增加偏差有时能降低预测误差，但这不是任何数据都必然改善，更不等于找到了唯一真实模型。",en:"Ordinary least squares can have substantial variance and a full model may be hard to interpret. Lasso shrinks coefficients and sets some to zero, balancing prediction and simplicity. Added bias can sometimes reduce prediction error, but improvement is not universal and the selected model need not be uniquely true."},reference:{url:"https://sites.stat.washington.edu/courses/stat527/s13/readings/j_royal_stat_soc_b1996.pdf",label:{zh:"原文定位：1996年期刊版，第267页",en:"Source: 1996 journal article, pp. 267"}}},{title:{zh:"约束上限越小，收缩越强",en:"A smaller bound means more shrinkage"},body:{zh:"原文最小化残差平方和，同时限制系数绝对值之和不超过t。较小的约束上限通常意味着更强收缩；这与常见惩罚形式中参数越大、惩罚越强的方向不同。比较软件参数时，先确认使用的是约束上限还是惩罚权重，不能只比较数值大小。",en:"The original formulation minimizes residual sum of squares subject to an absolute-coefficient sum bounded by t. A smaller constraint bound means more shrinkage, unlike a penalty-weight formulation where a larger weight penalizes more. Software parameters must be identified by formulation before their numerical sizes are compared."},reference:{url:"https://sites.stat.washington.edu/courses/stat527/s13/readings/j_royal_stat_soc_b1996.pdf",label:{zh:"原文定位：1996年期刊版，第268页",en:"Source: 1996 journal article, pp. 268"}}},{title:{zh:"变量尺度会改变惩罚含义",en:"Predictor scale changes the penalty's meaning"},body:{zh:"论文先将解释变量中心化并缩放到统一尺度。若一个字段以元计、另一个以百万元计，同样大小的系数惩罚并不代表同样的变量影响。用于新数据时应保留缩放规则，并在训练资料上确定变换，不能用后来观察到的信息改善历史预测。",en:"Predictors are centered and standardized before fitting. A coefficient penalty has a different meaning when one input is measured in units and another in millions. For new predictive applications, preserve scaling rules and estimate transformations from training data rather than using later observations to improve historical predictions."},reference:{url:"https://sites.stat.washington.edu/courses/stat527/s13/readings/j_royal_stat_soc_b1996.pdf",label:{zh:"原文定位：1996年期刊版，第268页",en:"Source: 1996 journal article, pp. 268"}}},{title:{zh:"零系数来自收缩，不是显著性裁决",en:"A zero coefficient is not a significance verdict"},body:{zh:"在正交设计的说明中，Lasso表现为软阈值收缩：较小的系数被压至零，较大的也会缩小。这个例子帮助理解它与岭回归和子集选择的差异，但实际相关解释变量的情形更复杂。零系数不是证明某变量在经济上永远没有作用。",en:"In the orthonormal illustration, soft thresholding sets smaller coefficients to zero and shrinks larger ones. It clarifies differences from ridge regression and subset selection, but correlated predictors are more complicated. A zero fitted coefficient does not prove that a variable is economically irrelevant in every setting."},reference:{url:"https://sites.stat.washington.edu/courses/stat527/s13/readings/j_royal_stat_soc_b1996.pdf",label:{zh:"原文定位：1996年期刊版，第269页",en:"Source: 1996 journal article, pp. 269"}}},{title:{zh:"调参目标是预测误差",en:"Tuning targets predictive error"},body:{zh:"论文讨论交叉验证、广义交叉验证等选择收缩程度的方法，并以非金融资料展示模型。验证方式决定参数选择回答什么问题。对有时间先后关系的金融数据，不能直接把独立观测示例中的分折程序当成已经处理了时间泄漏或市场制度变化。",en:"Cross-validation and generalized cross-validation help select shrinkage, illustrated with nonfinancial data. The validation design determines the question answered by tuning. For ordered financial observations, the independent-data example does not establish protection against temporal leakage or changing market regimes."},reference:{url:"https://sites.stat.washington.edu/courses/stat527/s13/readings/j_royal_stat_soc_b1996.pdf",label:{zh:"原文定位：1996年期刊版，第273–275页",en:"Source: 1996 journal article, pp. 273–275"}}},{title:{zh:"固定参数与重新调参的不确定性不同",en:"Retuning introduces another source of uncertainty"},body:{zh:"论文比较自助样本中固定收缩参数与每次重新选择参数的标准误，后者加入额外的选择变化。报告一个固定模型的系数波动，不能自动概括完整建模流程的不确定性。解释结果时应说明是否重新调参，以及哪些步骤在重复样本中被固定。",en:"The example compares bootstrap standard errors with shrinkage held fixed and reselected in each sample; retuning adds selection variation. Variation around one fixed model does not automatically describe uncertainty in the full modeling procedure. State whether tuning is repeated and which steps remain fixed across samples."},reference:{url:"https://sites.stat.washington.edu/courses/stat527/s13/readings/j_royal_stat_soc_b1996.pdf",label:{zh:"原文定位：1996年期刊版，第274–275页",en:"Source: 1996 journal article, pp. 274–275"}}}],readerLimits:{zh:"Lasso的变量选择依赖缩放、样本和调参目标，不证明被选变量具有因果作用。原文的独立观测设定与示例不能直接替代金融时间序列的验证设计。",en:"Lasso selection depends on scaling, samples and tuning objectives; selected variables are not thereby causal. The paper's independent-observation setup and example do not replace validation designed for financial time series."}},{id:"regularization-and-variable-selection-via-the-elastic-net",title:"Regularization and Variable Selection via the Elastic Net",titleZh:"弹性网正则化与变量选择",sourceTitle:"Regularization and Variable Selection Via the Elastic Net",authors:"Hui Zou · Trevor Hastie",venue:"Journal of the Royal Statistical Society Series B: Statistical Methodology",year:"2005",kind:"paper",topic:"research-methods",data:"standardized predictors; response; validation folds",dataZh:"标准化变量；响应；验证分组",summary:{en:"Combines penalties to handle correlated predictors and sparse model selection.",zh:"结合不同惩罚处理相关预测变量与稀疏选择。"},related:{recipes:["pit-fundamentals-panel","adjusted-price-series"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/j.1467-9868.2005.00503.x"}]},{id:"random-forests",title:"Random Forests",titleZh:"随机森林",sourceTitle:"Random Forests",authors:"Leo Breiman",venue:"Machine Learning",year:"2001",kind:"paper",topic:"research-methods",data:"feature matrix; labels; out-of-sample evaluation",dataZh:"特征矩阵；标签；样本外评估",summary:{en:"Introduces an ensemble of randomized trees for prediction and variable comparison.",zh:"通过随机化树集成进行预测和变量比较。"},related:{recipes:["pit-fundamentals-panel","adjusted-price-series"]},sources:[{label:"DOI",url:"https://doi.org/10.1023/a:1010933404324"}]},{id:"greedy-function-approximation-a-gradient-boosting-machine",title:"Greedy Function Approximation: A Gradient Boosting Machine",titleZh:"梯度提升机",sourceTitle:"Greedy function approximation: A gradient boosting machine.",authors:"Jerome H. Friedman",venue:"The Annals of Statistics",year:"2001",kind:"paper",topic:"research-methods",data:"features; target; loss function; held-out samples",dataZh:"特征；目标；损失函数；留出样本",summary:{en:"Constructs flexible functions through sequential loss-reducing updates.",zh:"通过逐步降低损失来构造灵活函数。"},related:{recipes:["pit-fundamentals-panel","adjusted-price-series"]},sources:[{label:"DOI",url:"https://doi.org/10.1214/aos/1013203451"}]},{id:"empirical-asset-pricing-via-machine-learning",title:"Empirical Asset Pricing via Machine Learning",titleZh:"机器学习与实证资产定价",sourceTitle:"Empirical Asset Pricing via Machine Learning",authors:"Shihao Gu · Bryan Kelly · Dacheng Xiu",venue:"The Review of Financial Studies",year:"2020",kind:"paper",topic:"research-methods",data:"firm characteristics; returns; temporal training splits",dataZh:"企业特征；收益；时间训练分割",summary:{en:"Compares nonlinear methods for organizing a large set of firm characteristics.",zh:"比较非线性方法如何组织大量企业特征。"},related:{recipes:["pit-fundamentals-panel","adjusted-price-series"]},sources:[{label:"DOI",url:"https://doi.org/10.1093/rfs/hhaa009"}]},{id:"autoencoder-asset-pricing-models",title:"Autoencoder Asset Pricing Models",titleZh:"自编码器资产定价模型",sourceTitle:"Autoencoder asset pricing models",authors:"Shihao Gu · Bryan Kelly · Dacheng Xiu",venue:"Journal of Econometrics",year:"2021",kind:"paper",topic:"research-methods",data:"characteristic panel; returns; model validation periods",dataZh:"特征面板；收益；模型验证期",summary:{en:"Uses latent representations to model conditional exposures and common components.",zh:"利用潜在表示建模条件暴露与共同成分。"},related:{recipes:["pit-fundamentals-panel","adjusted-price-series"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/j.jeconom.2020.07.009"}]},{id:"deep-learning-in-asset-pricing",title:"Deep Learning in Asset Pricing",titleZh:"资产定价中的深度学习",sourceTitle:"Deep Learning in Asset Pricing",authors:"Luyang Chen · Markus Pelger · Jason Zhu",venue:"Management Science",year:"2024",kind:"paper",topic:"research-methods",data:"returns; firm characteristics; macro states; temporal splits",dataZh:"收益；企业特征；宏观状态；时间分割",summary:{en:"Studies flexible representations of pricing kernels using economic restrictions.",zh:"结合经济约束研究定价核的灵活表示。"},related:{recipes:["pit-fundamentals-panel","adjusted-price-series"]},sources:[{label:"DOI",url:"https://doi.org/10.1287/mnsc.2023.4695"}]},{id:"characteristics-are-covariances-a-unified-model-of-risk-and-return",title:"Characteristics Are Covariances: A Unified Model of Risk and Return",titleZh:"特征即协方差：风险与收益的统一模型",sourceTitle:"Characteristics are covariances: A unified model of risk and return",authors:"Bryan T. Kelly · Seth Pruitt · Yinan Su",venue:"Journal of Financial Economics",year:"2019",kind:"paper",topic:"research-methods",data:"firm characteristics; return panel; factor dimension",dataZh:"企业特征；收益面板；因子维度",summary:{en:"Uses characteristics to model changing factor exposures across firms and time.",zh:"利用特征描述企业与时间维度上变化的因子暴露。"},related:{recipes:["pit-fundamentals-panel","adjusted-price-series"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/j.jfineco.2019.05.001"}]},{id:"a-simple-approximate-long-memory-model-of-realized-volatility",title:"A Simple Approximate Long-Memory Model of Realized Volatility",titleZh:"已实现波动率的简单近似长记忆模型",sourceTitle:"A Simple Approximate Long-Memory Model of Realized Volatility",authors:"Fulvio Corsi",venue:"Journal of Financial Econometrics",year:"2009",kind:"paper",topic:"research-methods",data:"intraday returns; daily realized variance; calendar windows",dataZh:"日内收益；日已实现方差；日历窗口",summary:{en:"Combines daily, weekly, and monthly volatility components in a parsimonious model.",zh:"用简约模型结合日、周、月尺度波动成分。"},related:{recipes:["pit-fundamentals-panel","adjusted-price-series"]},sources:[{label:"Journal of Financial Econometrics",url:"https://academic.oup.com/jfec/article-abstract/7/2/174/856522"}]},{id:"realized-kernels-in-practice-trades-and-quotes",title:"Realized Kernels in Practice: Trades and Quotes",titleZh:"实践中的已实现核：成交与报价",sourceTitle:"Realized kernels in practice: trades and quotes",authors:"O. E. Barndorff‐Nielsen · P. Reinhard Hansen · A. Lunde · N. Shephard",venue:"The Econometrics Journal",year:"2009",kind:"paper",topic:"research-methods",data:"high-frequency trades; quotes; sampling and kernel choices",dataZh:"高频成交；报价；采样与核函数选择",summary:{en:"Studies volatility estimation when high-frequency observations contain market noise.",zh:"研究高频观测含市场噪声时的波动率估计。"},related:{recipes:["pit-fundamentals-panel","adjusted-price-series"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/j.1368-423x.2008.00275.x"}]},{id:"microstructure-noise-in-the-continuous-case-the-pre-averaging-approach",title:"Microstructure Noise in the Continuous Case: The Pre-Averaging Approach",titleZh:"连续情形下的微观结构噪声：预平均方法",sourceTitle:"Microstructure noise in the continuous case: The pre-averaging approach",authors:"Jean Jacod · Yingying Li · Per A. Mykland · Mark Podolskij · Mathias Vetter",venue:"Stochastic Processes and their Applications",year:"2009",kind:"paper",topic:"research-methods",data:"high-frequency prices; noise assumptions; window sizes",dataZh:"高频价格；噪声假设；窗口长度",summary:{en:"Uses local averaging to reduce noise in high-frequency variance estimation.",zh:"用局部平均减少高频方差估计中的噪声。"},related:{recipes:["pit-fundamentals-panel","adjusted-price-series"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/j.spa.2008.11.004"}]},{id:"do-stock-prices-fully-reflect-information-in-accruals-and-cash-flows-about-future-earnings",title:"Do Stock Prices Fully Reflect Information in Accruals and Cash Flows about Future Earnings?",titleZh:"股价是否反映应计项目与现金流信息？",sourceTitle:"Do Stock Prices Fully Reflect Information in Accruals and Cash Flows About Future Earnings?",authors:"Richard G. Sloan",venue:"The Accounting Review",year:"1996",kind:"paper",topic:"corporate-fundamentals",data:"income statements; cash flows; accruals; filing dates",dataZh:"利润表；现金流；应计项目；披露日期",summary:{en:"Distinguishes accrual and cash-flow components when interpreting earnings persistence.",zh:"解释盈利持续性时区分应计与现金流成分。"},related:{datasets:["cn-pit-fundamentals","cn-company-master"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.2308/tar-9608042309"}],readingNotes:[{title:{zh:"同样的利润，能否同样持续",en:"Can equal earnings persist differently?"},body:{zh:"Sloan把当期利润拆成应计与现金流部分，研究它们对未来利润的含义是否不同，以及价格是否充分区分这种差别。问题不是简单地把应计项目判成坏消息，而是考察会计组成与持续性之间的联系。",en:"Sloan separates earnings into accrual and cash-flow components, asking whether their persistence differs and whether prices reflect that difference. Accruals are not simply classified as bad news; the question concerns the information in earnings composition."}},{title:{zh:"30年的美国公司数据",en:"Thirty years of US company data"},body:{zh:"论文将1993版Compustat与CRSP文件连接，使用1962—1991年财务资料，最终有40,679个公司年度观察。样本筛选要求必要财务项目、股票收益和后续利润可得；银行与保险等缺少所需应计资料的公司不在这一测量范围内。这不是全市场无条件样本。",en:"The study joins the 1993 Compustat and CRSP files, using financial statements for 1962–1991 and 40,679 firm-years. Required accounting items, returns and subsequent earnings determine inclusion. Banks and insurers lack the necessary accrual data in this setup, so the sample is not unconditional market coverage."},reference:{url:"https://www.cuhk.edu.hk/acy2/workshop/June2009Wasley/1996TAR).pdf",label:{zh:"原文第III节：样本形成",en:"Original §III: sample formation"}}},{title:{zh:"应计口径不是随手相减",en:"Accrual measurement is specific"},body:{zh:"由于现金流量表规则只覆盖样本末期，作者用资产负债表与利润表项目构造经营应计：流动资产变动扣现金，减去调整短期债务和应付税后的流动负债变动，再扣折旧摊销。利润采用折旧后的经营利润，现金部分由利润减应计得到，不能直接替换成任意净利润与现金流字段。",en:"Because cash-flow-statement reporting covers only the sample's final years, operating accruals are reconstructed from balance-sheet changes and depreciation. Earnings use operating income after depreciation; the cash component is the residual after accruals. Arbitrary net-income and cash-flow fields are not interchangeable with these definitions."},reference:{url:"https://www.cuhk.edu.hk/acy2/workshop/June2009Wasley/1996TAR).pdf",label:{zh:"原文第III节：变量定义",en:"Original §III: variable measurement"}}},{title:{zh:"分别检验持续性与定价",en:"Test persistence and pricing separately"},body:{zh:"论文先研究两个组成部分对未来利润的持续性，再检验价格中隐含的预期是否充分区分它们。进一步观察后续异常收益及其是否集中在未来业绩公告附近。这样能把会计关系、价格解释与信息揭示时间联系起来，但每一层都有各自的模型假设。",en:"The tests separate earnings persistence from expectations embedded in prices, then examine subsequent abnormal returns and their concentration around later earnings announcements. Accounting relations, pricing interpretation and information timing are connected, but each layer retains its own assumptions."}},{title:{zh:"发现应怎样理解",en:"How to interpret the finding"},body:{zh:"作者报告应计部分的持续性低于现金部分，价格表现与投资者未充分区分这两者相一致。原文中的历史异常收益是支持这一解释的证据，不是今天可获得同样收益的保证；异常收益也依赖基准模型，不能直接叫作无风险利润。",en:"The paper reports lower persistence for the accrual component and price behavior consistent with incomplete differentiation. Historical abnormal returns support that interpretation; they do not promise a current payoff. Abnormal performance also depends on the benchmark and is not risk-free profit."}},{title:{zh:"读完后先准备版本面板",en:"Prepare a versioned panel first"},body:{zh:"编辑建议：从原文第III节逐项映射会计定义，保留单位、合并范围与报告版本。财年末不等于信息可得日，最新重述值也不能倒填历史。若历史版本或发布日期不足，先把缺口列清，再用时点一致教程验证选择规则，不要先做组合再补解释。",en:"Editorial application: map each Section III definition, preserving units, consolidation scope and filing versions. Fiscal year-end is not availability; latest restatements cannot be backfilled as historical knowledge. Expose missing vintage or release evidence before moving beyond the point-in-time preparation exercise."}}],readerLimits:{zh:"会计准则、行业范围、存活筛选与披露时间都会影响迁移；应计高低本身不是公司质量定论。",en:"Accounting rules, industry coverage, survival filters and disclosure timing affect transferability. Accrual magnitude alone is not a verdict on company quality."}},{id:"value-investing-the-use-of-historical-financial-statement-information-to-separate-winners-from-losers",title:"Value Investing: The Use of Historical Financial Statement Information to Separate Winners from Losers",titleZh:"历史财务报表信息与企业比较",sourceTitle:"Value Investing: The Use of Historical Financial Statement Information to Separate Winners from Losers",authors:"Joseph D. Piotroski",venue:"Journal of Accounting Research",year:"2000",kind:"paper",topic:"corporate-fundamentals",data:"financial statements; book-to-market; announcement dates",dataZh:"财务报表；账面市值比；公告日期",summary:{en:"Combines accounting indicators to study differences within high book-to-market firms.",zh:"结合会计指标研究高账面市值比企业内部的差异。"},related:{datasets:["cn-pit-fundamentals","cn-company-master"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.2307/2672906"}],readingNotes:[{title:{zh:"先限定问题：便宜的股票并不相同",en:"Cheap stocks are not interchangeable"},body:{zh:"Piotroski从高账面市值比股票出发，研究财务报表能否区分其中经营状况较强与较弱的企业。这里的财务信号服务于一个已经限定的价值股样本，并不是先给全市场公司打分，再声称同一阈值适合所有行业、规模和市场。",en:"Piotroski starts with high book-to-market stocks and asks whether financial statements distinguish stronger from weaker firms within that group. The accounting signals address a bounded value-stock sample. They do not establish that a single score threshold applies to every industry, company size or market."},reference:{url:"https://www.ivey.uwo.ca/media/3775523/value_investing_the_use_of_historical_financial_statement_information.pdf",label:{zh:"原文定位：2000年论文，第2, 5–7页",en:"Source: 2000 paper, pp. 2, 5–7"}}},{title:{zh:"盈利与现金流要一起看",en:"Read profitability alongside cash flow"},body:{zh:"盈利组包含四项信号：资产收益为正、经营现金流为正、资产收益改善，以及现金流高于会计利润。利润和现金流使用期初资产缩放；最后一项关注应计成分。只保留净利润是否增长，会丢失现金支持程度与资产规模这两层信息。",en:"Four profitability signals cover positive return on assets, positive operating cash flow, improving return on assets and cash flow exceeding accounting earnings. Earnings and cash flow are scaled by beginning assets; their comparison captures accruals. Earnings growth alone loses both cash support and the asset base underlying profitability."},reference:{url:"https://www.ivey.uwo.ca/media/3775523/value_investing_the_use_of_historical_financial_statement_information.pdf",label:{zh:"原文定位：2000年论文，第7–8页",en:"Source: 2000 paper, pp. 7–8"}}},{title:{zh:"融资状态与经营效率是另外两组",en:"Financing and operations supply five more signals"},body:{zh:"另五项分别观察长期杠杆下降、流动比率改善、没有发行普通股，以及毛利率和资产周转率改善。毛利率的分母是销售额，周转率则连接销售与资产。它们描述不同变化，不能用一个名称宽泛的“盈利能力”字段替代。",en:"Five further signals track lower long-term leverage, improving current ratio, no common-equity issuance, improving gross margin and improving asset turnover. Gross margin uses sales as its denominator, whereas turnover links sales to assets. These are distinct changes, not interchangeable versions of a generic profitability field."},reference:{url:"https://www.ivey.uwo.ca/media/3775523/value_investing_the_use_of_historical_financial_statement_information.pdf",label:{zh:"原文定位：2000年论文，第8–10页",en:"Source: 2000 paper, pp. 8–10"}}},{title:{zh:"九个判断，不是精确的经营刻度",en:"Nine binary judgements, not a continuous scale"},body:{zh:"每项条件满足得一分，合计形成0至9的分数。这样的等权二元表达便于比较，却不保留改善幅度：略有改善与大幅改善可能同得一分。阅读时应保留原始财务值、比较期间和信号方向，避免把一分差异解释成固定的经济距离。",en:"Each satisfied condition contributes one point to a score from zero to nine. Equal-weight binary coding is easy to compare but discards magnitude: slight and substantial improvements can receive the same point. Preserve the underlying financial values, comparison periods and signal directions rather than treating each point as a fixed economic distance."},reference:{url:"https://www.ivey.uwo.ca/media/3775523/value_investing_the_use_of_historical_financial_statement_information.pdf",label:{zh:"原文定位：2000年论文，第7–10页",en:"Source: 2000 paper, pp. 7–10"}}},{title:{zh:"报告期末不是信息可用时点",en:"Respect the gap between fiscal year and use"},body:{zh:"研究样本覆盖1976至1996年，并在每个财政年度结束后的第五个月开始计算持有期收益。高账面市值比的样本筛选也需要财务资料齐备。这个历史时滞不证明其他市场的披露已经完成；实际应用仍要保留公告日期和修订版本。",en:"The sample covers 1976–1996, with holding-period returns beginning in the fifth month after fiscal year-end. High book-to-market selection also requires sufficient accounting data. This historical lag is not proof that disclosure is complete elsewhere; actual publication dates and revised filing versions remain essential for a new dataset."},reference:{url:"https://www.ivey.uwo.ca/media/3775523/value_investing_the_use_of_historical_financial_statement_information.pdf",label:{zh:"原文定位：2000年论文，第11–12页",en:"Source: 2000 paper, pp. 11–12"}}},{title:{zh:"结果也受样本退出规则影响",en:"Exits and exclusions affect interpretation"},body:{zh:"论文比较强弱财务组及整个高账面市值比样本，并使用不同统计检验。它在此处采用退市收益为零的假设，这会影响退出样本的处理。重读结果时，应把样本剔除、退市回报和缺失值规则一起考虑，不能只沿用评分而忽略收益序列如何形成。",en:"The paper compares financially stronger and weaker groups with the wider high book-to-market sample using multiple statistical tests. Its stated convention assumes a zero delisting return. Interpretation therefore needs exclusions, delisting treatment and missing-data rules alongside the score, rather than borrowing the signals while ignoring construction of the return series."},reference:{url:"https://www.ivey.uwo.ca/media/3775523/value_investing_the_use_of_historical_financial_statement_information.pdf",label:{zh:"原文定位：2000年论文，第11–12页",en:"Source: 2000 paper, pp. 11–12"}}}],readerLimits:{zh:"原研究针对历史高账面市值比股票。九项二元信号不是通用质量评级或买卖建议；样本时滞和退市处理会影响结果，迁移时需重新核对。",en:"The historical study concerns high book-to-market stocks. Nine binary signals are not a universal quality rating or a trading recommendation; availability lags and delisting treatment require renewed scrutiny in another sample."}},{id:"earnings-book-values-and-dividends-in-equity-valuation",title:"Earnings, Book Values, and Dividends in Equity Valuation",titleZh:"股票估值中的盈利、账面价值与股息",sourceTitle:"Earnings, Book Values, and Dividends in Equity Valuation*",authors:"JAMES A. OHLSON",venue:"Contemporary Accounting Research",year:"1995",kind:"paper",topic:"corporate-fundamentals",data:"book equity; earnings; dividends; accounting policies",dataZh:"账面权益；盈利；股息；会计政策",summary:{en:"Links accounting quantities to equity valuation under a residual-income framework.",zh:"在剩余收益框架下连接会计量与股票估值。"},related:{datasets:["cn-pit-fundamentals","cn-company-master"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/j.1911-3846.1995.tb00461.x"}]},{id:"the-quality-of-accruals-and-earnings-the-role-of-accrual-estimation-errors",title:"The Quality of Accruals and Earnings: The Role of Accrual Estimation Errors",titleZh:"应计项目与盈利质量",sourceTitle:"The Quality of Accruals and Earnings: The Role of Accrual Estimation Errors",authors:"Patricia M. Dechow · Ilia D. Dichev",venue:"The Accounting Review",year:"2002",kind:"paper",topic:"corporate-fundamentals",data:"working-capital accruals; operating cash flows; fiscal periods",dataZh:"营运资本应计；经营现金流；会计期间",summary:{en:"Examines the relation between accrual estimates and cash-flow realizations.",zh:"考察应计估计与实际现金流之间的关系。"},related:{datasets:["cn-pit-fundamentals","cn-company-master"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.2308/accr.2002.77.s-1.35"}],readingNotes:[{title:{zh:"应计不是现金流的反面",en:"Why accruals can be useful"},body:{zh:"应计可以把不同时间收到或支付的现金，调整到更能表达经营活动的期间。Dechow与Dichev提出的问题是：这种时间匹配依赖估计，而估计错误会怎样影响盈利质量？因此，应计并不是天然有问题，关键在于估计是否与后来实现的现金流相符。",en:"Accruals can improve the timing match between cash flows and operating activity. Dechow and Dichev ask how errors in the estimates required for that matching affect earnings quality. Accrual accounting is not inherently defective; the quality of its estimates matters."}},{title:{zh:"用现金流解释营运资本变化",en:"Relating working capital to cash flows"},body:{zh:"作者提出把营运资本变化与过去、当期及未来的经营现金流联系起来，用不能被解释的部分刻画估计误差。这不是简单比较利润与现金流的大小，而是考察跨期匹配关系。",en:"The proposed measure relates working-capital changes to past, present and future operating cash flows. Unexplained variation is used to characterize estimation noise. This examines matching across periods, rather than merely comparing the level of earnings with cash flow."}},{title:{zh:"“未来现金流”带来的关键边界",en:"The future-cash-flow boundary"},body:{zh:"作者摘要报告应计质量与盈利持续性正相关。阅读中尤其要注意，衡量质量时用到了未来现金流。本期资料即使已经披露，也不代表这个完整质量指标在当时已经可以算出。",en:"The authors report a positive relation between accrual quality and earnings persistence. Crucially, the measure uses future cash-flow realizations. Availability of current statements does not mean that the complete quality measure was available at that same date."}},{title:{zh:"如何放进时点一致研究？",en:"Using it in point-in-time work"},body:{zh:"本站建议分别保存“事后研究标签”和“当时可用输入”。如果把指标放入按时间回看的研究，必须延迟到所有所需报表均已披露，或另行定义只使用历史信息的代理变量；后一种做法不能直接沿用原指标名称而不说明变化。",en:"Keep ex-post research labels separate from contemporaneously available inputs. A historical information-set analysis must wait until all required reports are available, or define a distinct historical-only proxy. Such a proxy should not silently inherit the original measure's name or interpretation."}}],readerLimits:{zh:"此导读依据作者工作论文摘要讨论核心方法；期刊版本的具体设定请以原文为准。残差也可能包含模型遗漏，不能被直接解释为舞弊。",en:"This guide explains the core method from the authors' working-paper abstract; consult the journal edition for exact specifications. Residuals may also reflect model omissions, not misconduct."}},{id:"detecting-earnings-management",title:"Detecting Earnings Management",titleZh:"识别盈余管理",sourceTitle:"Detecting Earnings Management",authors:"Patricia M. Dechow · Richard G. Sloan · Amy P. Sweeney",venue:"The Accounting Review",year:"1995",kind:"paper",topic:"corporate-fundamentals",data:"accruals; revenue; assets; industry and event identifiers",dataZh:"应计项目；收入；资产；行业与事件标识",summary:{en:"Compares models for separating discretionary from normal accrual variation.",zh:"比较区分可操纵与正常应计变化的模型。"},related:{datasets:["cn-pit-fundamentals","cn-company-master"],recipes:["pit-fundamentals-panel"]},sources:[{label:"The Accounting Review",url:"https://www.jstor.org/stable/248303"}]},{id:"earnings-management-during-import-relief-investigations",title:"Earnings Management During Import Relief Investigations",titleZh:"进口救济调查期间的盈余管理",sourceTitle:"Earnings Management During Import Relief Investigations",authors:"Jennifer J. Jones",venue:"Journal of Accounting Research",year:"1991",kind:"paper",topic:"corporate-fundamentals",data:"financial statements; investigation dates; industry controls",dataZh:"财务报表；调查日期；行业控制变量",summary:{en:"Uses an institutional event to investigate accounting discretion.",zh:"利用制度事件研究会计裁量行为。"},related:{datasets:["cn-pit-fundamentals","cn-company-master"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.2307/2491047"}]},{id:"the-detection-of-earnings-manipulation",title:"The Detection of Earnings Manipulation",titleZh:"识别盈利操纵",sourceTitle:"The Detection of Earnings Manipulation",authors:"Messod D. Beneish",venue:"Financial Analysts Journal",year:"1999",kind:"paper",topic:"corporate-fundamentals",data:"statement ratios; labeled cases; comparable controls",dataZh:"报表比率；已标注案例；可比对照",summary:{en:"Studies financial-statement indicators associated with reported manipulation cases.",zh:"研究与已识别操纵案例相关的财务报表指标。"},related:{datasets:["cn-pit-fundamentals","cn-company-master"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.2469/faj.v55.n5.2296"}]},{id:"financial-ratios-discriminant-analysis-and-the-prediction-of-corporate-bankruptcy",title:"Financial Ratios, Discriminant Analysis and the Prediction of Corporate Bankruptcy",titleZh:"财务比率与企业破产判别分析",sourceTitle:"FINANCIAL RATIOS, DISCRIMINANT ANALYSIS AND THE PREDICTION OF CORPORATE BANKRUPTCY",authors:"Edward I. Altman",venue:"The Journal of Finance",year:"1968",kind:"paper",topic:"corporate-fundamentals",data:"balance sheets; income statements; bankruptcy outcomes",dataZh:"资产负债表；利润表；破产结果",summary:{en:"Illustrates multivariate financial-ratio analysis using bankruptcy outcomes.",zh:"以破产结果展示多变量财务比率分析。"},related:{datasets:["cn-pit-fundamentals","cn-company-master"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/j.1540-6261.1968.tb00843.x"}]},{id:"financial-ratios-and-the-probabilistic-prediction-of-bankruptcy",title:"Financial Ratios and the Probabilistic Prediction of Bankruptcy",titleZh:"财务比率与破产概率模型",sourceTitle:"Financial Ratios and the Probabilistic Prediction of Bankruptcy",authors:"James A. Ohlson",venue:"Journal of Accounting Research",year:"1980",kind:"paper",topic:"corporate-fundamentals",data:"financial ratios; firm size; distress labels; dates",dataZh:"财务比率；企业规模；困境标签；日期",summary:{en:"Uses probabilistic models to relate accounting information to distress outcomes.",zh:"用概率模型连接会计信息与财务困境结果。"},related:{datasets:["cn-pit-fundamentals","cn-company-master"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.2307/2490395"}]},{id:"in-search-of-distress-risk",title:"In Search of Distress Risk",titleZh:"寻找财务困境风险",sourceTitle:"In Search of Distress Risk",authors:"JOHN Y. CAMPBELL · JENS HILSCHER · JAN SZILAGYI",venue:"The Journal of Finance",year:"2008",kind:"paper",topic:"corporate-fundamentals",data:"market returns; leverage; cash; failure events",dataZh:"市场收益；杠杆；现金；失败事件",summary:{en:"Combines market and accounting information in the analysis of corporate failure.",zh:"在企业失败分析中结合市场与会计信息。"},related:{datasets:["cn-pit-fundamentals","cn-company-master"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/j.1540-6261.2008.01416.x"}],readingNotes:[{title:{zh:"先定义什么叫企业失败",en:"Define the outcome before the predictors"},body:{zh:"研究区分破产申请与更宽的企业失败标签；后者还纳入特定退市和信用评级降至D等事件。两种标签的覆盖时期也不同。因此，破产、违约和退市不能随意互换，更不能把所有退市都视作同一种财务失败。",en:"The study distinguishes bankruptcy filings from broader failure events, including specified delistings and a D credit rating. The labels also have different historical coverage. Bankruptcy, default and delisting are not interchangeable outcomes; in particular, every delisting must not automatically be treated as the same kind of financial failure."},reference:{url:"https://dash.harvard.edu/server/api/core/bitstreams/7312037c-5bf6-6bd4-e053-0100007fdf3b/content",label:{zh:"原文定位：2005年6月27日作者稿，第1, 4–5页",en:"Source: June 27, 2005 author draft, pp. 1, 4–5"}}},{title:{zh:"观察单位是公司与月份",en:"Think in firm-month observations"},body:{zh:"作者用动态面板逻辑模型研究失败概率，每家公司可以贡献多个按月排列的观察值。问题是已知当时信息时，在指定未来期限内是否发生失败，而不是给每家公司永久贴一个标签。样本退出、时间顺序及预测期限都是模型定义的一部分。",en:"A dynamic panel logit model organizes observations by firm and month. The question is whether failure occurs over a specified future horizon given information available then, not whether a company deserves a permanent label. Exits, observation order and forecast horizon therefore belong to the definition of the model."},reference:{url:"https://dash.harvard.edu/server/api/core/bitstreams/7312037c-5bf6-6bd4-e053-0100007fdf3b/content",label:{zh:"原文定位：2005年6月27日作者稿，第4–6页",en:"Source: June 27, 2005 author draft, pp. 4–6"}}},{title:{zh:"市场口径改变了财务比率",en:"The denominator changes the financial signal"},body:{zh:"作者稿比较以账面资产缩放的盈利和负债，与使用“权益市值加账面负债”缩放的版本。后者会随股价变化，并不是把账面资产简单改名。准备变量时应分别保存分子、分母和价格日期，避免把同名的杠杆或盈利指标混在一起。",en:"The draft compares profitability and leverage scaled by book assets with versions scaled by market equity plus book liabilities. The latter changes with equity prices; it is not book assets under another name. Keep numerators, denominators and price dates separately so similarly named leverage or profitability fields are not mixed."},reference:{url:"https://dash.harvard.edu/server/api/core/bitstreams/7312037c-5bf6-6bd4-e053-0100007fdf3b/content",label:{zh:"原文定位：2005年6月27日作者稿，第5–7页",en:"Source: June 27, 2005 author draft, pp. 5–7"}}},{title:{zh:"会计数据与市场数据有不同的时钟",en:"Accounting and market inputs run on different clocks"},body:{zh:"解释变量结合季度财务、月度收益和日度价格波动。此作者稿对会计数据施加两个月的时滞，同时使用过去市场信息构造收益和波动变量。拼接时要保留各自的可用日期；固定时滞本身不能证明一份延迟披露的报表当时已可获得。",en:"Predictors combine quarterly accounts, monthly returns and daily price variability. This draft lags accounting information by two months while constructing market measures from past observations. Preserve availability dates for each input: a fixed lag does not establish that a delayed financial filing was actually accessible at that time."},reference:{url:"https://dash.harvard.edu/server/api/core/bitstreams/7312037c-5bf6-6bd4-e053-0100007fdf3b/content",label:{zh:"原文定位：2005年6月27日作者稿，第6–7页",en:"Source: June 27, 2005 author draft, pp. 6–7"}}},{title:{zh:"近期风险与远期风险不是同一道题",en:"Near and distant horizons need separate evaluation"},body:{zh:"盈利、杠杆、超额收益、波动、规模和现金等特征共同进入比较，但它们对不同期限的失败预测可能有不同作用。检验应写清未来窗口、样本基准和预测信息集。一个期限下的拟合结果不能自动成为另一期限下经过校准的概率。",en:"Profitability, leverage, excess returns, volatility, size and cash enter the comparison, but their relevance can change with the failure horizon. Evaluation needs an explicit future window, baseline and information set. A fit at one horizon does not automatically yield calibrated probabilities at another."},reference:{url:"https://dash.harvard.edu/server/api/core/bitstreams/7312037c-5bf6-6bd4-e053-0100007fdf3b/content",label:{zh:"原文定位：2005年6月27日作者稿，第2–3, 7–8页",en:"Source: June 27, 2005 author draft, pp. 2–3, 7–8"}}},{title:{zh:"失败概率与股票回报需要分开解释",en:"Failure risk is not a promised return premium"},body:{zh:"论文进一步研究财务困境与股票收益的关系，但预测企业是否失败和解释股东收益是两个不同任务。企业困境更深，并不意味着股东必然获得更高补偿；历史关系也不能转化为个股交易结论。阅读时应把失败标签与收益样本分别核对。",en:"The paper also studies stock returns, but predicting company failure and explaining shareholder payoffs are separate tasks. Greater distress need not deliver a higher reward to equity holders. Historical associations do not establish an individual-stock trade; the failure outcome and the return sample must be examined independently."},reference:{url:"https://dash.harvard.edu/server/api/core/bitstreams/7312037c-5bf6-6bd4-e053-0100007fdf3b/content",label:{zh:"原文定位：2005年6月27日作者稿，第1–3页",en:"Source: June 27, 2005 author draft, pp. 1–3"}}}],readerLimits:{zh:"导读依据2005年作者稿，题录为2008年期刊版，最终设定需回到期刊原文。企业失败的标签、会计时滞与市场制度有样本依赖性，不能直接生成当前公司的违约概率。",en:"This guide uses the 2005 author draft, not the definitive specifications of the 2008 journal article. Failure labels, reporting lags and market institutions are sample-dependent; the guide does not generate current company default probabilities."}},{id:"the-dark-side-of-outside-directors-do-they-quit-when-they-are-most-needed",title:"The Dark Side of Outside Directors: Do They Quit When They Are Most Needed?",titleZh:"外部董事离任与公司事件",sourceTitle:"The dark side of outside directors: Do they quit when they are most needed?",authors:"Rüdiger Fahlenbrach · Angie Low · René Stulz",venue:"National Bureau of Economic Research",year:"2010",kind:"working-paper",topic:"corporate-fundamentals",data:"director histories; departures; company events; filing times",dataZh:"董事任职历史；离任；公司事件；披露时点",summary:{en:"Examines director departures around periods of heightened firm risk.",zh:"研究企业风险上升前后的董事离任事件。"},related:{datasets:["cn-pit-fundamentals","cn-company-master"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.3386/w15917"}]},{id:"corporate-governance-and-equity-prices",title:"Corporate Governance and Equity Prices",titleZh:"公司治理与股票价格",sourceTitle:"Corporate Governance and Equity Prices",authors:"P. Gompers · J. Ishii · A. Metrick",venue:"The Quarterly Journal of Economics",year:"2003",kind:"paper",topic:"corporate-fundamentals",data:"governance provisions; firm valuation; returns; ownership",dataZh:"治理条款；企业估值；收益；所有权",summary:{en:"Links shareholder-rights measures with corporate characteristics and valuation.",zh:"将股东权利度量与企业特征和估值联系起来。"},related:{datasets:["cn-pit-fundamentals","cn-company-master"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.1162/00335530360535162"}],readingNotes:[{title:{zh:"分数越高，股东权利越弱",en:"Check the direction before reading the score"},body:{zh:"论文汇总24项治理条款，形成衡量股东权利的指数。数值较高代表对股东权利的限制更多，而不是“治理更好”。这也不是环境、社会与治理的综合评分。解释任何分组或图表之前，先确认计分方向及条款到底衡量谁的权利。",en:"The index combines 24 governance provisions: a higher score indicates weaker shareholder rights, not better governance. It is also not a combined environmental, social and governance rating. Before interpreting a group comparison or chart, establish the coding direction and whose rights the underlying provisions describe."},reference:{url:"https://www.nber.org/papers/w8449.pdf",label:{zh:"原文定位：2001年8月NBER工作论文，第1–3, 7–8页",en:"Source: August 2001 NBER working paper, pp. 1–3, 7–8"}}},{title:{zh:"覆盖范围决定结论的边界",en:"Coverage defines the comparison"},body:{zh:"工作论文使用约1500家大型公司的治理资料，研究时期为1990至1999年，并排除双重股权结构公司。资料覆盖在后期发生扩展。因此样本不是所有上市公司的固定全集，跨期比较需要区分治理变化与被纳入资料库的公司变化。",en:"The working paper uses governance information for roughly 1,500 large companies over 1990–1999 and excludes dual-class firms. Coverage expands later in the period. This is not a fixed census of all listed companies; a time comparison must distinguish changing provisions from changes in which firms enter the source database."},reference:{url:"https://www.nber.org/papers/w8449.pdf",label:{zh:"原文定位：2001年8月NBER工作论文，第2, 7–8页",en:"Source: August 2001 NBER working paper, pp. 2, 7–8"}}},{title:{zh:"条款来自文件，不来自行情",en:"Governance coding starts with documents"},body:{zh:"资料来源包括公司章程、内部细则、代理投票材料及年度或季度文件。将条款编码为指数，需要保留原始文件、规则解释和观察日期。价格、财务比率或公司名称本身不能证明某项反收购安排存在，也不能替代具体条款的核对。",en:"The source material includes charters, bylaws, proxy documents and annual or quarterly filings. Coding provisions requires their documentary basis, interpretation and observation date. Prices, financial ratios or company names cannot establish the existence of a particular takeover defense or replace inspection of the relevant provision."},reference:{url:"https://www.nber.org/papers/w8449.pdf",label:{zh:"原文定位：2001年8月NBER工作论文，第7–8页",en:"Source: August 2001 NBER working paper, pp. 7–8"}}},{title:{zh:"资料版本不是实时状态",en:"A publication vintage is not a live state"},body:{zh:"治理资料来自1990、1993、1995和1998年的多个版本，并非每次都会更新所有公司的全部条款。相邻版本数值相同，不足以证明期间没有变化。与行情连接时还要校验公司标识和样本匹配，不能把最新一版指数直接回填到过去。",en:"Governance observations come from the 1990, 1993, 1995 and 1998 publications, without a complete refresh of every company at each edition. An unchanged value does not prove that nothing changed between observations. Matching market data requires validated firm identities and dated vintages, not backfilling history with the latest index."},reference:{url:"https://www.nber.org/papers/w8449.pdf",label:{zh:"原文定位：2001年8月NBER工作论文，第7–8页",en:"Source: August 2001 NBER working paper, pp. 7–8"}}},{title:{zh:"多个经营结果提供不同线索",en:"Outcomes ask different economic questions"},body:{zh:"论文把治理指数与公司估值、盈利、销售增长、资本支出和收购活动联系起来。这些结果变量不是同一概念：估值包含市场预期，投入可能反映扩张，盈利则受会计口径影响。理解论证需要分别看它们，不能把所有关系压缩成单一“优质公司”标签。",en:"The paper relates the index to valuation, profitability, sales growth, capital spending and acquisitions. These outcomes are not equivalent: valuation incorporates expectations, spending may reflect expansion and earnings depend on accounting conventions. Read their separate roles rather than compressing every association into a single label of company quality."},reference:{url:"https://www.nber.org/papers/w8449.pdf",label:{zh:"原文定位：2001年8月NBER工作论文，第3–5页",en:"Source: August 2001 NBER working paper, pp. 3–5"}}},{title:{zh:"相关性留下了因果问题",en:"Association leaves causality unresolved"},body:{zh:"作者明确不把这些关系当作因果方向已经确定的证明。治理条款可能影响经营，也可能在公司预期表现恶化时被采用，或者只是其他问题的伴随特征。若想评价一次治理改革，需要额外识别设计，而不是把历史组间差异直接解释为改革收益。",en:"The authors explicitly refrain from claiming a settled direction of causality. Provisions might affect operations, be adopted in anticipation of poor performance or indicate other underlying problems. Evaluating a governance reform requires an additional identification design; a historical difference between groups is not itself the return to implementing that reform."},reference:{url:"https://www.nber.org/papers/w8449.pdf",label:{zh:"原文定位：2001年8月NBER工作论文，第4–6页",en:"Source: August 2001 NBER working paper, pp. 4–6"}}}],readerLimits:{zh:"导读依据2001年工作论文，题录保留2003年期刊版。历史美国治理条款不能直接视为当前法律或跨市场治理标准；相关关系不等于治理改革的因果效果。",en:"This guide uses the 2001 working paper while retaining the 2003 journal citation. Historical US provisions are not current law or a cross-market governance standard; associations do not identify the causal effect of governance reform."}},{id:"investor-protection-and-corporate-governance",title:"Investor Protection and Corporate Governance",titleZh:"投资者保护与公司治理",sourceTitle:"Investor protection and corporate governance",authors:"Rafael La Porta · Florencio Lopez-de-Silanes · Andrei Shleifer · Robert Vishny",venue:"Journal of Financial Economics",year:"2000",kind:"paper",topic:"corporate-fundamentals",data:"legal rules; ownership structures; country classifications",dataZh:"法律规则；所有权结构；国家分类",summary:{en:"Compares legal protection and governance arrangements across countries.",zh:"比较各国法律保护与治理安排。"},related:{datasets:["cn-pit-fundamentals","cn-company-master"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/s0304-405x(00)00065-9"}]},{id:"law-and-finance",title:"Law and Finance",titleZh:"法律与金融",sourceTitle:"Law and Finance",authors:"Rafael La Porta · Florencio Lopez‐de‐Silanes · Andrei Shleifer · Robert W. Vishny",venue:"Journal of Political Economy",year:"1998",kind:"paper",topic:"corporate-fundamentals",data:"legal origin; investor rights; financial development indicators",dataZh:"法律起源；投资者权利；金融发展指标",summary:{en:"Studies relationships between legal institutions and financial development.",zh:"研究法律制度与金融发展之间的关系。"},related:{datasets:["cn-pit-fundamentals","cn-company-master"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.1086/250042"}]},{id:"corporate-ownership-around-the-world",title:"Corporate Ownership Around the World",titleZh:"全球公司所有权结构",sourceTitle:"Corporate Ownership Around the World",authors:"Rafael La Porta · Florencio Lopez‐De‐Silanes · Andrei Shleifer",venue:"The Journal of Finance",year:"1999",kind:"paper",topic:"corporate-fundamentals",data:"ultimate owners; control chains; voting rights",dataZh:"最终所有者；控制链；投票权",summary:{en:"Maps ownership and control across firms in different legal environments.",zh:"描绘不同法律环境下企业的所有权和控制权。"},related:{datasets:["cn-pit-fundamentals","cn-company-master"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/0022-1082.00115"}]},{id:"the-separation-of-ownership-and-control-in-east-asian-corporations",title:"The Separation of Ownership and Control in East Asian Corporations",titleZh:"东亚企业所有权与控制权的分离",sourceTitle:"The separation of ownership and control in East Asian Corporations",authors:"Stijn Claessens · Simeon Djankov · Larry H.P Lang",venue:"Journal of Financial Economics",year:"2000",kind:"paper",topic:"corporate-fundamentals",data:"ownership chains; share classes; voting and cash-flow rights",dataZh:"股权链；股份类别；投票权与现金流权",summary:{en:"Examines pyramids, cross-holdings, and control rights in East Asian firms.",zh:"考察东亚企业中的金字塔、交叉持股和控制权。"},related:{datasets:["cn-pit-fundamentals","cn-company-master"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/s0304-405x(00)00067-2"}]},{id:"agency-costs-of-free-cash-flow-corporate-finance-and-takeovers",title:"Agency Costs of Free Cash Flow, Corporate Finance, and Takeovers",titleZh:"自由现金流的代理成本",sourceTitle:"Agency Costs of Free Cash Flow, Corporate Finance, and Takeovers",authors:"Michael C. Jensen",venue:"The American Economic Review",year:"1986",kind:"paper",topic:"corporate-fundamentals",data:"cash flows; investment; payout; acquisition records",dataZh:"现金流；投资；分配；收购记录",summary:{en:"Frames conflicts over corporate cash deployment and control transactions.",zh:"讨论企业现金使用与控制权交易中的利益冲突。"},related:{datasets:["cn-pit-fundamentals","cn-company-master"],recipes:["pit-fundamentals-panel"]},sources:[{label:"The American Economic Review",url:"https://www.jstor.org/stable/1818789"}]},{id:"the-capital-structure-puzzle",title:"The Capital Structure Puzzle",titleZh:"资本结构之谜",sourceTitle:"The Capital Structure Puzzle",authors:"Stewart C. Myers",venue:"The Journal of Finance",year:"1984",kind:"paper",topic:"corporate-fundamentals",data:"debt; equity issuance; profitability; financing events",dataZh:"债务；股权发行；盈利能力；融资事件",summary:{en:"Compares explanations for corporate debt and equity financing choices.",zh:"比较企业债务与股权融资选择的不同解释。"},related:{datasets:["cn-pit-fundamentals","cn-company-master"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.2307/2327916"}]},{id:"corporate-financing-and-investment-decisions-when-firms-have-information-that-investors-do-not-have",title:"Corporate Financing and Investment Decisions When Firms Have Information That Investors Do Not Have",titleZh:"信息不对称下的融资与投资决策",sourceTitle:"Corporate financing and investment decisions when firms have information that investors do not have",authors:"Stewart C. Myers · Nicholas S. Majluf",venue:"Journal of Financial Economics",year:"1984",kind:"paper",topic:"corporate-fundamentals",data:"financing events; investment; information environment",dataZh:"融资事件；投资；信息环境",summary:{en:"Studies how asymmetric information can shape financing and investment decisions.",zh:"研究信息不对称如何影响融资和投资决策。"},related:{datasets:["cn-pit-fundamentals","cn-company-master"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/0304-405x(84)90023-0"}]},{id:"toward-an-implied-cost-of-capital",title:"Toward an Implied Cost of Capital",titleZh:"走向隐含资本成本估计",sourceTitle:"Toward an Implied Cost of Capital",authors:"William R. Gebhardt · Charles M. C. Lee · Bhaskaran Swaminathan",venue:"Journal of Accounting Research",year:"2001",kind:"paper",topic:"corporate-fundamentals",data:"analyst forecasts; book equity; prices; valuation inputs",dataZh:"分析师预测；账面权益；价格；估值输入",summary:{en:"Examines assumptions used to infer required returns from accounting forecasts.",zh:"考察利用会计预测推断必要收益时的假设。"},related:{datasets:["cn-pit-fundamentals","cn-company-master"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/1475-679x.00007"}]},{id:"pe-ratios-peg-ratios-and-estimating-the-implied-expected-rate-of-return-on-equity-capital",title:"PE Ratios, PEG Ratios, and Estimating the Implied Expected Rate of Return on Equity Capital",titleZh:"市盈率、PEG与隐含股权回报率估计",sourceTitle:"PE Ratios, PEG Ratios, and Estimating the Implied Expected Rate of Return on Equity Capital",authors:"Peter D. Easton",venue:"The Accounting Review",year:"2004",kind:"paper",topic:"corporate-fundamentals",data:"forecast earnings; prices; growth assumptions; fiscal dates",dataZh:"盈利预测；价格；增长假设；会计日期",summary:{en:"Studies how earnings forecasts and growth assumptions enter implied capital costs.",zh:"研究盈利预测与增长假设如何进入隐含资本成本。"},related:{datasets:["cn-pit-fundamentals","cn-company-master"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.2308/accr.2004.79.1.73"}]},{id:"information-asymmetry-corporate-disclosure-and-the-capital-markets-a-review-of-the-empirical-disclosure-literature",title:"Information Asymmetry, Corporate Disclosure, and the Capital Markets: A Review of the Empirical Disclosure Literature",titleZh:"信息不对称、公司披露与资本市场",sourceTitle:"Information asymmetry, corporate disclosure, and the capital markets: A review of the empirical disclosure literature",authors:"Paul M Healy · Krishna G Palepu",venue:"Journal of Accounting and Economics",year:"2001",kind:"paper",topic:"corporate-fundamentals",data:"disclosures; analyst coverage; ownership; market measures",dataZh:"披露；分析师覆盖；所有权；市场度量",summary:{en:"Reviews evidence on disclosure decisions, information asymmetry, and market outcomes.",zh:"综述披露决策、信息不对称与市场结果的证据。"},related:{datasets:["cn-pit-fundamentals","cn-company-master"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/s0165-4101(01)00018-0"}]},{id:"disclosure-liquidity-and-the-cost-of-capital",title:"Disclosure, Liquidity, and the Cost of Capital",titleZh:"披露、流动性与资本成本",sourceTitle:"Disclosure, Liquidity, and the Cost of Capital",authors:"DOUGLAS W. DIAMOND · ROBERT E. VERRECCHIA",venue:"The Journal of Finance",year:"1991",kind:"paper",topic:"corporate-fundamentals",data:"disclosure timing; investor information; liquidity measures",dataZh:"披露时点；投资者信息；流动性度量",summary:{en:"Models connections among public disclosure, market liquidity, and financing costs.",zh:"建模分析公开披露、市场流动性与融资成本的联系。"},related:{datasets:["cn-pit-fundamentals","cn-company-master"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/j.1540-6261.1991.tb04620.x"}]},{id:"international-differences-in-the-cost-of-equity-capital-do-legal-institutions-and-securities-regulation-matter",title:"International Differences in the Cost of Equity Capital: Do Legal Institutions and Securities Regulation Matter?",titleZh:"股权资本成本的国际差异",sourceTitle:"International Differences in the Cost of Equity Capital: Do Legal Institutions and Securities Regulation Matter?",authors:"LUZI HAIL · CHRISTIAN LEUZ",venue:"Journal of Accounting Research",year:"2006",kind:"paper",topic:"corporate-fundamentals",data:"analyst forecasts; prices; country institutions; regulation",dataZh:"分析师预测；价格；国家制度；监管",summary:{en:"Examines cross-country capital-cost differences alongside institutions and regulation.",zh:"结合制度与监管研究跨国资本成本差异。"},related:{datasets:["cn-pit-fundamentals","cn-company-master"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/j.1475-679x.2006.00209.x"}]},{id:"the-cost-of-capital-corporation-finance-and-the-theory-of-investment",title:"The Cost of Capital, Corporation Finance and the Theory of Investment",titleZh:"资本成本、公司金融与投资理论",sourceTitle:"The Cost of Capital, Corporation Finance and the Theory of Investment",authors:"Franco Modigliani · Merton H. Miller",venue:"The American Economic Review",year:"1958",kind:"paper",topic:"corporate-fundamentals",data:"capital structure; cash-flow claims; financing assumptions",dataZh:"资本结构；现金流权利；融资假设",summary:{en:"Provides a benchmark for analyzing financing structure under restrictive assumptions.",zh:"在限定假设下提供分析融资结构的理论基准。"},related:{datasets:["cn-pit-fundamentals","cn-company-master"],recipes:["pit-fundamentals-panel"]},sources:[{label:"The American Economic Review",url:"https://www.jstor.org/stable/1809766"}]},{id:"more-than-words-quantifying-language-to-measure-firms-fundamentals",title:"More Than Words: Quantifying Language to Measure Firms' Fundamentals",titleZh:"不止文字：量化语言与企业基本面",sourceTitle:"More Than Words: Quantifying Language to Measure Firms' Fundamentals",authors:"PAUL C. TETLOCK · MAYTAL SAAR‐TSECHANSKY · SOFUS MACSKASSY",venue:"The Journal of Finance",year:"2008",kind:"paper",topic:"alternative-data",data:"news text; firm mapping; publication time; accounting data",dataZh:"新闻文本；企业映射；发布时间；会计数据",summary:{en:"Uses financial-news language to examine information about company fundamentals.",zh:"利用财经新闻语言研究企业基本面信息。"},related:{datasets:["cn-news-flashes","cn-announcements"],recipes:["company-event-timeline"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/j.1540-6261.2008.01362.x"}]},{id:"when-is-a-liability-not-a-liability-textual-analysis-dictionaries-and-10-ks",title:"When Is a Liability Not a Liability? Textual Analysis, Dictionaries, and 10-Ks",titleZh:"金融文本分析、词典与10-K报告",sourceTitle:"When Is a Liability Not a Liability? Textual Analysis, Dictionaries, and 10‐Ks",authors:"TIM LOUGHRAN · BILL MCDONALD",venue:"The Journal of Finance",year:"2011",kind:"paper",topic:"alternative-data",data:"10-K documents; tokenization; financial dictionaries",dataZh:"10-K文件；分词；金融词典",summary:{en:"Shows why domain-specific language matters when measuring sentiment in filings.",zh:"说明衡量披露文本情绪时为何需要领域专用词典。"},related:{datasets:["cn-news-flashes","cn-announcements"],recipes:["company-event-timeline"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/j.1540-6261.2010.01625.x"}],readingNotes:[{title:{zh:"负面词不一定是负面消息",en:"A negative word is not always bad news"},body:{zh:"Loughran与McDonald指出，通用词典中的负面词在财务文件里可能只是术语。例如负债、税或成本经常是在描述会计项目。研究问题是词典是否测到了财务语气，还是不经意测到了行业与文件写法。",en:"Loughran and McDonald question whether general-purpose negative-word lists measure financial tone. Terms for liabilities, taxes or costs may simply describe accounting items. A dictionary can inadvertently capture industry or document conventions instead of adverse information."}},{title:{zh:"样本经过多层筛选",en:"The sample is filtered"},body:{zh:"原文使用1994—2008年的EDGAR年度10-K及10-K405文件，排除修订文件，并连接CRSP与Compustat。满足标识、价格、收益、财务信息和文本长度等条件后，留下50,115个公司年度、8,341家公司。管理层讨论部分另有识别与长度筛选，不能把子样本直接当成全样本。",en:"The study uses 1994–2008 EDGAR 10-K/10-K405 filings, excluding amendments, matched to CRSP and Compustat. Identity, price, returns, accounting and document-length requirements leave 50,115 firm-years from 8,341 firms. MD&A analyses apply additional extraction and length filters."},reference:{url:"https://www.uts.edu.au/globalassets/sites/default/files/adg_cons2015_loughran-mcdonald-je-2011.pdf",label:{zh:"原文第II.A节：10-K样本",en:"Original §II.A: the 10-K sample"}}},{title:{zh:"先解析，再计数",en:"Parsing comes before counting"},body:{zh:"作者采用词袋表示，但计数前先排除表格与附件，减少模板语言的干扰。文中还比较词频比例与词项加权，避免高频词压过真正有信息的词。因而“全文分析”在这里不是把下载文件每个字符直接分词：解析范围本身就是方法的一部分。",en:"The bag-of-words pipeline excludes tables and exhibits to reduce boilerplate contamination. Proportional counts are compared with term weighting, which reduces domination by frequent words. Here, full-document analysis has a defined parsing boundary; it is not indiscriminate tokenization of every downloaded character."},reference:{url:"https://www.uts.edu.au/globalassets/sites/default/files/adg_cons2015_loughran-mcdonald-je-2011.pdf",label:{zh:"原文第II.B与II.E节：解析与加权",en:"Original §§II.B and II.E: parsing and weighting"}}},{title:{zh:"发现不是一条交易信号",en:"The finding is not a trading signal"},body:{zh:"作者发现通用词典存在显著语境误分类，财务负面词表及加权方案能改变与文件披露反应的关系。但引言也明确指出，比较的语气指标没有显示出其检验中的未来收益可预测性。能描述同期市场反应，不等于能提前获利。",en:"The authors report substantial contextual misclassification and show that financial dictionaries and term weighting change relations with filing reactions. They also report no future-return predictability from the competing tone measures in their tests. Describing an announcement response is not the same as forecasting profits."}},{title:{zh:"读方法时追踪事件窗口",en:"Track the event window"},body:{zh:"第II.D节把披露反应定义为提交日及随后三日的持有期超额收益，并说明基准与控制变量。建议把文本范围、词表版本、分母和事件时间一起记录：即使词典相同，换成新闻标题、中文公告或另一种事件窗口，也不是同一项测量。",en:"Section II.D defines a filing-date response over days 0–3 and specifies the benchmark and controls. Track text boundaries, dictionary version, denominator and event timing together. The same dictionary applied to headlines, Chinese announcements or another window defines a different measurement."}},{title:{zh:"中文材料需要另行验证",en:"Chinese documents need separate validation"},body:{zh:"编辑建议：中文文本的分词、否定、歧义与财务术语要在人工标注样本上验证，不能逐词翻译英语词典后宣称等效。保留文件哈希与修订关系，才能区分语气变化、解析器变化和重复转载；不要把数据清理差异解释成公司行为变化。",en:"Editorial application: validate Chinese segmentation, negation and domain terms against labeled material; translating an English dictionary does not establish equivalence. Preserve document hashes and revisions to distinguish tone changes from parser changes or syndicated copies."}}],readerLimits:{zh:"词典是有版本、有语境的测量工具，不是对事实真伪或投资价值的自动判断。",en:"A dictionary is a versioned, context-dependent measurement tool, not an automatic judgment of truth or investment value."}},{id:"textual-analysis-in-accounting-and-finance-a-survey",title:"Textual Analysis in Accounting and Finance: A Survey",titleZh:"会计与金融文本分析综述",sourceTitle:"Textual Analysis in Accounting and Finance: A Survey",authors:"TIM LOUGHRAN · BILL MCDONALD",venue:"Journal of Accounting Research",year:"2016",kind:"paper",topic:"alternative-data",data:"documents; text features; labels; publication metadata",dataZh:"文档；文本特征；标签；发布元数据",summary:{en:"Reviews textual measurement choices and validation challenges in financial research.",zh:"综述金融研究中的文本度量选择与验证难点。"},related:{datasets:["cn-news-flashes","cn-announcements"],recipes:["company-event-timeline"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/1475-679x.12123"}]},{id:"text-as-data",title:"Text as Data",titleZh:"文本作为数据",sourceTitle:"Text as Data",authors:"Matthew Gentzkow · Bryan Kelly · Matt Taddy",venue:"Journal of Economic Literature",year:"2019",kind:"paper",topic:"alternative-data",data:"document corpus; preprocessing rules; labels; validation",dataZh:"文档语料；预处理规则；标签；验证",summary:{en:"Explains how text is transformed into measurable variables and statistical evidence.",zh:"解释如何将文本转化为可测量变量与统计证据。"},related:{datasets:["cn-news-flashes","cn-announcements"],recipes:["company-event-timeline"]},sources:[{label:"DOI",url:"https://doi.org/10.1257/jel.20181020"}]},{id:"measuring-economic-policy-uncertainty",title:"Measuring Economic Policy Uncertainty",titleZh:"衡量经济政策不确定性",sourceTitle:"Measuring Economic Policy Uncertainty*",authors:"Scott R. Baker · Nicholas Bloom · Steven J. Davis",venue:"The Quarterly Journal of Economics",year:"2016",kind:"paper",topic:"macro-finance",data:"newspaper corpus; search rules; normalization; dates",dataZh:"报纸语料；检索规则；标准化；日期",summary:{en:"Constructs policy-uncertainty measures from news and other documentary inputs.",zh:"利用新闻及其他文档材料构建政策不确定性度量。"},related:{datasets:["cn-macro-calendar","cn-yield-curve","global-macro-indicators"]},sources:[{label:"DOI",url:"https://doi.org/10.1093/qje/qjw024"}],readingNotes:[{title:{zh:"测量的是政策相关的不确定性",en:"The target is policy-related uncertainty"},body:{zh:"作者希望捕捉谁制定政策、何时采取何种政策以及其经济影响等不确定性，也包含长期财政问题。它不是把所有政治报道加总，更不是一般经济波动的同义词。论文正式版聚焦报纸文本，早期草稿中的其他成分不能不加区别地混入。",en:"The target includes uncertainty about policymakers, policy actions, timing and economic consequences, including long-horizon fiscal questions. It is not a count of all political reporting or a synonym for economic volatility. The final article focuses on newspapers; components from earlier drafts should not be silently mixed into that definition."},reference:{url:"https://users.ssc.wisc.edu/~mchinn/bakerbloomdavis_QJE2016.pdf",label:{zh:"原文定位：2016年期刊版，第1598页",en:"Source: 2016 journal article, pp. 1598"}}},{title:{zh:"同一篇报道必须满足三类词",en:"An article must meet three term categories"},body:{zh:"美国月度指数在十家报纸中寻找同时包含不确定性、经济和政策三类词的文章，政策词包括国会、赤字、联储等及其变体。只出现政策关键词并不足够。跨语言扩展也需要重新设计词表与语境判断，不能把英文关键词逐字翻译就当作同一测量。",en:"The US monthly index searches ten newspapers for articles containing uncertainty, economy and policy terms together, including policy terms such as Congress, deficit and the Federal Reserve. A policy mention alone is insufficient. A new language requires reconsidering vocabulary and context rather than assuming literal translation preserves the measure."},reference:{url:"https://users.ssc.wisc.edu/~mchinn/bakerbloomdavis_QJE2016.pdf",label:{zh:"原文定位：2016年期刊版，第1599页",en:"Source: 2016 journal article, pp. 1599"}}},{title:{zh:"先除以报道总量，再合成指数",en:"Normalize newspaper counts before combining them"},body:{zh:"原始命中数先除以同一报纸同月全部文章数，再将各报纸序列按1985至2009年标准差缩放，按月平均后把基期均值设为100。100是尺度约定，不是100%的概率。新闻总量增加本身不应自动被解读为政策不确定性同比例上升。",en:"Matches are divided by each newspaper's total monthly article count, scaled using its 1985–2009 standard deviation, averaged across papers and normalized to a baseline mean of 100. That 100 is a scale convention, not a probability. More news volume alone should not imply proportionately greater uncertainty."},reference:{url:"https://users.ssc.wisc.edu/~mchinn/bakerbloomdavis_QJE2016.pdf",label:{zh:"原文定位：2016年期刊版，第1599页",en:"Source: 2016 journal article, pp. 1599"}}},{title:{zh:"日度版不是月度版的简单拆分",en:"The daily series uses a different archive"},body:{zh:"日度指数使用Newsbank更广泛的报纸集合，而不是把十家报纸的月度值拆到每天。报纸会进入或离开资料库，覆盖变化可能影响长期走势。因此频率转换之外，还要保留资料库构成与版本；两个指数相关性高也不表示定义完全相同。",en:"The daily index draws on a broader Newsbank archive rather than splitting the ten-paper monthly value into days. Papers enter and leave that archive, potentially affecting longer-run behavior. Archive composition and vintages matter alongside frequency conversion; high correlation does not make the two constructions identical."},reference:{url:"https://users.ssc.wisc.edu/~mchinn/bakerbloomdavis_QJE2016.pdf",label:{zh:"原文定位：2016年期刊版，第1600页",en:"Source: 2016 journal article, pp. 1600"}}},{title:{zh:"跨国与长历史需要调整词表",en:"Country and historical coverage need different choices"},body:{zh:"长历史指数扩展了经济和政策相关词汇，以适应早期报纸用语；不同国家的报纸覆盖也并不一致。单报纸来源可能更嘈杂，媒体环境还会影响什么被报道。比较指数水平之前，应先检查当地来源、词表和基期，而不是只把曲线放在一起。",en:"Long-span indexes expand economic and policy vocabulary to reflect earlier usage, while country indexes differ in newspaper coverage. A single-paper source can be noisier, and media conditions affect what is reported. Check local sources, term sets and baselines before comparing index levels on a shared chart."},reference:{url:"https://users.ssc.wisc.edu/~mchinn/bakerbloomdavis_QJE2016.pdf",label:{zh:"原文定位：2016年期刊版，第1605–1606页",en:"Source: 2016 journal article, pp. 1605–1606"}}},{title:{zh:"政治事件不一定形成指数峰值",en:"Political turbulence need not produce an EPU spike"},body:{zh:"论文指出一些政府停摆虽获大量报道，却很少同时出现经济与不确定性用语，因此未必带来明显峰值。这不是自动证明指数错误，而是提醒读者理解它的筛选目标。它衡量特定报道中的关注，不是给每次事件评定严重程度或因果影响。",en:"Some government shutdowns received extensive coverage without many articles simultaneously mentioning the economy and uncertainty. A missing spike is therefore not automatically a measurement failure. The index tracks a defined type of coverage, not the severity or causal economic impact of every political event."},reference:{url:"https://users.ssc.wisc.edu/~mchinn/bakerbloomdavis_QJE2016.pdf",label:{zh:"原文定位：2016年期刊版，第1598–1600页",en:"Source: 2016 journal article, pp. 1598–1600"}}}],readerLimits:{zh:"EPU是新闻覆盖频率构成的代理指标，不是政策发生概率或市场涨跌预测。报纸构成、关键词与标准化区间不同，会影响跨国和跨时期比较。",en:"EPU is a newspaper-frequency proxy, not a policy-event probability or market-direction forecast. Newspaper coverage, keyword sets and normalization windows affect comparisons across countries and periods."}},{id:"measuring-geopolitical-risk",title:"Measuring Geopolitical Risk",titleZh:"衡量地缘政治风险",sourceTitle:"Measuring Geopolitical Risk",authors:"Dario Caldara · Matteo Iacoviello",venue:"International Finance Discussion Papers",year:"2022",kind:"paper",topic:"macro-finance",data:"news archives; dictionaries; event chronology",dataZh:"新闻档案；词典；事件时间线",summary:{en:"Builds text-based measures of geopolitical threats and realized events.",zh:"构建基于文本的地缘政治威胁与已发生事件度量。"},related:{datasets:["cn-macro-calendar","cn-yield-curve","global-macro-indicators"]},sources:[{label:"DOI",url:"https://doi.org/10.17016/ifdp.2018.1222r1"}]},{id:"the-price-of-political-uncertainty-theory-and-evidence-from-the-option-market",title:"The Price of Political Uncertainty: Theory and Evidence from the Option Market",titleZh:"政治不确定性的价格与期权市场证据",sourceTitle:"The Price of Political Uncertainty: Theory and Evidence from the Option Market",authors:"BRYAN KELLY · ĽUBOŠ PÁSTOR · PIETRO VERONESI",venue:"The Journal of Finance",year:"2016",kind:"paper",topic:"alternative-data",data:"options; election dates; implied volatility; countries",dataZh:"期权；选举日期；隐含波动率；国家",summary:{en:"Uses election-related option observations to study uncertainty around political events.",zh:"利用选举相关期权观测研究政治事件前后的不确定性。"},related:{datasets:["cn-news-flashes","cn-announcements"],recipes:["company-event-timeline"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/jofi.12406"}]},{id:"in-search-of-attention",title:"In Search of Attention",titleZh:"寻找投资者关注",sourceTitle:"In Search of Attention",authors:"ZHI DA · JOSEPH ENGELBERG · PENGJIE GAO",venue:"The Journal of Finance",year:"2011",kind:"paper",topic:"alternative-data",data:"search intensity; ticker mapping; dates; returns",dataZh:"搜索强度；代码映射；日期；收益",summary:{en:"Uses search activity as a proxy for investor attention with careful entity matching.",zh:"在谨慎实体匹配的前提下，以搜索活动代理投资者关注。"},related:{datasets:["cn-news-flashes","cn-announcements"],recipes:["company-event-timeline"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/j.1540-6261.2011.01679.x"}]},{id:"the-sum-of-all-fears-investor-sentiment-and-asset-prices",title:"The Sum of All FEARS Investor Sentiment and Asset Prices",titleZh:"搜索行为、投资者情绪与资产价格",sourceTitle:"The Sum of All FEARS Investor Sentiment and Asset Prices",authors:"Zhi Da · Joseph Engelberg · Pengjie Gao",venue:"Review of Financial Studies",year:"2015",kind:"paper",topic:"alternative-data",data:"search-term series; aggregation rules; returns; volumes",dataZh:"搜索词序列；汇总规则；收益；成交量",summary:{en:"Aggregates search terms to study investor sentiment and market activity.",zh:"汇总搜索词以研究投资者情绪与市场活动。"},related:{datasets:["cn-news-flashes","cn-announcements"],recipes:["company-event-timeline"]},sources:[{label:"DOI",url:"https://doi.org/10.1093/rfs/hhu072"}]},{id:"all-that-glitters-the-effect-of-attention-and-news-on-the-buying-behavior-of-individual-and-institutional-investors",title:"All That Glitters: The Effect of Attention and News on the Buying Behavior of Individual and Institutional Investors",titleZh:"关注与新闻对投资者买入行为的影响",sourceTitle:"All That Glitters: The Effect of Attention and News on the Buying Behavior of Individual and Institutional Investors",authors:"Brad M. Barber · Terrance Odean",venue:"Review of Financial Studies",year:"2008",kind:"paper",topic:"alternative-data",data:"investor-type trades; news; volume; extreme returns",dataZh:"投资者类型成交；新闻；成交量；极端收益",summary:{en:"Compares investor buying behavior around attention-grabbing securities.",zh:"比较不同投资者在高关注证券上的买入行为。"},related:{datasets:["cn-news-flashes","cn-announcements"],recipes:["company-event-timeline"]},sources:[{label:"DOI",url:"https://doi.org/10.1093/rfs/hhm079"}]},{id:"peer-pressure-social-interaction-and-the-disposition-effect",title:"Peer Pressure: Social Interaction and the Disposition Effect",titleZh:"同伴压力、社会互动与处置效应",sourceTitle:"Peer Pressure: Social Interaction and the Disposition Effect",authors:"Rawley Z. Heimer",venue:"Review of Financial Studies",year:"2016",kind:"paper",topic:"alternative-data",data:"social links; timestamped messages; account trades",dataZh:"社交关系；带时间戳消息；账户成交",summary:{en:"Studies social interaction and the disposition effect using investor-network and trading observations.",zh:"利用投资者网络与交易观测研究社会互动和处置效应。"},related:{datasets:["cn-news-flashes","cn-announcements"],recipes:["company-event-timeline"]},sources:[{label:"DOI",url:"https://doi.org/10.1093/rfs/hhw063"}]},{id:"wisdom-of-crowds-the-value-of-stock-opinions-transmitted-through-social-media",title:"Wisdom of Crowds: The Value of Stock Opinions Transmitted Through Social Media",titleZh:"社交媒体股票观点与群体信息",sourceTitle:"Wisdom of Crowds: The Value of Stock Opinions Transmitted Through Social Media",authors:"Hailiang Chen · Prabuddha De · Yu (Jeffrey) Hu · Byoung-Hyoun Hwang",venue:"Review of Financial Studies",year:"2014",kind:"paper",topic:"alternative-data",data:"authored posts; comment text; timestamps; earnings",dataZh:"署名帖子；评论文本；时间戳；盈利",summary:{en:"Examines stock-related opinions and subsequent information in a social-media setting.",zh:"研究社交媒体股票观点与后续信息之间的联系。"},related:{datasets:["cn-news-flashes","cn-announcements"],recipes:["company-event-timeline"]},sources:[{label:"DOI",url:"https://doi.org/10.1093/rfs/hhu001"}]},{id:"investor-sentiment-and-the-cross-section-of-stock-returns",title:"Investor Sentiment and the Cross-Section of Stock Returns",titleZh:"投资者情绪与股票收益横截面",sourceTitle:"Investor Sentiment and the Cross‐Section of Stock Returns",authors:"MALCOLM BAKER · JEFFREY WURGLER",venue:"The Journal of Finance",year:"2006",kind:"paper",topic:"alternative-data",data:"sentiment proxies; firm characteristics; returns",dataZh:"情绪代理；企业特征；收益",summary:{en:"Examines how sentiment measures relate to different types of companies.",zh:"考察情绪度量与不同类型企业之间的关系。"},related:{datasets:["cn-news-flashes","cn-announcements"],recipes:["company-event-timeline"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/j.1540-6261.2006.00885.x"}],readingNotes:[{title:{zh:"同一情绪为何影响不同股票？",en:"Why might sentiment affect stocks differently?"},body:{zh:"论文把投机需求变化与套利限制放在一起考虑。估值更主观的公司可能更受乐观或悲观预期影响，难以对冲、卖空成本高的股票也更难被套利力量纠正。这两组特征常有重叠，所以研究并不能轻易把每个结果归给单一渠道。",en:"The argument combines changing speculative demand with limits to arbitrage. Subjective valuations may respond more to optimism or pessimism, while difficult hedging and costly short selling can impede correction. These characteristics overlap, making it difficult to assign each empirical pattern to only one channel."},reference:{url:"https://pages.stern.nyu.edu/~jwurgler/papers/wurgler_baker_cross_section.pdf",label:{zh:"原文定位：2006年期刊版，第1648–1650页",en:"Source: 2006 journal article, pp. 1648–1650"}}},{title:{zh:"六个代理量，不是一份问卷",en:"Six proxies, not a sentiment questionnaire"},body:{zh:"指数使用封闭式基金折价、纽约证交所换手率、IPO数量与首日收益、股票融资占比和股息溢价。它们分别来自市场价格、交易和融资活动。股息溢价比较派息与不派息公司的估值，不能替换为股息率；新闻情感分数也不是这篇论文的原始指标。",en:"The six inputs are closed-end fund discounts, NYSE turnover, IPO volume and first-day returns, the equity share in new issues, and the dividend premium. They describe prices, trading and financing. The dividend premium compares payer and nonpayer valuations; it is not a dividend yield or a text-based news sentiment score."},reference:{url:"https://pages.stern.nyu.edu/~jwurgler/papers/wurgler_baker_cross_section.pdf",label:{zh:"原文定位：2006年期刊版，第1655–1656页",en:"Source: 2006 journal article, pp. 1655–1656"}}},{title:{zh:"共同成分也要考虑先后顺序",en:"Shared variation has a timing structure"},body:{zh:"作者先对六个代理量及其滞后值提取第一主成分，再按与初步指数的相关性为各代理量选择时点，重新构造精简指数。最终组合同时含当期和滞后项，不能把所有观测统一移到同一年而声称保持了原方法。各输入还要先标准化。",en:"A first principal component is estimated from six proxies and their lags. Correlations with that preliminary index then select a timing for each proxy before a parsimonious index is constructed. The final mix uses current and lagged inputs, standardized first; moving every observation to the same year changes the method."},reference:{url:"https://pages.stern.nyu.edu/~jwurgler/papers/wurgler_baker_cross_section.pdf",label:{zh:"原文定位：2006年期刊版，第1656–1657页",en:"Source: 2006 journal article, pp. 1656–1657"}}},{title:{zh:"去除周期成分仍然是模型选择",en:"Removing business-cycle variation is conditional"},body:{zh:"IPO与换手等变量也会随合理的经济变化波动，第一主成分不能自动把共同波动识别为情绪。作者另将各代理量对工业生产、消费增长和衰退指标回归，用残差构造第二指数。这个处理依赖选定的控制变量，不等于剔除了所有基本面信息。",en:"IPO activity and turnover can move for rational economic reasons; a principal component does not label shared variation as sentiment. A second index uses residuals after controlling for industrial production, consumption growth and recessions. Its interpretation remains conditional on those controls, not proof that all fundamental information has disappeared."},reference:{url:"https://pages.stern.nyu.edu/~jwurgler/papers/wurgler_baker_cross_section.pdf",label:{zh:"原文定位：2006年期刊版，第1657页",en:"Source: 2006 journal article, pp. 1657"}}},{title:{zh:"公司特征需要历史匹配",en:"Firm characteristics require historical matching"},body:{zh:"公司资料来自CRSP与Compustat的历史普通股样本，财政年度结束于t−1年的报表与t年7月至次年6月收益匹配。公司年龄按首次进入CRSP计算，并不等同于成立年限。数据覆盖改变会影响解释，跨市场迁移时不能省略这一身份与时间核对。",en:"The historical common-stock sample joins CRSP and Compustat, matching fiscal years ending in t−1 to returns from July t through June t+1. Age measures time since first appearance in CRSP, not time since incorporation. Coverage changes therefore matter when translating the firm's identity and timing conventions to another market."},reference:{url:"https://pages.stern.nyu.edu/~jwurgler/papers/wurgler_baker_cross_section.pdf",label:{zh:"原文定位：2006年期刊版，第1653–1655页",en:"Source: 2006 journal article, pp. 1653–1655"}}},{title:{zh:"不要给复杂特征贴单一标签",en:"Characteristics can carry several meanings"},body:{zh:"高账面市值比既可能反映困境，也包含估值与预期收益信息；销售增长和融资又可能同时对应成长机会或经营压力。论文因此关注情绪与多种特征的关系，而不是把某一比率直接解释为非理性。指数与收益的关系仍需要结合样本和替代解释阅读。",en:"High book-to-market can reflect distress as well as valuation and expected returns; sales growth and financing can describe growth opportunities or operating pressure. The study examines sentiment across such multidimensional characteristics rather than equating one ratio with irrationality. Sample context and competing explanations remain important."},reference:{url:"https://pages.stern.nyu.edu/~jwurgler/papers/wurgler_baker_cross_section.pdf",label:{zh:"原文定位：2006年期刊版，第1655, 1657页",en:"Source: 2006 journal article, pp. 1655, 1657"}}}],readerLimits:{zh:"综合情绪指数不是直接观察到的心理状态。共同周期、代理变量的时滞与套利限制都影响解释，历史美国样本的指数权重不是跨市场通用标准。",en:"The composite index is not a direct observation of psychology. Shared cycles, proxy timing and arbitrage constraints affect interpretation; historical US index weights are not a universal cross-market standard."}},{id:"investor-sentiment-in-the-stock-market",title:"Investor Sentiment in the Stock Market",titleZh:"股票市场中的投资者情绪",sourceTitle:"Investor Sentiment in the Stock Market",authors:"Malcolm Baker · Jeffrey Wurgler",venue:"Journal of Economic Perspectives",year:"2007",kind:"paper",topic:"alternative-data",data:"sentiment indicators; issuance; turnover; valuation",dataZh:"情绪指标；发行；换手率；估值",summary:{en:"Reviews measurement approaches and economic interpretations of investor sentiment.",zh:"综述投资者情绪的度量方法与经济解释。"},related:{datasets:["cn-news-flashes","cn-announcements"],recipes:["company-event-timeline"]},sources:[{label:"DOI",url:"https://doi.org/10.1257/jep.21.2.129"}]},{id:"the-stock-market-s-reaction-to-unemployment-news-why-bad-news-is-usually-good-for-stocks",title:"The Stock Market's Reaction to Unemployment News: Why Bad News Is Usually Good for Stocks",titleZh:"股票市场对失业消息的反应",sourceTitle:"The Stock Market's Reaction to Unemployment News: Why Bad News Is Usually Good for Stocks",authors:"JOHN H. BOYD · JIAN HU · RAVI JAGANNATHAN",venue:"The Journal of Finance",year:"2005",kind:"paper",topic:"macro-finance",data:"release timestamps; unemployment surprises; market returns",dataZh:"发布时间戳；失业数据意外；市场收益",summary:{en:"Studies how business-cycle conditions change interpretation of labor-market releases.",zh:"研究经济周期状态如何改变劳动市场发布的含义。"},related:{datasets:["cn-macro-calendar","cn-yield-curve","global-macro-indicators"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/j.1540-6261.2005.00742.x"}]},{id:"what-moves-stock-prices",title:"What Moves Stock Prices?",titleZh:"什么推动股价变化？",sourceTitle:"What moves stock prices?",authors:"David M. Cutler · James M. Poterba · Lawrence H. Summers",venue:"The Journal of Portfolio Management",year:"1989",kind:"paper",topic:"alternative-data",data:"market returns; news chronology; macro announcements",dataZh:"市场收益；新闻时间线；宏观公告",summary:{en:"Compares large market movements with identified news and economic developments.",zh:"将大幅市场变化与可识别新闻和经济事件比较。"},related:{datasets:["cn-news-flashes","cn-announcements"],recipes:["company-event-timeline"]},sources:[{label:"DOI",url:"https://doi.org/10.3905/jpm.1989.409212"}]},{id:"the-impact-of-public-information-on-the-stock-market",title:"The Impact of Public Information on the Stock Market",titleZh:"公开信息对股票市场的影响",sourceTitle:"The Impact of Public Information on the Stock Market",authors:"MARK L. MITCHELL · J. HAROLD MULHERIN",venue:"The Journal of Finance",year:"1994",kind:"paper",topic:"alternative-data",data:"news counts; publication dates; returns; volume",dataZh:"新闻数量；发布日期；收益；成交量",summary:{en:"Studies daily public news releases and aggregate market activity.",zh:"研究每日公开新闻发布与市场总体活动之间的关系。"},related:{datasets:["cn-news-flashes","cn-announcements"],recipes:["company-event-timeline"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/j.1540-6261.1994.tb00083.x"}]},{id:"lazy-prices",title:"Lazy Prices",titleZh:"迟滞的信息反应与披露文本变化",sourceTitle:"Lazy Prices",authors:"LAUREN COHEN · CHRISTOPHER MALLOY · QUOC NGUYEN",venue:"The Journal of Finance",year:"2020",kind:"paper",topic:"alternative-data",data:"successive filings; text differences; filing dates; returns",dataZh:"连续披露文件；文本差异；披露日期；收益",summary:{en:"Uses changes in corporate disclosures to study how document revisions enter prices.",zh:"利用公司披露文本变化研究文档修订如何进入价格。"},related:{datasets:["cn-news-flashes","cn-announcements"],recipes:["company-event-timeline"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/jofi.12885"}],readingNotes:[{title:{zh:"读变化，而不只读语气",en:"Read changes, not just tone"},body:{zh:"Cohen、Malloy与Nguyen比较企业定期披露文本在不同版本之间的变化。与计算一份文件有多少负面词不同，这里的研究对象是同一公司报告语言和结构怎样改变。",en:"Cohen, Malloy and Nguyen compare changes in recurring corporate disclosures. Unlike counting negative words in one document, the object is how a firm's reporting language and construction change over time."}},{title:{zh:"报告所属年度不是读者看到的日期",en:"The reporting year is not the release date"},body:{zh:"2019年工作论文考察1995—2014年的定期披露，并用Baxter案例说明：一份标为2009年度的报告实际在2010年公开，之后又出现相关新闻。编辑建议：同时保存报告期、提交时间和后续消息时间，不能将年度标签当作报告已可阅读的日期。",en:"The March 2019 working paper studies recurring disclosures from 1995–2014. Its Baxter illustration distinguishes a report for 2009 from its public filing in 2010 and subsequent news. Editorial application: preserve reporting period, filing time and later-news time separately; a fiscal-year label does not establish public availability."},reference:{url:"https://www.nber.org/system/files/working_papers/w25084/w25084.pdf",label:{zh:"2019年3月工作论文引言：Baxter披露案例",en:"March 2019 working-paper introduction: Baxter disclosure example"}}},{title:{zh:"需要一对可比文件",en:"Start with a comparable pair"},body:{zh:"研究使用美国公司的季度与年度文件。本站建议先明确比较的报告类型、期间和版本，再处理格式。把年报与季报、首次披露与后续修订混在一起，可能把文档管理差异误认为信息变化。",en:"The study uses US quarterly and annual filings. Match form, period and version before cleaning. Mixing annual with quarterly reports, or originals with amendments, can confuse document management with information change."}},{title:{zh:"没有即时反应不等于没有信息",en:"No immediate response is not no information"},body:{zh:"作者报告文本变化与后续经营结果相关，但未观察到典型的公告时点反应，因而讨论投资者注意力。这个发现提示应区分信息发布、信息被处理与后续结果显现，而不是只看披露当天。",en:"The authors associate changes with later operating outcomes despite lacking a typical announcement response. Their attention interpretation separates information release, processing and subsequent realization rather than looking only at filing day."}},{title:{zh:"变化多的章节，不一定最有信息",en:"Frequent change need not be the most informative change"},body:{zh:"作者在引言中区分变化集中出现的管理层讨论章节，与对后续结果更有信息的风险因素等内容。编辑建议：比较总文本变化之外，还要保留章节边界，并抽查新增、删除和修改的实际语句。一个整体相似度分数，无法独自说明变化属于经营风险还是例行编辑。",en:"The introduction distinguishes MD&A, where many changes occur, from sections such as risk factors that contain informative changes. Editorial application: preserve section boundaries and inspect additions, deletions and revisions alongside aggregate similarity. One whole-document score cannot by itself distinguish operating-risk disclosure from routine editing."},reference:{url:"https://www.nber.org/system/files/working_papers/w25084/w25084.pdf",label:{zh:"2019年3月工作论文引言：章节差异",en:"March 2019 working-paper introduction: differences across sections"}}},{title:{zh:"与金融词典互补，而非替代",en:"Complement dictionaries"},body:{zh:"金融词典强调特定语境下的词义，这篇强调同一企业的文本变化，两者测量对象不同。本站建议保留文本版本、清洗规则和人工核对样本；版式调整、模板变更和会计制度变化都值得单独检查。",en:"Financial dictionaries target contextual meaning; this study targets document change. Preserve versions, cleaning rules and manual checks. Formatting, templates and reporting-rule changes deserve separate inspection."}}],readerLimits:{zh:"导读补充依据2019年3月工作论文；正式出版身份不变。文本变化不必然是坏消息，英文样本也不能直接验证中文指标或当前表现。",en:"Added reading detail uses the March 2019 working paper, separately from the final publication identity. Change is not automatically bad news; English-sample evidence does not validate Chinese measures or current performance."}},{id:"the-information-content-of-forward-looking-statements-in-corporate-filings-a-na-ve-bayesian-machine-learning-approach",title:"The Information Content of Forward-Looking Statements in Corporate Filings—A Naïve Bayesian Machine Learning Approach",titleZh:"公司披露前瞻性陈述的信息含量",sourceTitle:"The Information Content of Forward‐Looking Statements in Corporate Filings—A Naïve Bayesian Machine Learning Approach",authors:"FENG LI",venue:"Journal of Accounting Research",year:"2010",kind:"paper",topic:"alternative-data",data:"filing sections; sentence labels; accounting outcomes",dataZh:"披露章节；句子标签；会计结果",summary:{en:"Classifies forward-looking disclosure language and relates it to subsequent fundamentals.",zh:"分类前瞻性披露语言，并与后续基本面关联。"},related:{datasets:["cn-news-flashes","cn-announcements"],recipes:["company-event-timeline"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/j.1475-679x.2010.00382.x"}]},{id:"annual-report-readability-current-earnings-and-earnings-persistence",title:"Annual Report Readability, Current Earnings, and Earnings Persistence",titleZh:"年报可读性、当期盈利与盈利持续性",sourceTitle:"Annual report readability, current earnings, and earnings persistence",authors:"Feng Li",venue:"Journal of Accounting and Economics",year:"2008",kind:"paper",topic:"alternative-data",data:"annual reports; readability measures; earnings; firm controls",dataZh:"年报；可读性指标；盈利；企业控制变量",summary:{en:"Studies document readability alongside earnings and their persistence.",zh:"结合盈利及其持续性研究文档可读性。"},related:{datasets:["cn-news-flashes","cn-announcements"],recipes:["company-event-timeline"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/j.jacceco.2008.02.003"}]},{id:"bond-risk-premia",title:"Bond Risk Premia",titleZh:"债券风险溢价",sourceTitle:"Bond Risk Premia",authors:"John H Cochrane · Monika Piazzesi",venue:"American Economic Review",year:"2005",kind:"paper",topic:"macro-finance",data:"zero-coupon yields; forward rates; holding-period returns",dataZh:"零息收益率；远期利率；持有期收益",summary:{en:"Examines information in forward rates for understanding bond excess returns.",zh:"研究远期利率包含的债券超额收益相关信息。"},related:{datasets:["cn-macro-calendar","cn-yield-curve","global-macro-indicators"]},sources:[{label:"DOI",url:"https://doi.org/10.1257/0002828053828581"}],readingNotes:[{title:{zh:"收益率曲线与持有期收益不同",en:"Yields are not holding-period returns"},body:{zh:"Cochrane与Piazzesi研究债券预期超额收益如何随时间变化。研究对象是未来一年持有债券的超额收益，而不是今天的到期收益率或一年后的短期利率；三者不能互相替代。",en:"Cochrane and Piazzesi study time variation in expected excess bond returns. Their target is a one-year holding-period excess return, not today's yield or next year's short rate."}},{title:{zh:"持有一年后，债券期限也变短一年",en:"A year of holding also shortens maturity"},body:{zh:"原文使用Fama–Bliss一至五年零息债券价格。买入一只n年债券，一年后卖出时它已是n−1年债券；持有期对数收益再减去期初一年期利率，才得到这里的超额收益。用同一期限收益率的年度变化代替，会漏掉滚动期限与价格转换。",en:"The paper uses Fama–Bliss zero-coupon prices for one- through five-year maturities. An n-year bond becomes an n−1-year bond when sold one year later; its log holding return is then reduced by the initial one-year rate. A change in a constant-maturity yield is not that return calculation."},reference:{url:"https://web.stanford.edu/~piazzesi/cp.pdf",label:{zh:"原文第I.A–I.B节：定义与零息价格",en:"Original §§I.A–I.B: definitions and zero-coupon prices"}}},{title:{zh:"从期初远期利率提取信息",en:"Use information available initially"},body:{zh:"作者将一年超额收益与期初一组远期利率联系起来，发现一个帐篷形线性组合能概括多个期限的预测关系。这里的组合是统计表示，不是本站提供的交易信号，也不是任意挑选几个期限即可重建。",en:"Regressions relate one-year excess returns to initial forward rates. A tent-shaped combination summarizes relationships across maturities. It is a statistical representation, not a site-provided trading signal or an arbitrary choice of tenors."}},{title:{zh:"拟合曲线的因子未必保留全部信息",en:"Curve factors may omit information"},body:{zh:"论文强调，预测收益的信息有一部分不同于描述收益率曲线主要变化的水平、斜率和曲率。一个模型很好地拟合了收益率，不代表它自动保留了另一个目标所需要的全部信息。",en:"Some return-forecasting information differs from level, slope and curvature movements explaining most yield variation. A good fit for yields need not preserve everything relevant to a different target."}},{title:{zh:"月度观测的一年收益会重叠",en:"Monthly observations of annual returns overlap"},body:{zh:"每个月向前看一年，相邻观测会共享大部分持有月份，因此样本行数不能当作独立年度实验次数。第I.C节专门比较重叠收益下的统计处理。作者也用滞后的远期利率检查共用价格测量误差；这与简单增加观测数量是不同的稳健性问题。",en:"Rolling a one-year horizon forward monthly makes adjacent observations share most holding months. Row count is therefore not a count of independent annual experiments. Section I.C examines overlapping-return inference, while lagged forward rates address shared-price measurement error. These are distinct checks, not benefits obtained merely by adding rows."},reference:{url:"https://web.stanford.edu/~piazzesi/cp.pdf",label:{zh:"原文第I.C节及引言：重叠窗口与测量误差",en:"Original §I.C and introduction: overlap and measurement error"}}},{title:{zh:"与前两篇形成三个层次",en:"Three questions in one sequence"},body:{zh:"Nelson–Siegel关注曲线形状，Diebold–Li关注曲线动态，这篇关注持有期超额收益。本站建议分别保存价格、收益率、远期利率和期限约定；不要把供应商同名字段当作论文定义，也不要把样本内关系写成当前可用预测。",en:"Nelson–Siegel addresses shape, Diebold–Li dynamics, and this paper holding-period excess returns. Preserve prices, yields, forwards and tenor conventions separately; vendor labels alone do not establish equivalence to the paper's inputs."}}],readerLimits:{zh:"美国国债历史样本的统计关系不保证当前或跨市场预测；持有期重叠、利率测量和样本外检验仍影响解释。",en:"Historical US Treasury relationships do not guarantee current or cross-market forecasts; overlapping horizons, rate measurement and out-of-sample tests matter."}},{id:"common-factors-affecting-bond-returns",title:"Common Factors Affecting Bond Returns",titleZh:"影响债券收益的共同因子",sourceTitle:"Common Factors Affecting Bond Returns",authors:"Robert B Litterman · Josè Scheinkman",venue:"The Journal of Fixed Income",year:"1991",kind:"paper",topic:"macro-finance",data:"yield curves; tenors; rate changes; factor loadings",dataZh:"收益率曲线；期限；利率变化；因子载荷",summary:{en:"Studies level, slope, and curvature as common movements in interest rates.",zh:"研究利率共同变化中的水平、斜率与曲率。"},related:{datasets:["cn-macro-calendar","cn-yield-curve","global-macro-indicators"]},sources:[{label:"DOI",url:"https://doi.org/10.3905/jfi.1991.692347"}]},{id:"parsimonious-modeling-of-yield-curves",title:"Parsimonious Modeling of Yield Curves",titleZh:"收益率曲线的简约建模",sourceTitle:"Parsimonious Modeling of Yield Curves",authors:"Charles R. Nelson · Andrew F. Siegel",venue:"The Journal of Business",year:"1987",kind:"paper",topic:"macro-finance",data:"bond yields; maturities; curve-fitting weights",dataZh:"债券收益率；到期时间；曲线拟合权重",summary:{en:"Provides a low-dimensional representation of term structures.",zh:"为期限结构提供低维表示。"},related:{datasets:["cn-macro-calendar","cn-yield-curve","global-macro-indicators"]},sources:[{label:"DOI",url:"https://doi.org/10.1086/296409"}],readingNotes:[{title:{zh:"用少数参数描述很多期限",en:"Few parameters, many maturities"},body:{zh:"Nelson与Siegel提出简约收益率曲线模型，目标是在较少参数下表达常见曲线形状。简约意味着在灵活度和可解释性之间做选择，不意味着所有期限都能毫无误差地拟合。",en:"Nelson and Siegel seek a small-parameter representation of common yield-curve shapes. Parsimony trades flexibility against interpretability; it does not promise exact fit at every maturity."}},{title:{zh:"先固定衰减尺度，再估计系数",en:"Fix the decay scale before estimating coefficients"},body:{zh:"1985年工作论文把估计分成两层：给定衰减参数后，其余三个系数可用线性最小二乘求得，再比较不同衰减参数下的拟合。该参数影响曲率集中在哪些期限；它不是无关紧要的设置。因此，“三个线性系数”不意味着整个估计问题只有三个待定量。",en:"The 1985 working paper separates estimation into two layers. Conditional on a decay parameter, three coefficients follow from linear least squares; fit is then compared across decay values. The decay scale affects where curvature can occur along maturity. Three linear coefficients therefore do not mean that only three quantities must be chosen."},reference:{url:"https://www.nber.org/system/files/working_papers/w1594/w1594.pdf",label:{zh:"1985年工作论文第2–3节，正文第8、11–12页",en:"1985 working paper §§2–3, printed pp. 8, 11–12"}}},{title:{zh:"曲线不必总是向上",en:"Curves need not simply rise"},body:{zh:"摘要说明模型能够表达单调、驼峰与S形曲线。阅读时应把观察到的形状与赋予形状的经济解释分开：同一种外形可能来自不同市场环境，不能只凭曲线形状识别唯一原因。",en:"The abstract describes monotonic, humped and S-shaped curves. An observed shape and its economic interpretation are different; a shape alone cannot identify one underlying cause."}},{title:{zh:"拟合证据有样本范围",en:"Fit has a sample boundary"},body:{zh:"原研究用1981—1983年的国库券收益率考察不同期限的拟合，并讨论参数随时间的变化。这是特定资料上的曲线表示证据，不应写成任何时期、任何国家的利率预测能力。",en:"The study examines Treasury-bill yields in 1981–1983 and movements in fitted parameters. Evidence about representation in that sample is not universal forecasting performance across countries and regimes."}},{title:{zh:"这里的样本外，是跨期限外推",en:"Out of sample here means extrapolating across maturities"},body:{zh:"工作论文第5节用短期国库券拟合的曲线为长期债券定价，检验的是超出已有期限范围后的表现，不是未来日期的预测。文中说明，局部拟合相近的参数可能给出差别很大的长期贴现率。阅读这类检验时，要先分清留出的是期限还是时间，不能把二者当成同一种预测证据。",en:"Section 5 of the working paper prices a long bond using a curve fitted to short bills. Its extrapolation leaves the observed maturity range, not the observation date. Similar short-end fits can imply very different long-term discount rates. Distinguish a held-out maturity from a future date before interpreting either exercise as forecast evidence."},reference:{url:"https://www.nber.org/system/files/working_papers/w1594/w1594.pdf",label:{zh:"1985年工作论文第5节，正文第20–21页",en:"1985 working paper §5, printed pp. 20–21"}}},{title:{zh:"下一步：让曲线随时间变化",en:"Next: model curves over time"},body:{zh:"Diebold与Li在相关框架中进一步研究动态表示与样本外预测。本站建议先确认输入是零息收益率还是到期收益率，统一期限与复利单位；曲线拟合、跨期预测和债券持有期收益是三种不同任务。",en:"Diebold and Li extend the discussion to dynamics and out-of-sample forecasts. First align yield definitions, maturity units and compounding. Curve fitting, forecasting and holding-period returns are distinct tasks."}}],readerLimits:{zh:"方法细节依据1985年NBER工作论文，书目信息保留1987年终刊。曲线拟合不保证跨期限外推可靠，也不等于无套利证明或未来预测能力。",en:"Method details use the 1985 NBER working paper; the citation identifies the 1987 journal publication. Curve fit does not establish reliable maturity extrapolation, no-arbitrage or future forecasting performance."}},{id:"forecasting-the-term-structure-of-government-bond-yields",title:"Forecasting the Term Structure of Government Bond Yields",titleZh:"预测国债收益率期限结构",sourceTitle:"Forecasting the term structure of government bond yields",authors:"Francis X. Diebold · Canlin Li",venue:"Journal of Econometrics",year:"2006",kind:"paper",topic:"macro-finance",data:"yield curves; maturities; factor time series",dataZh:"收益率曲线；期限；因子时间序列",summary:{en:"Models time variation in yield-curve factors using a dynamic representation.",zh:"用动态表示研究收益率曲线因子的时间变化。"},related:{datasets:["cn-macro-calendar","cn-yield-curve","global-macro-indicators"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/j.jeconom.2005.03.005"}],readingNotes:[{title:{zh:"拟合今天与预测未来不同",en:"Fitting today is not forecasting tomorrow"},body:{zh:"Diebold与Li把Nelson–Siegel曲线重新解释为水平、斜率与曲率三个动态因子，再预测因子来重建未来曲线。核心问题不只是当前各期限能否拟合得很漂亮，而是这种简约结构是否有助于样本外预测。",en:"Diebold and Li reinterpret Nelson–Siegel coefficients as dynamic level, slope and curvature factors. Forecasting the factors reconstructs a future curve. The question is whether a parsimonious structure helps out-of-sample prediction, not merely whether today's curve fits closely."}},{title:{zh:"输入是构造后的零息收益率",en:"Inputs are constructed zero yields"},body:{zh:"样本为1985年1月至2000年12月的美国国债月末买卖报价均值，来自CRSP。作者由过滤后的债券报价构造Fama–Bliss零息收益率，再将相邻期限插值到固定期限。这不是把债券票息或任意到期收益率直接拼成一条曲线。",en:"The sample uses end-of-month US Treasury bid/ask averages from CRSP, January 1985–December 2000. Filtered bond prices yield Fama–Bliss zero rates, interpolated to fixed maturities. Coupon rates or arbitrary coupon-bond yields cannot simply be substituted."},reference:{url:"https://elearning.unito.it/sme/pluginfile.php/546632/course/section/90489/DieboldLi_JoE06.pdf",label:{zh:"原文第2.1与3.1节：收益率口径和数据",en:"Original §§2.1 and 3.1: yield conventions and data"}}},{title:{zh:"三个因子怎样作用于期限",en:"How the factors load on maturity"},body:{zh:"水平因子的载荷在所有期限相同；斜率因子更多作用于短端；曲率因子主要作用于中段。作者固定衰减参数，让每期因子可以用较简单的估计方法得到。要注意斜率的符号约定：因子系数不应未经转换就等同于长端减短端的利差。",en:"The level loading is constant, the slope loading concentrates at the short end and curvature loads most strongly in the middle. Fixing the decay parameter simplifies factor estimation. Sign conventions matter: a slope coefficient is not automatically the long-minus-short yield spread."},reference:{url:"https://elearning.unito.it/sme/pluginfile.php/546632/course/section/90489/DieboldLi_JoE06.pdf",label:{zh:"原文第2.2节：因子解释",en:"Original §2.2: factor interpretation"}}},{title:{zh:"优势依赖预测期限",en:"The advantage depends on horizon"},body:{zh:"结论部分报告，一月期预测未优于随机游走等主要对照，而一年期表现明显更好。这提醒读者不要只说“模型胜出”，而应写明预测期限、评价样本与基准。当前曲线拟合更灵活，也不保证样本外预测更准。",en:"The conclusion distinguishes horizons: one-month forecasts do not outperform the leading benchmarks, while one-year forecasts are substantially stronger. A model comparison must specify horizon, evaluation sample and benchmark. A more flexible in-sample fit does not guarantee better forecasts."},reference:{url:"https://elearning.unito.it/sme/pluginfile.php/546632/course/section/90489/DieboldLi_JoE06.pdf",label:{zh:"原文第4节：预测结论与限制",en:"Original §4: forecasting conclusions and limits"}}},{title:{zh:"先读单位，再读预测比较",en:"Read units before comparisons"},body:{zh:"建议先核对零息、连续复利、期限单位和报价日期，再读第2.2节的载荷，最后看预测比较。模型中的期限用月表示；如果改成年而不一致地调整参数，曲线形状就会被改变。不同国家或数据商的曲线也要先统一口径。",en:"Check zero-coupon status, compounding, maturity units and observation dates before reading the loadings and forecast comparisons. Maturity is measured in months; changing units without adjusting parameters changes the shape. Curves from different countries or vendors need convention alignment first."}},{title:{zh:"预测模型不是定价保证",en:"A forecast model is not a pricing guarantee"},body:{zh:"作者明确讨论其模型并非无套利模型。编辑建议：若目标是预测，先保留时间切分与基准；若目标转为衍生品定价，则需要另行处理无套利与动态一致性。宏观解释也应独立检验，不能把水平、斜率和曲率的名称直接当成经济因果。",en:"The authors explicitly note that their model is not arbitrage-free. Editorial application: preserve chronological evaluation for forecasting; derivative pricing needs additional no-arbitrage and dynamic-consistency treatment. Factor labels also do not establish macroeconomic causality."}}],readerLimits:{zh:"美国历史月度样本的预测比较不是跨市场保证；零息口径、期限单位与预测目标必须保持明确。",en:"Historical US monthly forecast comparisons are not a cross-market guarantee. Keep zero-yield conventions, maturity units and forecasting targets explicit."}},{id:"the-macroeconomy-and-the-yield-curve-a-dynamic-latent-factor-approach",title:"The Macroeconomy and the Yield Curve: A Dynamic Latent Factor Approach",titleZh:"宏观经济与收益率曲线",sourceTitle:"The macroeconomy and the yield curve: a dynamic latent factor approach",authors:"Francis X. Diebold · Glenn D. Rudebusch · S. Boragˇan Aruoba",venue:"Journal of Econometrics",year:"2006",kind:"paper",topic:"macro-finance",data:"yield curves; inflation; output; policy rates",dataZh:"收益率曲线；通胀；产出；政策利率",summary:{en:"Connects latent yield-curve factors with macroeconomic observations.",zh:"将潜在收益率曲线因子与宏观观测连接。"},related:{datasets:["cn-macro-calendar","cn-yield-curve","global-macro-indicators"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/j.jeconom.2005.01.011"}]},{id:"business-cycles-in-a-small-open-economy",title:"Business Cycles in a Small Open Economy",titleZh:"小型开放经济中的经济周期",sourceTitle:"Business cycles in a small open economy",authors:"Isabel Correia · João C. Neves · Sergio Rebelo",venue:"European Economic Review",year:"1995",kind:"paper",topic:"macro-finance",data:"output; consumption; trade balance; world interest rates",dataZh:"产出；消费；贸易余额；世界利率",summary:{en:"Studies macroeconomic fluctuations in an open-economy setting.",zh:"研究开放经济环境下的宏观波动。"},related:{datasets:["cn-macro-calendar","cn-yield-curve","global-macro-indicators"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/0014-2921(94)00105-9"}]},{id:"the-forward-premium-puzzle-different-tales-from-developed-and-emerging-economies",title:"The Forward Premium Puzzle: Different Tales from Developed and Emerging Economies",titleZh:"远期升水之谜与不同经济体",sourceTitle:"The forward premium puzzle: different tales from developed and emerging economies",authors:"Ravi Bansal · Magnus Dahlquist",venue:"Journal of International Economics",year:"2000",kind:"paper",topic:"macro-finance",data:"spot FX; forward FX; interest differentials; currencies",dataZh:"即期汇率；远期汇率；利差；币种",summary:{en:"Compares exchange-rate and interest-rate relationships across country groups.",zh:"比较不同国家组的汇率与利率关系。"},related:{datasets:["cn-macro-calendar","cn-yield-curve","global-macro-indicators"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/s0022-1996(99)00039-2"}]},{id:"common-risk-factors-in-currency-markets",title:"Common Risk Factors in Currency Markets",titleZh:"货币市场中的共同风险因子",sourceTitle:"Common Risk Factors in Currency Markets",authors:"Hanno Lustig · Nikolai Roussanov · Adrien Verdelhan",venue:"Review of Financial Studies",year:"2011",kind:"paper",topic:"macro-finance",data:"exchange rates; forward discounts; currency baskets",dataZh:"汇率；远期贴水；货币篮子",summary:{en:"Studies common risk components across currency portfolios.",zh:"研究货币组合之间的共同风险成分。"},related:{datasets:["cn-macro-calendar","cn-yield-curve","global-macro-indicators"]},sources:[{label:"DOI",url:"https://doi.org/10.1093/rfs/hhr068"}]},{id:"carry",title:"Carry",titleZh:"持有收益研究",sourceTitle:"Carry",authors:"Ralph S.J. Koijen · Tobias J. Moskowitz · Lasse Heje Pedersen · Evert B. Vrugt",venue:"Journal of Financial Economics",year:"2018",kind:"paper",topic:"macro-finance",data:"spot and forward prices; contract terms; financing rates",dataZh:"即期与远期价格；合约条款；融资利率",summary:{en:"Defines carry consistently across asset classes and distinguishes it from price changes.",zh:"跨资产统一定义持有收益，并与价格变化区分。"},related:{datasets:["cn-macro-calendar","cn-yield-curve","global-macro-indicators"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/j.jfineco.2017.11.002"}]},{id:"discretion-versus-policy-rules-in-practice",title:"Discretion versus Policy Rules in Practice",titleZh:"相机抉择与政策规则",sourceTitle:"Discretion versus policy rules in practice",authors:"John B. Taylor",venue:"Carnegie-Rochester Conference Series on Public Policy",year:"1993",kind:"paper",topic:"macro-finance",data:"policy rates; inflation; output gap; real-time vintages",dataZh:"政策利率；通胀；产出缺口；实时版本",summary:{en:"Offers a benchmark for relating policy rates to inflation and economic activity.",zh:"为政策利率与通胀及经济活动的关系提供基准。"},related:{datasets:["cn-macro-calendar","cn-yield-curve","global-macro-indicators"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/0167-2231(93)90009-l"}]},{id:"monetary-policy-shocks-what-have-we-learned-and-to-what-end",title:"Monetary Policy Shocks: What Have We Learned and to What End?",titleZh:"货币政策冲击的识别与解释",sourceTitle:"Monetary Policy Shocks: What Have We Learned and to What End?",authors:"Lawrence Christiano · Martin Eichenbaum · Charles Evans",venue:"National Bureau of Economic Research",year:"1998",kind:"working-paper",topic:"macro-finance",data:"policy instruments; macro series; identification restrictions",dataZh:"政策工具；宏观序列；识别约束",summary:{en:"Reviews identification choices for measuring monetary policy shocks.",zh:"综述衡量货币政策冲击时的识别选择。"},related:{datasets:["cn-macro-calendar","cn-yield-curve","global-macro-indicators"]},sources:[{label:"DOI",url:"https://doi.org/10.3386/w6400"}]},{id:"measuring-the-effects-of-monetary-policy-a-factor-augmented-vector-autoregressive-favar-approach",title:"Measuring the Effects of Monetary Policy: A Factor-Augmented Vector Autoregressive (FAVAR) Approach",titleZh:"货币政策效应的因子增强向量自回归分析",sourceTitle:"Measuring the Effects of Monetary Policy: A Factor-Augmented Vector Autoregressive (FAVAR) Approach",authors:"B. S. Bernanke · J. Boivin · P. Eliasz",venue:"The Quarterly Journal of Economics",year:"2005",kind:"paper",topic:"macro-finance",data:"macro panel; policy rates; factor estimates; vintages",dataZh:"宏观面板；政策利率；因子估计；数据版本",summary:{en:"Uses many macro indicators to enrich the information set in policy analysis.",zh:"利用大量宏观指标扩展政策分析的信息集。"},related:{datasets:["cn-macro-calendar","cn-yield-curve","global-macro-indicators"]},sources:[{label:"DOI",url:"https://doi.org/10.1162/0033553053327452"}]},{id:"the-macroeconomic-impact-of-financial-and-uncertainty-shocks",title:"The Macroeconomic Impact of Financial and Uncertainty Shocks",titleZh:"金融与不确定性冲击的宏观影响",sourceTitle:"The macroeconomic impact of financial and uncertainty shocks",authors:"Dario Caldara · Cristina Fuentes-Albero · Simon Gilchrist · Egon Zakrajšek",venue:"European Economic Review",year:"2016",kind:"paper",topic:"macro-finance",data:"credit spreads; uncertainty measures; macro series",dataZh:"信用利差；不确定性指标；宏观序列",summary:{en:"Studies identification of financial and uncertainty shocks and their separate macroeconomic effects.",zh:"研究金融冲击与不确定性冲击的识别及各自的宏观经济影响。"},related:{datasets:["cn-macro-calendar","cn-yield-curve","global-macro-indicators"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/j.euroecorev.2016.02.020"}]},{id:"credit-spreads-and-business-cycle-fluctuations",title:"Credit Spreads and Business Cycle Fluctuations",titleZh:"信用利差与经济周期波动",sourceTitle:"Credit Spreads and Business Cycle Fluctuations",authors:"Simon Gilchrist · Egon Zakrajšek",venue:"American Economic Review",year:"2012",kind:"paper",topic:"macro-finance",data:"bond prices; default risk; excess bond premium; output",dataZh:"债券价格；违约风险；超额债券溢价；产出",summary:{en:"Separates credit-spread components to examine economic fluctuations.",zh:"分离信用利差成分以研究经济波动。"},related:{datasets:["cn-macro-calendar","cn-yield-curve","global-macro-indicators"]},sources:[{label:"DOI",url:"https://doi.org/10.1257/aer.102.4.1692"}]},{id:"financial-intermediation-and-credit-policy-in-business-cycle-analysis",title:"Financial Intermediation and Credit Policy in Business Cycle Analysis",titleZh:"经济周期分析中的金融中介与信用政策",sourceTitle:"Financial Intermediation and Credit Policy in Business Cycle Analysis",authors:"Mark Gertler · Nobuhiro Kiyotaki",venue:"Handbook of Monetary Economics",year:"2010",kind:"book",topic:"macro-finance",data:"bank balance sheets; credit spreads; macro aggregates",dataZh:"银行资产负债表；信用利差；宏观汇总",summary:{en:"Adds financial intermediaries to a framework for studying macroeconomic shocks.",zh:"将金融中介纳入宏观冲击研究框架。"},related:{datasets:["cn-macro-calendar","cn-yield-curve","global-macro-indicators"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/b978-0-444-53238-1.00011-9"}]},{id:"the-leverage-cycle",title:"The Leverage Cycle",titleZh:"杠杆周期",sourceTitle:"The Leverage Cycle",authors:"John Geanakoplos",venue:"NBER Macroeconomics Annual",year:"2010",kind:"paper",topic:"macro-finance",data:"collateral values; margins; leverage; funding conditions",dataZh:"抵押品价值；保证金；杠杆；融资条件",summary:{en:"Explains how collateral requirements can amplify asset-price and credit cycles.",zh:"解释抵押要求如何放大资产价格与信贷周期。"},related:{datasets:["cn-macro-calendar","cn-yield-curve","global-macro-indicators"]},sources:[{label:"DOI",url:"https://doi.org/10.1086/648285"}]},{id:"liquidity-and-leverage",title:"Liquidity and Leverage",titleZh:"流动性与杠杆",sourceTitle:"Liquidity and leverage",authors:"Tobias Adrian · Hyun Song Shin",venue:"Journal of Financial Intermediation",year:"2010",kind:"paper",topic:"macro-finance",data:"intermediary assets; debt; market values; funding",dataZh:"中介资产；债务；市值；融资",summary:{en:"Studies balance-sheet adjustment and leverage over the financial cycle.",zh:"研究金融周期中的资产负债表调整与杠杆变化。"},related:{datasets:["cn-macro-calendar","cn-yield-curve","global-macro-indicators"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/j.jfi.2008.12.002"}]},{id:"covar",title:"CoVaR",titleZh:"条件风险价值CoVaR",sourceTitle:"CoVaR",authors:"Tobias Adrian · Markus K. Brunnermeier",venue:"American Economic Review",year:"2016",kind:"paper",topic:"macro-finance",data:"institution returns; system returns; state variables",dataZh:"机构收益；系统收益；状态变量",summary:{en:"Measures dependence between institutional distress and systemwide tail outcomes.",zh:"衡量机构困境与系统尾部结果之间的依赖。"},related:{datasets:["cn-macro-calendar","cn-yield-curve","global-macro-indicators"]},sources:[{label:"DOI",url:"https://doi.org/10.1257/aer.20120555"}]},{id:"srisk-a-conditional-capital-shortfall-measure-of-systemic-risk",title:"SRISK: A Conditional Capital Shortfall Measure of Systemic Risk",titleZh:"SRISK：系统性风险的条件资本缺口",sourceTitle:"SRISK: A Conditional Capital Shortfall Measure of Systemic Risk",authors:"Christian Brownlees · Robert F. Engle",venue:"Review of Financial Studies",year:"2017",kind:"paper",topic:"macro-finance",data:"equity prices; liabilities; capitalization; market returns",dataZh:"股价；负债；资本化；市场收益",summary:{en:"Connects leverage, size, and downside market exposure to capital shortfall.",zh:"将杠杆、规模与市场下行暴露连接到资本缺口。"},related:{datasets:["cn-macro-calendar","cn-yield-curve","global-macro-indicators"]},sources:[{label:"DOI",url:"https://doi.org/10.1093/rfs/hhw060"}]},{id:"forecasting-using-principal-components-from-a-large-number-of-predictors",title:"Forecasting Using Principal Components From a Large Number of Predictors",titleZh:"大量预测变量的主成分方法",sourceTitle:"Forecasting Using Principal Components From a Large Number of Predictors",authors:"James H Stock · Mark W Watson",venue:"Journal of the American Statistical Association",year:"2002",kind:"paper",topic:"macro-finance",data:"macro panel; release lags; standardization; missing data",dataZh:"宏观面板；发布滞后；标准化；缺失数据",summary:{en:"Reduces a large information panel to factors for time-series analysis.",zh:"将大规模信息面板压缩为用于时间序列分析的因子。"},related:{datasets:["cn-macro-calendar","cn-yield-curve","global-macro-indicators"]},sources:[{label:"DOI",url:"https://doi.org/10.1198/016214502388618960"}]},{id:"the-real-value-of-china-s-stock-market",title:"The Real Value of China's Stock Market",titleZh:"中国股票市场的实际价值",sourceTitle:"The real value of China’s stock market",authors:"Jennifer N. Carpenter · Fangzhou Lu · Robert F. Whitelaw",venue:"Journal of Financial Economics",year:"2021",kind:"paper",topic:"a-share-market",data:"A-share prices; earnings; investment; institutional regimes",dataZh:"A股价格；盈利；投资；制度阶段",summary:{en:"Examines prices, future fundamentals, and corporate investment in China.",zh:"研究中国市场价格、未来基本面与企业投资之间的联系。"},related:{datasets:["cn-equity-daily","cn-company-master","cn-market-reference"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/j.jfineco.2020.08.012"}],readingNotes:[{title:{zh:"真实价值不只体现在指数涨跌",en:"Real value is more than an index's return"},body:{zh:"论文关心股票市场能否汇集有关企业未来盈利的信息，以及这些信息是否有助于投资配置。价格能预测未来盈利，与管理者从价格学到额外信息是两个问题。即使一个市场波动很大，也不能只据波动就判断它没有信息功能或资本配置作用。",en:"The paper asks whether prices aggregate information about future profits and whether that information helps allocate investment. Forecasting profits and revealing information beyond managers' private knowledge are distinct questions. High market volatility alone cannot establish the absence of either informational or allocative value."},reference:{url:"https://pages.stern.nyu.edu/~jcarpen0/pdfs/Carpenter%20Lu%20Whitelaw%20-%20The%20Real%20Value%20of%20China%27s%20Stock%20Market.pdf",label:{zh:"原文定位：2021年期刊版，第680–681页",en:"Source: 2021 journal article, pp. 680–681"}}},{title:{zh:"信息含量不是简单的市场相关性",en:"Informativeness is not simply market correlation"},body:{zh:"作者按年做横截面回归，用当前估值和盈利等解释未来盈利，再结合估值分散度衡量预测变化。这个指标不同于股票对市场回归的拟合度。特质波动可能同时包含信息和噪声，所以不能把“与大盘走势不同”直接解释为价格包含更多可靠信息。",en:"Annual cross-sectional regressions relate future profits to current valuations and profitability, combining a coefficient with valuation dispersion to measure predicted variation. This differs from a stock's market-model fit. Idiosyncratic variation can contain news and noise, so moving differently from the market does not automatically imply more reliable information."},reference:{url:"https://pages.stern.nyu.edu/~jcarpen0/pdfs/Carpenter%20Lu%20Whitelaw%20-%20The%20Real%20Value%20of%20China%27s%20Stock%20Market.pdf",label:{zh:"原文定位：2021年期刊版，第681页",en:"Source: 2021 journal article, pp. 681"}}},{title:{zh:"市值并非仅用流通A股计算",en:"Market value is not just tradable A-share capitalization"},body:{zh:"研究使用CSMAR的1995至2016年财务与行情资料，按年末A股价格乘以总股数构造市值，股数包括可交易A、B、H股及非流通股。这个特定口径不同于流通市值。若改用数据平台现成的市值字段，必须核对覆盖哪些股份类别。",en:"Using 1995–2016 CSMAR data, market value is year-end A-share price multiplied by total shares, including tradable A, B and H shares and nontradable shares. This is a specific convention, not free-float capitalization. A ready-made market-value field must be checked for which share classes it covers."},reference:{url:"https://pages.stern.nyu.edu/~jcarpen0/pdfs/Carpenter%20Lu%20Whitelaw%20-%20The%20Real%20Value%20of%20China%27s%20Stock%20Market.pdf",label:{zh:"原文定位：2021年期刊版，第682页",en:"Source: 2021 journal article, pp. 682"}}},{title:{zh:"价格、投资与盈利构成三组关系",en:"Prices, investment and profits form three tests"},body:{zh:"论文分别研究价格对未来盈利、价格对未来投资，以及投资对未来盈利的预测关系，投资以资本开支衡量。三组结果之间的联系依赖管理者追求价值最大化并从价格学习等假设。它们共同提供解释线索，但不是同一个回归，也不能相互替代。",en:"Separate tests connect prices to future profits, prices to future investment, and investment to future profits, with capital expenditure measuring investment. Connections among them rely on assumptions about value-maximizing managers and learning from prices. They provide related evidence but are not interchangeable regressions."},reference:{url:"https://pages.stern.nyu.edu/~jcarpen0/pdfs/Carpenter%20Lu%20Whitelaw%20-%20The%20Real%20Value%20of%20China%27s%20Stock%20Market.pdf",label:{zh:"原文定位：2021年期刊版，第681–682页",en:"Source: 2021 journal article, pp. 681–682"}}},{title:{zh:"国有股权比例影响比较方式",en:"State ownership changes the comparison"},body:{zh:"股权资料来自Wind，研究既允许系数随国有股权比例变化，也按40%的界限进行分组。国有企业可能承担盈利之外的目标，因而价值最大化假设的适用性不同。这个历史分组是论文的研究设计，不能当成所有场景通用的企业治理分类。",en:"Wind ownership data support coefficients varying with the state-owned equity fraction and a separate 40% split. State enterprises may pursue objectives beyond profit, changing the applicability of value-maximization assumptions. The historical grouping is a research design choice, not a universal corporate-governance classification."},reference:{url:"https://pages.stern.nyu.edu/~jcarpen0/pdfs/Carpenter%20Lu%20Whitelaw%20-%20The%20Real%20Value%20of%20China%27s%20Stock%20Market.pdf",label:{zh:"原文定位：2021年期刊版，第682页",en:"Source: 2021 journal article, pp. 682"}}},{title:{zh:"信息改善不等于未来回报保证",en:"Better information does not promise future returns"},body:{zh:"作者还讨论资本成本，并提醒用历史实现回报估计必要回报会受到意外市场表现影响。价格信息含量改善也不意味着投资者可以轻易取得超额收益。阅读结论时应区分市场的信息作用、企业融资成本和投资者回报这三种含义。",en:"The capital-cost discussion warns that realized returns used to estimate required returns may reflect unexpected market performance. Improved price informativeness does not promise easily attainable excess returns. Keep the market's information function, firms' financing costs and investors' realized outcomes separate."},reference:{url:"https://pages.stern.nyu.edu/~jcarpen0/pdfs/Carpenter%20Lu%20Whitelaw%20-%20The%20Real%20Value%20of%20China%27s%20Stock%20Market.pdf",label:{zh:"原文定位：2021年期刊版，第680–682页",en:"Source: 2021 journal article, pp. 680–682"}}}],readerLimits:{zh:"研究覆盖1995至2016年，区分价格信息、投资配置与资本成本。历史实现收益不等于预期收益，制度变化同期发生也不单独证明改革的因果效应。",en:"The 1995–2016 study separates price information, capital allocation and capital costs. Realized historical returns need not equal expected returns, and coincident institutional reforms do not alone establish a causal reform effect."}},{id:"law-finance-and-economic-growth-in-china",title:"Law, Finance, and Economic Growth in China",titleZh:"中国的法律、金融与经济增长",sourceTitle:"Law, finance, and economic growth in China",authors:"F ALLEN · J QIAN · M QIAN",venue:"Journal of Financial Economics",year:"2005",kind:"paper",topic:"a-share-market",data:"firm financing; ownership; regional institutions; growth",dataZh:"企业融资；所有权；区域制度；增长",summary:{en:"Studies formal and informal financing alongside economic development in China.",zh:"结合中国经济发展研究正式与非正式融资。"},related:{datasets:["cn-equity-daily","cn-company-master","cn-market-reference"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/j.jfineco.2004.06.010"}]},{id:"the-chinese-warrants-bubble",title:"The Chinese Warrants Bubble",titleZh:"中国权证泡沫",sourceTitle:"The Chinese Warrants Bubble",authors:"Wei Xiong · Jialin Yu",venue:"American Economic Review",year:"2011",kind:"paper",topic:"a-share-market",data:"warrant prices; underlying prices; turnover; expiry terms",dataZh:"权证价格；标的价格；换手率；到期条款",summary:{en:"Uses the warrant market to examine disagreement and speculative trading.",zh:"利用权证市场研究分歧与投机交易。"},related:{datasets:["cn-equity-daily","cn-company-master","cn-market-reference"]},sources:[{label:"DOI",url:"https://doi.org/10.1257/aer.101.6.2723"}]},{id:"short-sales-constraints-and-price-discovery-evidence-from-the-hong-kong-market",title:"Short-Sales Constraints and Price Discovery: Evidence from the Hong Kong Market",titleZh:"卖空约束与价格发现：香港市场证据",sourceTitle:"Short‐Sales Constraints and Price Discovery: Evidence from the Hong Kong Market",authors:"ERIC C. CHANG · JOSEPH W. CHENG · YINGHUI YU",venue:"The Journal of Finance",year:"2007",kind:"paper",topic:"a-share-market",data:"eligibility lists; effective dates; returns; volumes",dataZh:"资格名单；生效日期；收益；成交量",summary:{en:"Uses changes in short-sale eligibility to study constraints and price discovery.",zh:"利用卖空资格变化研究交易约束与价格发现。"},related:{datasets:["cn-equity-daily","cn-company-master","cn-market-reference"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/j.1540-6261.2007.01270.x"}]},{id:"differences-of-opinion-short-sales-constraints-and-market-crashes",title:"Differences of Opinion, Short-Sales Constraints, and Market Crashes",titleZh:"意见分歧、卖空约束与市场崩跌",sourceTitle:"Differences of Opinion, Short-Sales Constraints, and Market Crashes",authors:"Harrison Hong · Jeremy C. Stein",venue:"Review of Financial Studies",year:"2003",kind:"paper",topic:"a-share-market",data:"turnover; return distributions; disagreement proxies",dataZh:"换手率；收益分布；分歧代理",summary:{en:"Models how disagreement and short-sale restrictions affect information in prices.",zh:"建模分析分歧与卖空限制如何影响价格中的信息。"},related:{datasets:["cn-equity-daily","cn-company-master","cn-market-reference"]},sources:[{label:"DOI",url:"https://doi.org/10.1093/rfs/hhg006"}]},{id:"speculative-trading-and-stock-prices-evidence-from-chinese-a-b-share-premia",title:"Speculative Trading and Stock Prices: Evidence from Chinese A-B Share Premia",titleZh:"投机交易与中国A/B股溢价",sourceTitle:"Speculative Trading and Stock Prices: Evidence from Chinese A-B Share Premia",authors:"Jianping Mei · Jose Scheinkman · Wei Xiong",venue:"National Bureau of Economic Research",year:"2005",kind:"working-paper",topic:"a-share-market",data:"A/B paired shares; FX; turnover; ownership restrictions",dataZh:"A/B配对股份；汇率；换手率；持有约束",summary:{en:"Studies price differences for related share classes under segmented participation.",zh:"研究参与者分割条件下相关股份类别的价格差异。"},related:{datasets:["cn-equity-daily","cn-company-master","cn-market-reference"]},sources:[{label:"DOI",url:"https://doi.org/10.3386/w11362"}]},{id:"how-does-government-ownership-affect-firm-performance-evidence-from-china-s-privatization-experience",title:"How Does Government Ownership Affect Firm Performance? Evidence from China’s Privatization Experience",titleZh:"政府所有权如何影响企业绩效？中国民营化证据",sourceTitle:"How Does Government Ownership Affect Firm Performance? Evidence from China’s Privatization Experience",authors:"Qian Sun · Wilson H. S. Tong · Jing Tong",venue:"Journal of Business Finance & Accounting",year:"2002",kind:"paper",topic:"a-share-market",data:"state ownership; firm financials; listing and reform dates",dataZh:"国有持股；企业财务；上市与改革日期",summary:{en:"Examines state ownership in relation to the characteristics of listed firms.",zh:"考察国家所有权与上市企业特征的关系。"},related:{datasets:["cn-equity-daily","cn-company-master","cn-market-reference"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/1468-5957.00422"}]},{id:"politically-connected-ceos-corporate-governance-and-post-ipo-performance-of-china-s-newly-partially-privatized-firms",title:"Politically Connected CEOs, Corporate Governance, and Post-IPO Performance of China's Newly Partially Privatized Firms",titleZh:"政治关联、治理与中国部分私有化企业",sourceTitle:"Politically connected CEOs, corporate governance, and Post-IPO performance of China's newly partially privatized firms☆",authors:"J FAN · T WONG · T ZHANG",venue:"Journal of Financial Economics",year:"2007",kind:"paper",topic:"a-share-market",data:"CEO biographies; IPO dates; ownership; financial statements",dataZh:"高管履历；IPO日期；所有权；财务报表",summary:{en:"Studies executive backgrounds and governance around partial privatization IPOs.",zh:"研究部分私有化上市过程中的高管背景与公司治理。"},related:{datasets:["cn-equity-daily","cn-company-master","cn-market-reference"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/j.jfineco.2006.03.008"}]},{id:"the-effects-of-political-connections-and-state-ownership-on-corporate-litigation-in-china",title:"The Effects of Political Connections and State Ownership on Corporate Litigation in China",titleZh:"政治关联、国有股权与中国企业诉讼",sourceTitle:"The Effects of Political Connections and State Ownership on Corporate Litigation in China",authors:"Michael Firth · Oliver M. Rui · Wenfeng Wu",venue:"The Journal of Law and Economics",year:"2011",kind:"paper",topic:"a-share-market",data:"litigation records; ownership; political ties; firm controls",dataZh:"诉讼记录；所有权；政治关联；企业控制变量",summary:{en:"Examines political connections and ownership in corporate litigation outcomes.",zh:"结合政治关联与所有权结构分析企业诉讼结果。"},related:{datasets:["cn-equity-daily","cn-company-master","cn-market-reference"]},sources:[{label:"DOI",url:"https://doi.org/10.1086/659261"}]},{id:"asset-growth-and-the-cross-section-of-stock-returns",title:"Asset Growth and the Cross-Section of Stock Returns",titleZh:"资产增长与股票收益横截面",sourceTitle:"Asset Growth and the Cross‐Section of Stock Returns",authors:"MICHAEL J. COOPER · HUSEYIN GULEN · MICHAEL J. SCHILL",venue:"The Journal of Finance",year:"2008",kind:"paper",topic:"corporate-fundamentals",data:"total assets; financial statement dates; returns",dataZh:"总资产；财报日期；收益",summary:{en:"Studies differences in future returns across firms with different asset growth.",zh:"比较资产增长不同的企业之间的后续收益。"},related:{datasets:["cn-pit-fundamentals","cn-company-master"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/j.1540-6261.2008.01370.x"}]},{id:"the-investment-capm",title:"The Investment CAPM",titleZh:"投资资本资产定价模型",sourceTitle:"The Investment CAPM",authors:"Lu Zhang",venue:"European Financial Management",year:"2017",kind:"paper",topic:"asset-pricing",data:"investment; profitability; market equity; asset returns",dataZh:"投资；盈利能力；市值；资产收益",summary:{en:"Reviews a production-based perspective linking investment and expected returns.",zh:"综述连接企业投资与预期收益的生产侧定价视角。"},related:{datasets:["cn-equity-daily","cn-pit-fundamentals"],recipes:["pit-fundamentals-panel"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/eufm.12129"}]},{id:"stock-market-liberalization-economic-reform-and-emerging-market-equity-prices",title:"Stock Market Liberalization, Economic Reform, and Emerging Market Equity Prices",titleZh:"股市开放、经济改革与新兴市场股价",sourceTitle:"Stock Market Liberalization, Economic Reform, and Emerging Market Equity Prices",authors:"Peter Blair Henry",venue:"The Journal of Finance",year:"2000",kind:"paper",topic:"a-share-market",data:"liberalization dates; market indices; reform controls",dataZh:"开放日期；市场指数；改革控制变量",summary:{en:"Examines market liberalization events together with broader economic reforms.",zh:"结合更广泛经济改革研究市场开放事件。"},related:{datasets:["cn-equity-daily","cn-company-master","cn-market-reference"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/0022-1082.00219"}]},{id:"does-financial-liberalization-spur-growth",title:"Does Financial Liberalization Spur Growth?",titleZh:"金融开放是否促进增长？",sourceTitle:"Does financial liberalization spur growth?",authors:"G BEKAERT · C HARVEY · C LUNDBLAD",venue:"Journal of Financial Economics",year:"2005",kind:"paper",topic:"a-share-market",data:"country panels; liberalization dates; macro controls",dataZh:"国家面板；开放日期；宏观控制变量",summary:{en:"Studies capital-market liberalization and growth using cross-country panels.",zh:"利用跨国面板研究资本市场开放与增长。"},related:{datasets:["cn-equity-daily","cn-company-master","cn-market-reference"]},sources:[{label:"DOI",url:"https://doi.org/10.1016/j.jfineco.2004.05.007"}]},{id:"retail-and-institutional-investor-trading-behaviors-evidence-from-china",title:"Retail and Institutional Investor Trading Behaviors: Evidence from China",titleZh:"中国散户与机构投资者交易行为",sourceTitle:"Retail and Institutional Investor Trading Behaviors: Evidence from China",authors:"Lin Tan · Xiaoyan Zhang · Xinran Zhang",venue:"Annual Review of Financial Economics",year:"2024",kind:"paper",topic:"a-share-market",data:"investor classifications; trades; information and policy events",dataZh:"投资者分类；成交；信息与政策事件",summary:{en:"Reviews heterogeneous investor behavior within China's institutional setting.",zh:"综述中国制度环境下不同投资者的行为差异。"},related:{datasets:["cn-equity-daily","cn-company-master","cn-market-reference"]},sources:[{label:"DOI",url:"https://doi.org/10.1146/annurev-financial-082123-110132"}]},{id:"the-economics-of-cryptocurrencies-bitcoin-and-beyond",title:"The Economics of Cryptocurrencies—Bitcoin and Beyond",titleZh:"加密货币经济学：比特币及其他",sourceTitle:"The Economics of Cryptocurrencies – Bitcoin and Beyond",authors:"Jonathan Chiu · Thorsten V. Koeppl",venue:"SSRN",year:"2017",kind:"working-paper",topic:"crypto-markets",data:"transaction fees; settlement delays; protocol parameters",dataZh:"交易费用；结算延迟；协议参数",summary:{en:"Models payment frictions and the economic design of cryptocurrency systems.",zh:"建模分析支付摩擦与加密货币系统的经济设计。"},related:{datasets:["crypto-binance-spot-5m","crypto-binance-derivatives"]},sources:[{label:"DOI",url:"https://doi.org/10.2139/ssrn.3048124"}]},{id:"risks-and-returns-of-cryptocurrency",title:"Risks and Returns of Cryptocurrency",titleZh:"加密货币的风险与收益",sourceTitle:"Risks and Returns of Cryptocurrency",authors:"Yukun Liu · Aleh Tsyvinski",venue:"The Review of Financial Studies",year:"2021",kind:"paper",topic:"crypto-markets",data:"crypto prices; network measures; attention; macro factors",dataZh:"加密价格；网络指标；关注度；宏观因子",summary:{en:"Studies cryptocurrency return variation and compares it with traditional asset exposures.",zh:"研究加密货币收益变化，并与传统资产暴露比较。"},related:{datasets:["crypto-binance-spot-5m","crypto-binance-derivatives"]},sources:[{label:"DOI",url:"https://doi.org/10.1093/rfs/hhaa113"}],readingNotes:[{title:{zh:"先看这份早期版本研究了谁",en:"Start with the early draft's actual assets"},body:{zh:"这份工作论文研究比特币、Ripple与以太坊，而不是今日所有代币。三条价格序列起点不同，分别始于2011、2013和2015年，均结束于2018年5月31日。不同长度会改变共同检验窗口，不能把三种资产的结果视为同一个完整市场面板。",en:"The draft studies Bitcoin, Ripple and Ethereum, not today's full token universe. Price histories begin in 2011, 2013 and 2015 respectively and end on May 31, 2018. Different lengths affect common testing windows, so the three series should not be treated as a balanced panel of the entire market."},reference:{url:"https://www.nber.org/system/files/working_papers/w24877/w24877.pdf",label:{zh:"原文定位：2018年8月工作论文，第2–4页",en:"Source: August 2018 working paper, pp. 2–4"}}},{title:{zh:"传统因子是比较基准，不是独立性证明",en:"Traditional factors are benchmarks, not proof of independence"},body:{zh:"作者比较股票因子、货币、贵金属与宏观变量的解释力，并指出许多传统解释在该样本中较弱。但文中仍有个别资产与因子的关联，不能把总体讨论翻译成“加密资产与一切传统市场无关”。统计上未检出稳定关系，也不等于关系永远不存在。",en:"Equity factors, currencies, precious metals and macro variables serve as comparison benchmarks. Many conventional explanations are weak in this sample, but asset-specific associations remain. Failure to detect a stable pattern does not establish permanent independence from every traditional market or economic variable."},reference:{url:"https://www.nber.org/system/files/working_papers/w24877/w24877.pdf",label:{zh:"原文定位：2018年8月工作论文，第2–3页",en:"Source: August 2018 working paper, pp. 2–3"}}},{title:{zh:"关注度和情绪方向是两回事",en:"Attention is different from emotional tone"},body:{zh:"Google搜索和包含Bitcoin的Twitter发帖数量被用作关注度代理，另有与黑客事件相关的搜索比率考察负面关注。搜索变多可能源于担忧或兴趣，所以不能直接解读为看多。关键词、分母、采样频率和时间对齐都会改变这个指标的含义。",en:"Google searches and Twitter post counts mentioning Bitcoin proxy for attention, while a hack-related search ratio examines negative attention. More searches can reflect concern or curiosity rather than optimism. Keywords, denominators, sampling frequency and time alignment are therefore part of the measure's meaning."},reference:{url:"https://www.nber.org/system/files/working_papers/w24877/w24877.pdf",label:{zh:"原文定位：2018年8月工作论文，第3–4页",en:"Source: August 2018 working paper, pp. 3–4"}}},{title:{zh:"钱包数量不是现金分红",en:"Wallet counts are not cash dividends"},body:{zh:"草稿用价格相对于钱包用户数量的比值构造带引号的“价格股息比”。这里的钱包用户数量只是采用程度的代理，不是资产向持有人支付的现金流。论文在这份版本中未发现该指标的预测力，也不能据此推导出所有网络采用指标都无效。",en:"The draft's quoted price-to-dividend proxy divides price by wallet-user counts. Those counts proxy for adoption rather than cash distributions to holders. The reported lack of predictive power for this construction does not establish that every network-adoption measure is uninformative."},reference:{url:"https://www.nber.org/system/files/working_papers/w24877/w24877.pdf",label:{zh:"原文定位：2018年8月工作论文，第3–4页",en:"Source: August 2018 working paper, pp. 3–4"}}},{title:{zh:"比较资产时还要比较数据窗口",en:"Comparisons inherit different data windows"},body:{zh:"加密价格来自CoinDesk，而股票、汇率、债券与其他比较序列来自不同资料库，其中一些更早结束。完整研究需要明确每项回归实际使用的交集窗口。某一个交易所的现货数据不能自动替代这些多来源序列，更不能补出没有观察到的历史。",en:"Crypto prices come from CoinDesk, whereas equities, currencies, bonds and other comparison series use different databases, some ending earlier. Each regression needs its actual overlapping window. A single venue's spot series cannot silently replace the multi-source inputs or create unobserved history."},reference:{url:"https://www.nber.org/system/files/working_papers/w24877/w24877.pdf",label:{zh:"原文定位：2018年8月工作论文，第4–5页",en:"Source: August 2018 working paper, pp. 4–5"}}},{title:{zh:"预测关联与交易结果之间仍有距离",en:"Predictive associations are not trading outcomes"},body:{zh:"草稿讨论动量与注意力变量对后续收益的历史预测关系。这样的统计关联与扣除交易成本后、经过样本外检验的投资表现是不同问题。把论文用于新数据时，需要重新处理观察时点、样本变化与估计不确定性，不能直接沿用早期样本的结论。",en:"The draft discusses historical return predictability from momentum and attention. Such associations are distinct from out-of-sample investment performance after trading costs. Applying the questions to new data requires renewed timing, sample and estimation checks rather than carrying the early findings forward as current trading results."},reference:{url:"https://www.nber.org/system/files/working_papers/w24877/w24877.pdf",label:{zh:"原文定位：2018年8月工作论文，第2–4页",en:"Source: August 2018 working paper, pp. 2–4"}}}],readerLimits:{zh:"导读依据2018年工作论文，题录保留2021年期刊版。早期三种资产的结果不代表当前整个加密市场；历史注意力关联也不是可执行收益保证。",en:"This guide uses the 2018 working paper and retains the 2021 journal citation. Its early three-asset sample does not represent the entire current crypto market, and historical attention associations are not executable return guarantees."}},{id:"common-risk-factors-in-cryptocurrency",title:"Common Risk Factors in Cryptocurrency",titleZh:"加密货币中的共同风险因子",sourceTitle:"Common Risk Factors in Cryptocurrency",authors:"YUKUN LIU · ALEH TSYVINSKI · XI WU",venue:"The Journal of Finance",year:"2022",kind:"paper",topic:"crypto-markets",data:"multi-token prices; capitalization; turnover; delistings",dataZh:"多代币价格；市值；换手率；退市记录",summary:{en:"Organizes cross-sectional cryptocurrency returns using common characteristics.",zh:"利用共同特征组织加密资产收益横截面。"},related:{datasets:["crypto-binance-spot-5m","crypto-binance-derivatives"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/jofi.13119"}]},{id:"is-bitcoin-really-un-tethered",title:"Is Bitcoin Really Un-Tethered?",titleZh:"比特币与稳定币发行关系研究",sourceTitle:"Is Bitcoin Really Untethered?",authors:"JOHN M. GRIFFIN · AMIN SHAMS",venue:"The Journal of Finance",year:"2020",kind:"paper",topic:"crypto-markets",data:"wallet flows; stablecoin issuance; exchange prices; timestamps",dataZh:"钱包流量；稳定币发行；场所价格；时间戳",summary:{en:"Examines blockchain flows, stablecoin issuance, and exchange price movements.",zh:"研究链上流量、稳定币发行与交易所价格变化。"},related:{datasets:["crypto-binance-spot-5m","crypto-binance-derivatives"]},sources:[{label:"DOI",url:"https://doi.org/10.1111/jofi.12903"}]},{id:"bitcoin-economics-technology-and-governance",title:"Bitcoin: Economics, Technology, and Governance",titleZh:"比特币：经济、技术与治理",sourceTitle:"Bitcoin: Economics, Technology, and Governance",authors:"Rainer Böhme · Nicolas Christin · Benjamin Edelman · Tyler Moore",venue:"Journal of Economic Perspectives",year:"2015",kind:"paper",topic:"crypto-markets",data:"protocol rules; transaction records; mining incentives",dataZh:"协议规则；交易记录；挖矿激励",summary:{en:"Reviews Bitcoin's technical mechanisms and economic governance questions.",zh:"综述比特币技术机制与经济治理问题。"},related:{datasets:["crypto-binance-spot-5m","crypto-binance-derivatives"]},sources:[{label:"DOI",url:"https://doi.org/10.1257/jep.29.2.213"}],readingNotes:[{title:{zh:"先区分协议与价格",en:"Separate protocol from price"},body:{zh:"Böhme、Christin、Edelman与Moore面向非技术读者介绍比特币的设计、经济机制与治理。文章把支付协议、分布式记录和现实金融系统的连接放在一起，而不是从价格曲线出发给资产估值。",en:"Böhme, Christin, Edelman and Moore introduce Bitcoin's design, economics and governance to nontechnical readers. They connect a payment protocol and distributed records to the conventional financial system rather than deriving value from a price chart."}},{title:{zh:"签名解决授权，账本解决记录",en:"Signatures authorize; the ledger records"},body:{zh:"作者草稿将两个问题分开：数字签名帮助验证支出的授权，分布式交易记录帮助追踪输入与此前输出的联系。签名并不负责隐藏整份交易历史，也不证明现实中的法律身份。理解这一区别，才能避免把“使用密码学”直接理解成所有交易内容都被加密保密。",en:"The author draft separates authorization through digital signatures from recording transactions whose inputs refer to earlier outputs. A signature does not conceal the entire transaction history or establish a real-world legal identity. Cryptographic verification and secrecy are therefore different properties, not interchangeable descriptions of the system."},reference:{url:"https://www.benedelman.org/publications/bitcoin-15jul2014.pdf",label:{zh:"2014年作者草稿：Enabling Technologies / The Role of Cryptography",en:"2014 author draft: Enabling Technologies / The Role of Cryptography"}}},{title:{zh:"机制不能脱离参与者",en:"Mechanisms depend on participants"},body:{zh:"综述讨论交易记录、参与激励、发行路径和权力集中等问题。即使规则在协议中写明，仍然需要理解谁运行系统、谁提供中介服务，以及参与者怎样响应激励，不能把技术描述当作完整经济解释。",en:"The overview discusses transaction records, participation incentives, issuance and concentration. Protocol rules alone do not fully explain who operates the system, provides intermediation or responds to incentives."}},{title:{zh:"隐私与去中心化都有边界",en:"Privacy and decentralization have limits"},body:{zh:"作者强调灵活性、隐私和监管相关特征并非没有限制。本站建议把链上可见信息与链下身份、交易所账户和托管关系分开，避免把公开记录解释成匿名保证，或把协议特征套用到所有服务商。",en:"The authors emphasize limits to flexibility, privacy and regulatory claims. Distinguish on-chain records from off-chain identity, exchange accounts and custody. Public records do not establish anonymity or identical intermediary behavior."}},{title:{zh:"激励机制同时带来资源成本",en:"Participation incentives also consume resources"},body:{zh:"草稿把工作量证明与维护账本的激励联系起来：同一机制既提高伪造参与的成本，也奖励记录维护者，但计算活动消耗现实资源。阅读重点是激励、竞争与成本之间的关系；文中的历史奖励和能耗数字不能作为今天的参数，更不能只由交易价格判断网络运行状况。",en:"The draft links proof of work to incentives for maintaining the shared record: the mechanism makes fabricated participation costly and rewards record maintenance, while computation consumes resources. The useful reading is about incentives, competition and costs. Historical reward and energy figures are not current parameters, and exchange prices alone do not describe network operation."},reference:{url:"https://www.benedelman.org/publications/bitcoin-15jul2014.pdf",label:{zh:"2014年作者草稿：Incentives for Participation",en:"2014 author draft: Incentives for Participation"}}},{title:{zh:"再分别阅读采用模型与市场数据",en:"Then study adoption and markets"},body:{zh:"这篇提供概念背景；Tokenomics讨论平台采用与价值的模型，跨交易所研究讨论交易场所分割。三个对象相关但不能互换：交易量不是用户数，交易所价格也不是协议全部经济活动。",en:"This is conceptual background. Tokenomics models platform adoption, while cross-exchange research studies venue segmentation. Trading volume, users and protocol activity are related but not interchangeable objects."}}],readerLimits:{zh:"导读结合2014年作者草稿与2015年综述摘要，仅解释历史设计思路，不提供当前协议、安全、监管或投资判断。",en:"The guide combines the 2014 author draft with the 2015 overview abstract to explain historical design ideas, not current protocol, security, regulatory or investment conditions."}},{id:"some-simple-economics-of-the-blockchain",title:"Some Simple Economics of the Blockchain",titleZh:"区块链的基本经济学",sourceTitle:"Some simple economics of the blockchain",authors:"Christian Catalini · Joshua S. Gans",venue:"Communications of the ACM",year:"2020",kind:"paper",topic:"crypto-markets",data:"verification workflows; network structure; protocol costs",dataZh:"验证流程；网络结构；协议成本",summary:{en:"Separates verification and networking costs in blockchain applications.",zh:"区分区块链应用中的验证成本与网络成本。"},related:{datasets:["crypto-binance-spot-5m","crypto-binance-derivatives"]},sources:[{label:"DOI",url:"https://doi.org/10.1145/3359552"}]},{id:"blockchain-economics",title:"Blockchain Economics",titleZh:"区块链经济学",sourceTitle:"Blockchain Economics",authors:"Joseph Abadi · Markus Brunnermeier",venue:"Working paper (Federal Reserve Bank of Philadelphia)",year:"2022",kind:"working-paper",topic:"crypto-markets",data:"consensus assumptions; transaction records; participation costs",dataZh:"共识假设；交易记录；参与成本",summary:{en:"Models tradeoffs in distributed recordkeeping and incentive design.",zh:"建模分析分布式记账与激励设计的权衡。"},related:{datasets:["crypto-binance-spot-5m","crypto-binance-derivatives"]},sources:[{label:"DOI",url:"https://doi.org/10.21799/frbp.wp.2022.15"}]},{id:"sok-research-perspectives-and-challenges-for-bitcoin-and-cryptocurrencies",title:"SoK: Research Perspectives and Challenges for Bitcoin and Cryptocurrencies",titleZh:"比特币与加密货币的研究视角和挑战",sourceTitle:"SoK: Research Perspectives and Challenges for Bitcoin and Cryptocurrencies",authors:"Joseph Bonneau · Andrew Miller · Jeremy Clark · Arvind Narayanan · Joshua A. Kroll · Edward W. Felten",venue:"2015 IEEE Symposium on Security and Privacy",year:"2015",kind:"paper",topic:"crypto-markets",data:"protocol specifications; network observations; threat models",dataZh:"协议规范；网络观测；威胁模型",summary:{en:"Systematizes cryptocurrency security, consensus, and privacy research challenges.",zh:"系统整理加密货币安全、共识与隐私的研究挑战。"},related:{datasets:["crypto-binance-spot-5m","crypto-binance-derivatives"]},sources:[{label:"DOI",url:"https://doi.org/10.1109/sp.2015.14"}]},{id:"decentralized-finance-on-blockchain-and-smart-contract-based-financial-markets",title:"Decentralized Finance: On Blockchain- and Smart Contract-Based Financial Markets",titleZh:"去中心化金融与智能合约市场",sourceTitle:"Decentralized Finance: On Blockchain- and Smart Contract-Based Financial Markets",authors:"Fabian Schär",venue:"Review",year:"2021",kind:"paper",topic:"crypto-markets",data:"protocol contracts; collateral; liquidity pools; governance",dataZh:"协议合约；抵押物；流动性池；治理",summary:{en:"Surveys DeFi building blocks and the risks of composable smart-contract services.",zh:"综述DeFi构件与可组合智能合约服务的风险。"},related:{datasets:["crypto-binance-spot-5m","crypto-binance-derivatives"]},sources:[{label:"DOI",url:"https://doi.org/10.20955/r.103.153-74"}]},{id:"defi-risks-and-the-decentralisation-illusion",title:"DeFi Risks and the Decentralisation Illusion",titleZh:"DeFi风险与去中心化假象",sourceTitle:"DeFi risks and the decentralisation illusion",authors:"Sirio Aramonte · Wenqian Huang · Andreas Schrimpf",venue:"BIS Quarterly Review",year:"2021",kind:"industry-research",topic:"crypto-markets",data:"protocol governance; leverage; liquidity; token ownership",dataZh:"协议治理；杠杆；流动性；代币所有权",summary:{en:"Examines concentration, governance, and financial fragilities in DeFi.",zh:"研究DeFi中的集中度、治理与金融脆弱性。"},related:{datasets:["crypto-binance-spot-5m","crypto-binance-derivatives"]},sources:[{label:"BIS Quarterly Review",url:"https://www.bis.org/publ/qtrpdf/r_qt2112b.htm"}]},{id:"taming-wildcat-stablecoins",title:"Taming Wildcat Stablecoins",titleZh:"稳定币制度与监管设计",sourceTitle:"Taming Wildcat Stablecoins",authors:"Gary B. Gorton · Jeffery Y. Zhang",venue:"SSRN",year:"2021",kind:"working-paper",topic:"crypto-markets",data:"reserve disclosures; redemption terms; issuance; prices",dataZh:"储备披露；赎回条款；发行；价格",summary:{en:"Compares stablecoin arrangements with historical private-money institutions.",zh:"将稳定币安排与历史私人货币制度比较。"},related:{datasets:["crypto-binance-spot-5m","crypto-binance-derivatives"]},sources:[{label:"DOI",url:"https://doi.org/10.2139/ssrn.3888752"}]},{id:"an-empirical-study-of-defi-liquidations-incentives-risks-and-instabilities",title:"An Empirical Study of DeFi Liquidations: Incentives, Risks, and Instabilities",titleZh:"DeFi清算的激励、风险与不稳定性",sourceTitle:"An empirical study of DeFi liquidations",authors:"Kaihua Qin · Liyi Zhou · Pablo Gamito · Philipp Jovanovic · Arthur Gervais",venue:"Proceedings of the 21st ACM Internet Measurement Conference",year:"2021",kind:"paper",topic:"crypto-markets",data:"lending positions; collateral; oracle prices; liquidations",dataZh:"借贷头寸；抵押物；预言机价格；清算",summary:{en:"Studies liquidation mechanisms using on-chain lending observations.",zh:"利用链上借贷观测研究清算机制。"},related:{datasets:["crypto-binance-spot-5m","crypto-binance-derivatives"]},sources:[{label:"DOI",url:"https://doi.org/10.1145/3487552.3487811"}]},{id:"flash-boys-2-0-frontrunning-in-decentralized-exchanges-miner-extractable-value-and-consensus-instability",title:"Flash Boys 2.0: Frontrunning in Decentralized Exchanges, Miner Extractable Value, and Consensus Instability",titleZh:"去中心化交易所抢跑、MEV与共识稳定性",sourceTitle:"Flash Boys 2.0: Frontrunning in Decentralized Exchanges, Miner Extractable Value, and Consensus Instability",authors:"Philip Daian · Steven Goldfeder · Tyler Kell · Yunqi Li · Xueyuan Zhao · Iddo Bentov · Lorenz Breidenbach · Ari Juels",venue:"2020 IEEE Symposium on Security and Privacy (SP)",year:"2020",kind:"paper",topic:"crypto-markets",data:"mempool observations; transaction ordering; gas bids; blocks",dataZh:"内存池观测；交易排序；Gas竞价；区块",summary:{en:"Documents ordering incentives and transaction extraction in decentralized exchanges.",zh:"研究去中心化交易所中的交易排序激励与价值提取。"},related:{datasets:["crypto-binance-spot-5m","crypto-binance-derivatives"]},sources:[{label:"DOI",url:"https://doi.org/10.1109/sp40000.2020.00040"}]},{id:"sok-decentralized-finance-defi",title:"SoK: Decentralized Finance (DeFi)",titleZh:"去中心化金融知识体系综述",sourceTitle:"SoK: Decentralized Finance (DeFi)",authors:"Sam Werner · Daniel Perez · Lewis Gudgeon · Ariah Klages-Mundt · Dominik Harz · William Knottenbelt",venue:"Proceedings of the 4th ACM Conference on Advances in Financial Technologies",year:"2022",kind:"paper",topic:"crypto-markets",data:"protocol taxonomy; smart contracts; attack and risk cases",dataZh:"协议分类；智能合约；攻击与风险案例",summary:{en:"Organizes DeFi protocols, security assumptions, and economic risks into a taxonomy.",zh:"系统整理DeFi协议、安全假设与经济风险。"},related:{datasets:["crypto-binance-spot-5m","crypto-binance-derivatives"]},sources:[{label:"DOI",url:"https://doi.org/10.1145/3558535.3559780"}]},{id:"cryptocurrency-pump-and-dump-schemes",title:"Cryptocurrency Pump-and-Dump Schemes",titleZh:"加密货币拉升出货事件研究",sourceTitle:"Cryptocurrency Pump-and-Dump Schemes",authors:"Tao Li · Donghwa Shin · Baolian Wang",venue:"Journal of Financial and Quantitative Analysis",year:"2025",kind:"paper",topic:"crypto-markets",data:"public messages; event timestamps; prices; volumes",dataZh:"公开消息；事件时间戳；价格；成交量",summary:{en:"Studies coordinated promotion episodes using messages and market observations.",zh:"结合消息与市场观测研究协同推广事件。"},related:{datasets:["crypto-binance-spot-5m","crypto-binance-derivatives"]},sources:[{label:"DOI",url:"https://doi.org/10.1017/s0022109025000201"}]},{id:"tokenomics-dynamic-adoption-and-valuation",title:"Tokenomics: Dynamic Adoption and Valuation",titleZh:"代币经济：动态采用与估值",sourceTitle:"Tokenomics: Dynamic Adoption and Valuation",authors:"Lin William Cong · Ye Li · Neng Wang",venue:"The Review of Financial Studies",year:"2021",kind:"paper",topic:"crypto-markets",data:"platform users; token supply; transaction demand; prices",dataZh:"平台用户；代币供给；交易需求；价格",summary:{en:"Models interactions between platform adoption, token usage, and valuation.",zh:"建模分析平台采用、代币使用与估值之间的相互关系。"},related:{datasets:["crypto-binance-spot-5m","crypto-binance-derivatives"]},sources:[{label:"DOI",url:"https://doi.org/10.1093/rfs/hhaa089"}],readingNotes:[{title:{zh:"代币价格与用户采用互相影响",en:"Token value and adoption interact"},body:{zh:"Cong、Li与Wang研究作为平台支付媒介的代币：更多用户可能提高平台交易价值，而预期代币升值又可能改变用户现在是否加入。它把采用决策与代币价格放在同一个动态模型里，不把用户数量简单当作外生估值倍数。",en:"Cong, Li and Wang model tokens used as platform payment media. More users can raise transaction utility, while expected token appreciation can affect today's participation. Adoption and valuation are jointly determined rather than treating user count as an external valuation multiple."}},{title:{zh:"理论对象，不是币价样本",en:"A theoretical economy, not a price sample"},body:{zh:"模型中的用户有不同交易需求，平台生产率随机变化，代币供给在基准设定中固定。用户决定是否承担参与成本，以及持有多少支付余额。文中提到具体平台是帮助解释机制，不是对这些币做出的样本回归或价格目标。",en:"Users differ in transaction needs, platform productivity is stochastic and baseline token supply is fixed. Agents choose participation and payment balances. Named platforms illustrate the mechanism; they are not an empirical price-regression sample or valuation targets."},reference:{url:"https://nengwang-economics.com/publications/papers/Cong_Li_Wang_RFS_2020_authorcopy.pdf",label:{zh:"作者版本第1节：平台经济模型",en:"Author copy §1: platform-economy model"}}},{title:{zh:"持有成本是关键连接",en:"Carrying cost connects the decisions"},body:{zh:"持有支付媒介意味着放弃其他资产的回报。在模型中，预期代币升值可以抵消部分机会成本，鼓励更早采用；用户增长又增加代币需求。这个反馈需要平台交易效用、网络效应与预期共同成立，不是仅靠限制发行数量就能推出价格上涨。",en:"Payment balances forgo returns on other assets. Expected token appreciation can offset part of that opportunity cost and encourage earlier adoption, while user growth increases demand. The feedback depends on transaction utility, network effects and expectations—not scarcity alone."}},{title:{zh:"模型给出的条件性结论",en:"Conditional model implications"},body:{zh:"作者描述了S形采用路径，以及在相同生产率过程下，代币平台相较无代币平台更快、更稳定的采用。网络效应也可能放大生产率冲击对价格的影响。因此，“采用更稳定”与“价格更稳定”不能混为一谈，更不能据此断言现实项目必然成功。",en:"The model produces S-shaped adoption and, relative to a tokenless platform with the same productivity process, accelerated and more stable participation. Network effects can also amplify price responses to productivity shocks. Stable adoption and stable prices are different claims."}},{title:{zh:"阅读时对照两种平台",en:"Compare like-for-like platforms"},body:{zh:"建议先读第1节，列出用户效用、参与成本、供给与贴现假设；随后比较有代币与使用普通计价商品的平台。尤其注意代币的权利：本文交易媒介并不等同于代表发行人现金流的证券型代币。用不同权利的资产替代，会改变模型问题。",en:"Start with utility, participation cost, supply and discounting assumptions in Section 1, then compare token and numeraire-settled platforms. Rights matter: transaction tokens here are distinct from claims on issuer cash flows. Substituting a different asset changes the model's question."},reference:{url:"https://nengwang-economics.com/publications/papers/Cong_Li_Wang_RFS_2020_authorcopy.pdf",label:{zh:"作者版本引言：代币范围与比较思路",en:"Author-copy introduction: token scope and comparison"}}},{title:{zh:"怎样准备后续观察材料",en:"Preparing subsequent observations"},body:{zh:"编辑建议：如果要研究现实平台，应分别定义真实用户、交易用途、代币余额和供给变更，并检查激励活动或机器人是否扭曲计数。交易所价格与成交量只能描述交易活动，不能替代平台采用和效用；本导读不输出估值、收益预测或买卖建议。",en:"Editorial application: define users, transaction uses, balances and supply changes separately, checking incentive-driven or automated activity. Exchange prices and volumes cannot substitute for platform adoption or utility. This guide produces no valuation, return forecast or trading recommendation."}}],readerLimits:{zh:"导读依据2020年作者版本；书目保留2021年正式发表身份。理论比较不等于对现实代币的实证验证。",en:"The guide uses the 2020 author copy while retaining the 2021 publication identity. Theoretical comparisons are not empirical validation of live tokens."}}],i=[{id:"pit-fundamentals",title:{en:"Point-in-time fundamentals",zh:"时点一致财务"},titles:["The Cross-Section of Expected Stock Returns","Do Stock Prices Fully Reflect Information in Accruals and Cash Flows about Future Earnings?","The Quality of Accruals and Earnings: The Role of Accrual Estimation Errors","Replicating Anomalies"]},{id:"market-microstructure",title:{en:"A-share microstructure",zh:"A股微观结构"},titles:["Continuous Auctions and Insider Trading","Intraday Information Efficiency on the Chinese Equity Market","Modeling and Forecasting Realized Volatility","A Simple Way to Estimate Bid-Ask Spreads from Daily High and Low Prices"]},{id:"announcement-events",title:{en:"Announcements and events",zh:"公告与事件"},titles:["Event Studies in Economics and Finance","Giving Content to Investor Sentiment: The Role of Media in the Stock Market","When Is a Liability Not a Liability? Textual Analysis, Dictionaries, and 10-Ks","Lazy Prices"]}],n=(e,t)=>t==="zh"?e.titleZh:e.sourceTitle||e.title,r=(e,t)=>t==="zh"?e.dataZh:e.data,s=(e,t)=>e.year==="living"?t==="zh"?"持续更新资料":"Living reference":e.year;export{s as a,i as b,r as c,a as p,n as r};
